window.SV_LIVROS={"1934":{"regioes":[{"nome":"White Hills","dono":"Prefeitura (dinheiro velho)","dif":6,"perigo":"Baixo","resumo":"Casarões vitorianos, velhas fortunas, o bonde, Santa Úrsula, o Jockey Club, o Banco Ashcroft e os Banhos Imperiais. Os crimes daqui aparecem nos testamentos, não nos jornais.","lugares":[["Mansão Ashcroft","30 cômodos, metade fechada para economizar carvão"],["Clube Pacífico","Clube de cavalheiros; ali se escolhe o próximo juiz"],["Sanatório de Santa Úrsula","Casa de repouso “para nervos”, janelas com grade decorada"],["Catedral da Graça","Onde White Hills se casa, se enterra e se confessa"],["Escritório Thorne & Vance","Testamentos, divórcios e acordos de silêncio"],["Estação do Bonde do Topo","Criados esperam ali às 5h da manhã"],["Casa de Penhores Fairbanks","Onde White Hills vende o que não pode admitir"]]},{"nome":"Downtown","dono":"Prefeitura e vereadores","dif":4,"perigo":"Baixo","resumo":"Bancos de granito, Prefeitura, Delegacia, Fórum, a Gazeta e a Praça do Fórum. Aqui as armas são canetas, e quem domina o arquivo domina a verdade.","lugares":[["Prefeitura","Cúpula de cobre, gabinete do prefeito no terceiro andar"],["Delegacia Central","Tijolo vermelho, celas no porão, depósito de provas sem inventário"],["Fórum Municipal","Advogados negociam penas no bebedouro"],["Necrotério Municipal","Gavetas numeradas e um legista bêbado"],["Redação da Gazeta da Manhã","Linotipos e um arquivo morto de fotografias"],["Hotel St. Clair","O sexto andar é de vereadores e “consultores”"],["Banco Pacific Trust","Sobreviveu a 1929 lavando o dinheiro do rum"],["Cartório de Registros","Empresas de fachada e donos reais de terrenos"],["Zachary Hobby Store","A banca verde-garrafa do Zack, na Praça do Fórum"]]},{"nome":"Black Rock e a Ponte","dono":"Delegacia Central (e quem a paga)","dif":7,"perigo":"Extremo","resumo":"A ilha-prisão e o canteiro da Black Rock Bridge, onde operários morrem toda semana. Onde os segredos da cidade vão morrer: no concreto, no estreito ou numa cela.","lugares":[["Canteiro Sul","Escritório da empreiteira, sempre de cortinas fechadas"],["Pilar 3","O pilar do concreto adulterado"],["Cantina do Canteiro","Apostas sobre quem cai na próxima semana"],["Barracão do Sindicato","Retratos dos mortos na parede"],["Cais de Black Rock","A lancha da prisão, duas vezes ao dia"],["Prisão de Pedra Negra","Celas de granito, solitária no subsolo"],["Farol da Ilha","Um faroleiro velho que se recusa a sair"]]},{"nome":"Chinatown","dono":"Tong da Flor de Lótus","dif":6,"perigo":"Médio","resumo":"Casas de chá, tongs, fumadouros e túneis desde 1906. Ninguém mente; simplesmente ninguém entende inglês quando não quer.","lugares":[["Casa de Chá do Dragão Jade","Nos fundos, a sala onde o Lótus recebe"],["Fumadouro da Rua Grant","Catres e fumaça doce"],["Salão de Fan-Tan Bom Augúrio","Atrás de uma loja de ervas"],["Sede das Seis Companhias","Um tribunal de clã no último piso"],["Lavanderia Wah Sing","Do Tong do Junco Negro"],["Missão Presbiteriana","Ada Pryor abriga mulheres fugidas"],["Templo de Tin Hau","Entrada para os túneis do St. Clair"],["Penhores Wong Shu","Tudo tem preço e nada tem origem"]]},{"nome":"Saint Edwiges","dono":"Família Moretti","dif":4,"perigo":"Alto","resumo":"Clubes, jazz, cassinos e speakeasies até as quatro da manhã.","lugares":[["Cassino Il Paradiso","Atrás da Chapelaria Moretti; Sal no mezanino"],["Farol Azul","Bar de fachada com porão de jazz e porta para os túneis"],["Clube Savoy","O único salão onde negros e brancos dançam juntos"],["Casa da Madame Celeste","Bordel elegante; o livro de clientes"],["Barbearia Fratelli","Barbearia de dia, banca de apostas de noite"],["Floricultura Bella Rosa","Agência de “acompanhantes”"],["Salão de Boxe Gallagher","Lutas clandestinas e capangas de aluguel"],["Pensão do Marinheiro","Quartos por hora; gente sem nome"]]},{"nome":"Embarcadouro e Píer 9","dono":"Irmandade (estiva) e Moretti (armazéns)","dif":5,"perigo":"Alto","resumo":"Docas, contrabando, sindicatos e uma neblina que esconde corpos até o amanhecer.","lugares":[["Píer 9","O píer do shape-up; os corpos boiam aqui"],["Galpão 14","“Frutas” de Mae Calloway e um alçapão para os túneis"],["Salão do Sindicato dos Estivadores","A lista negra pregada na parede"],["Armazéns Moretti (Píeres 12–18)","Homens de terno e cães"],["Bar do Otto","Onde os engenheiros da Ponte bebem"],["Capitania do Porto","Manifestos falsos"],["Cantina da Irmã Agnes","Sopa grátis para estivadores"],["Cais da Guarda Costeira","Noites em que a patrulha “está de folga”"]]},{"nome":"Distrito de Waterford","dono":"Irmandade Irlandesa","dif":3,"perigo":"Médio","resumo":"Cortiços, pubs, São Brendan e greves; a fábrica Waterford S.A. e o Golden Gate Motel.","lugares":[["Igreja de São Brendan","Armas escondidas na sacristia"],["Pub O’Rourke’s","Sede informal da Irmandade"],["Porão da Rua Dolores","Onde a Irmandade nasceu; tribunal e arsenal"],["Pensão da Sra. Rosales","A dona vê tudo da janela"],["Garagem Ferraro","Carros roubados, placas trocadas"],["Escola Paroquial Santa Brígida","As crianças contam tudo no recreio"],["Casa de Penhores Murphy","Agiota a 20% por semana"],["Hospital Gratuito Ashcroft","Feridos sem nome"]]},{"nome":"Esgotos e túneis","dono":"Ninguém — e todos","dif":"—","perigo":"Alto","resumo":"Cento e vinte quilômetros de galerias, metade fora de qualquer mapa oficial: a Grande Galeria, os túneis de tijolo de 1856 e as passagens de 1906.","lugares":[]},{"nome":"Estação Ferroviária Central","dono":"—","dif":"—","perigo":"Médio","resumo":"Trilhos, carregadores da Pullman, vigias ferroviários e a Vila Hoover à sombra dos vagões.","lugares":[]}],"npcs":[{"n":"Cornelius Ashcroft III","p":"Patriarca, banqueiro aposentado, 74 anos","r":"White Hills","d":"Construiu metade da cidade e perdeu metade da fortuna em 1929. Preso a uma cadeira de rodas depois de um derrame, ainda governa a família com a voz e com o testamento. Ama Teddy, o filho fraco, e despreza Vivian, que é parecida demais com ele.","v":"Fundou o hospital gratuito do Distrito de Waterford e o mantém em segredo, com o dinheiro que lhe resta.","pe":"Em 1906, pagou bombeiros para salvar White Hills e deixar Chinatown queimar. Ainda sonha com o fogo.","q":"Que o nome Ashcroft sobreviva, limpo, por mais uma geração.","t":"Morrer e ver Vivian herdar tudo.","a":"Clube Pacífico, juiz Hale; despreza Whitcombe, mas financia sua campanha. · Fala com:"},{"n":"Vivian Ashcroft","p":"Herdeira, 29 anos","r":"White Hills","d":"Linda, inteligente e encurralada. Foi criada para ser esposa decorativa e se recusou. Joga nas mesas de Moretti porque é o único lugar onde suas decisões têm consequência.","v":"Protege as criadas da casa dos avanços do pai e paga médicos para elas.","pe":"Atirou no irmão por acidente e deixou um tira sumir com o corpo, em vez de confessar.","q":"Liberdade: dinheiro próprio, longe de White Hills.","t":"A cadeia, mas mais ainda o sanatório de Santa Úrsula.","a":"Deve a Moretti; usa Brannigan; seduz quem for útil. · Fala com: Faro para Mentiras, Bajulação"},{"n":"Theodore \"Teddy\" Ashcroft","p":"Herdeiro desaparecido, 26 anos (morto)","r":"White Hills","d":"O filho gentil e covarde, que virou contador da empreiteira da Ponte para provar ao pai que sabia ganhar dinheiro. Descobriu a fraude e, pela primeira vez na vida, quis ser corajoso.","v":"Ia entregar o livro-caixa a Delgado, de graça.","pe":"Antes disso, tentou vendê-lo ao prefeito por 20 mil dólares. Whitcombe recusou.","q":"— (morto) Seu diário, escondido no Clube, revela os dois lados dele. Alianças: — · Fala com: Pesquisa (diário)","t":"— Juiz Lucius Hale J U I Z DA S U P R E M A C O R T E E S T A D U A L , 6 1 A N O S Jurista brilhante, autor de sentenças que protegeram trabalhadores contra os bancos. Também é o homem que decide, no Clube Pacífico, quais processos nunca chegarão à sua mesa.","a":""},{"n":"Juiz Lucius Hale","p":"Juiz da Suprema Corte Estadual, 61 anos","r":"White Hills","d":"Jurista brilhante, autor de sentenças que protegeram trabalhadores contra os bancos. Também é o homem que decide, no Clube Pacífico, quais processos nunca chegarão à sua mesa.","v":"Absolveu grevistas em 1932, contra a pressão de toda White Hills.","pe":"Aceita “doações” de Moretti para a fundação da esposa; em troca, Moretti nunca é julgado por ele.","q":"Ser lembrado como o maior juiz da Costa Oeste.","t":"Que uma única fotografia de Raymond Holt chegue à primeira página.","a":"Ashcroft, Moretti; inimigo íntimo do promotor Crane, seu ex-pupilo. · Fala com: Respeito,"},{"n":"Eleanor Whitcombe","p":"Esposa do prefeito, 48 anos","r":"White Hills","d":"Nascida em White Hills, casou-se com um homem de baixo para lhe dar um sobrenome e ganhou um marido infiel e ambicioso. É ela quem escreve os discursos e conta os votos.","v":"Dirige a Liga de Mulheres que distribui sopa no Distrito de Waterford; ela própria serve as filas.","pe":"Sabe da amante do marido (Lola Marchetti) e pagou Kowalski para “assustá-la”. Lola perdeu um bebê.","q":"Que o marido seja reeleito — e depois governador, e depois ela.","t":"Que descubram que a ideia da fraude da Ponte foi dela.","a":"Usa Whitcombe; financia Holt às escondidas; despreza White Hills que a criou. · Fala com:"},{"n":"Margaret \"Peg\" Donnelly","p":"Governanta da Mansão Ashcroft, 55 anos","r":"White Hills","d":"Irlandesa, viúva, trabalha para os Ashcroft há trinta anos. Criou Teddy e Vivian mais do que a própria mãe deles. Sabe onde cada osso da família está enterrado, inclusive o mais recente.","v":"Ama as crianças Ashcroft como se fossem dela; protegeria Vivian da forca.","pe":"Limpou o sangue de Teddy do tapete do escritório e queimou o vestido de Vivian. Passa informações de White Hills ao Padre Byrne, seu primo.","q":"Que Vivian fique livre, e que a Irmandade lhe garanta uma velhice digna.","t":"Ser descartada pela família como um móvel velho.","a":"Leal aos Ashcroft e à Irmandade — até que os dois entrem em conflito. · Fala com: Tranquilizar"},{"n":"Prefeito Edmund Whitcombe","p":"Prefeito de Saint Village, 52 anos","r":"Downtown","d":"Filho de um carroceiro do Distrito de Waterford, subiu de contínuo a vereador a prefeito em vinte anos de apertos de mão. Acredita sinceramente que é o único capaz de manter a cidade inteira — e que manter a cidade inteira justifica qualquer coisa.","v":"Criou o primeiro programa de empregos públicos da Costa Oeste; 4 mil homens trabalham na Ponte por causa dele.","pe":"Aceita o superfaturamento da Ponte, protege os cunhados e deixou Brannigan sumir com o corpo de Teddy.","q":"Ser reeleito e chegar a governador antes de envelhecer.","t":"Voltar a ser ninguém; ser preso na frente do filho.","a":"Precisa de Moretti e de Byrne ao mesmo tempo; é usado por Eleanor; teme Crane. · Fala com:"},{"n":"Capitão Harlan Voss","p":"Capitão da Delegacia Central, 57 anos","r":"Downtown","d":"Veterano da Grande Guerra, rosto de pedra e terço no bolso. Voss não se vê como corrupto: vê-se como o homem que impede uma guerra entre italianos e irlandeses que encheria a cidade de corpos. Recebe dos dois para que nenhum vença.","v":"Desde que assumiu, os homicídios caíram pela metade. É verdade.","pe":"Decide quem é preso por dinheiro; mandou atirar em grevistas em 1932; planta provas em quem ameaça o equilíbrio.","q":"Ser Chefe de Polícia e se aposentar com a cidade em paz.","t":"Que uma das máfias vença a outra; morrer sem confessar.","a":"Paga e é pago por todos; despreza Whitcombe; respeita Delgado e por isso o mantém no"},{"n":"Promotor Elliot Crane","p":"Promotor público, candidato a prefeito, 38 anos","r":"Downtown","d":"Reformista de óculos redondos, ex-pupilo do juiz Hale, que denuncia a corrupção em todos os discursos. Os jornais o chamam de “o Incorruptível”. Ele gosta do apelido.","v":"Leva a julgamento casos que nenhum outro promotor tocaria; já prendeu três tiras de Voss.","pe":"Sua campanha é financiada em segredo por Sal Moretti, que quer um prefeito capaz de destruir a Irmandade. Crane sabe e aceita.","q":"Ser prefeito e limpar a cidade — começando pelos irlandeses.","t":"Que descubram de onde vem o dinheiro; que Hale o renegue.","a":"Moretti (secreto), Delgado, Holt (quando convém); inimigo de Whitcombe e Voss. · Fala com:"},{"n":"Raymond Holt","p":"Editor-chefe da Gazeta da Manhã, 50 anos","r":"Downtown","d":"Gravata solta, cigarro eterno, cinismo de quem viu tudo duas vezes. Holt não acredita em verdade; acredita em circulação. Publica o que vende e cala o que paga, mas tem um limite que nem ele conhece até chegar nele.","v":"Recusou-se a publicar o nome de uma criança vítima de abuso, mesmo sob pressão de toda a redação.","pe":"Guarda um arquivo de fotos comprometedoras de metade da cidade e vende o silêncio; destruiu a carreira de um vereador honesto porque ele não comprou anúncios.","q":"Uma manchete que derrube um prefeito — e o prêmio que vem com ela.","t":"Ficar irrelevante; que o rádio mate o jornal.","a":"Eleanor Whitcombe (furos), Crane, Moretti (anúncios do Il Paradiso); inimigo de ninguém,"},{"n":"Hattie Brooks","p":"Repórter da Gazeta, 27 anos","r":"Downtown","d":"Uma das duas mulheres da redação policial, rápida no gatilho da câmera e mais rápida na língua. Quer um furo que a tire das páginas de culinária para sempre.","v":"Arrisca a vida para expor os acidentes da Ponte que ninguém quer publicar.","pe":"Tirou as fotos de Whitcombe com Lola e as vendeu a Holt, sabendo que Lola seria destruída junto.","q":"Seu nome assinando a primeira página.","t":"Voltar para a casa dos pais em Sacramento.","a":"Usa os PJs como fonte; desconfia de Holt; tem um caso com Delgado. · Fala com: Jargão de"},{"n":"Tenente Earl Brannigan","p":"Tenente de Homicídios, 44 anos","r":"Downtown","d":"Detetive competente que se perdeu nas mesas do Il Paradiso. Deve 6 mil dólares a Moretti e paga encerrando casos que incomodam a Prefeitura.","v":"Ainda resolve os homicídios de gente pobre que ninguém mais investiga; é o único tira que vai a enterros no Distrito de Waterford.","pe":"Sumiu com o corpo de Teddy Ashcroft e falsificou o relatório; já espancou um suspeito até a morte.","q":"Quitar a dívida e voltar a ser o detetive que era.","t":"Que Moretti cobre a dívida de outra forma; que a filha descubra.","a":"Prefeitura (por ordem), Moretti (por dívida), Vivian (por chantagem mútua). · Fala com: Jargão"},{"n":"Dr. Axel Lindqvist","p":"Legista municipal, 63 anos","r":"Downtown","d":"Sueco, ex-cirurgião militar, mãos firmes até a terceira dose. Faz as melhores autópsias da Costa Oeste e as vende para quem pagar.","v":"Faz autópsias gratuitas para famílias pobres e as assina como “causa natural” para que recebam o seguro.","pe":"Assinou o atestado de afogamento de Teddy; troca laudos por 5 dólares e por garrafas.","q":"Morrer em paz, de preferência bêbado.","t":"Sóbrio, lembrar-se de tudo o que assinou.","a":"Trabalha para qualquer um; tem carinho por Delgado. · Fala com: Medicina Legal, Bajulação"},{"n":"Frank Delgado","p":"Detetive no arquivo morto, 41 anos","r":"Downtown","d":"Mexicano-americano, filho de lavadeira, entrou na polícia para que ninguém mais tratasse sua mãe como seu pai foi tratado. Um dos últimos tiras limpos — e o mais isolado.","v":"Junta provas contra Voss há três anos, sem um centavo, arriscando a vida.","pe":"Para obter essas provas, plantou drogas em um informante dos Moretti e deixou um homem inocente ser preso por um ano.","q":"Ver Voss no banco dos réus.","t":"Que sua causa justa o transforme em Voss.","a":"Crane (aliado incômodo), Hattie Brooks (amante), Pell (favores). · Fala com: Jargão de Polícia,"},{"n":"Otto Brandt","p":"Engenheiro-chefe adjunto, 49 anos","r":"Black Rock e a Ponte","d":"Engenheiro alemão formado em Dresden, que projetou pontes no Reno antes de fugir dos nazistas. Sabe que o concreto do pilar 3 é areia da baía desde março e bebe gim no café da manhã para não pensar nisso.","v":"É o único engenheiro que sobe aos cabos todo dia para inspecionar; já salvou dois operários com as próprias mãos.","pe":"Assinou os laudos de qualidade do pilar 3 por 3 mil dólares. Mandou o dinheiro para a irmã em Berlim.","q":"Que a ponte não caia — e não ser o culpado se cair.","t":"Ser deportado; ver a ponte ruir com gente em cima.","a":"Chantageado pela empreiteira; procura os PJs em segredo (Caso 2). · Fala com: Arquitetura,"},{"n":"Harold Lyman","p":"Diretor da empreiteira Whitcombe-Lyman, 46 anos","r":"Black Rock e a Ponte","d":"Cunhado do prefeito, ex-vendedor de seguros, que ganhou o contrato da Ponte sem nunca ter construído uma garagem. É simpático, generoso com caridades e incapaz de entender por que alguém se importaria com um pouco de areia.","v":"Paga escola para os filhos dos operários mortos — do próprio bolso, sem publicidade.","pe":"Desvia um terço da verba da ponte; mandou demitir e colocar na lista negra todos que reclamaram.","q":"Terminar a ponte e se mudar para White Hills.","t":"Ir para Black Rock — que ele vê todo dia pela janela.","a":"Whitcombe (família), Moretti (fornecedor), Eleanor (que o despreza e o usa). · Fala com:"},{"n":"Seamus Doyle","p":"Presidente do Sindicato dos Ferreiros, 38 anos","r":"Black Rock e a Ponte","d":"Ferreiro irlandês de braços tatuados, sobrevivente de uma queda de 40 metros em Nova York. Fala pouco e é ouvido por quatro mil homens.","v":"Organizou o fundo de viúvas e enterra cada morto com caixão e missa, pagos pelo sindicato.","pe":"Recebe ordens do Padre Byrne e sabe que Byrne está chantageando o prefeito em vez de salvar os operários. Obedece porque precisa da Irmandade para não ser esmagado.","q":"Segurança nos cabos: rede de proteção e salário de risco.","t":"Que Byrne o descarte; que a greve fracasse e os homens passem fome.","a":"Leal à Irmandade, mas não a ponto de deixar a ponte cair. · Fala com: Tranquilizar, Política"},{"n":"Pedro Alvarado","p":"Operário morto, 24 anos","r":"Black Rock e a Ponte","d":"Rebitador mexicano que caiu do pilar 3 “por acidente” em janeiro. Ia denunciar o concreto adulterado no sindicato. Seu corpo nunca foi encontrado.","v":"Sustentava a mãe e quatro irmãos no Distrito de Waterford.","pe":"Antes de procurar o sindicato, tentou vender a informação à Gazeta por 200 dólares. Hattie Brooks recusou: “não é notícia ainda”.","q":"— (morto) Seu diário está na Pensão Rosales. Alianças: — · Fala com: Pesquisa (diário)","t":"—","a":""},{"n":"Diretor Warren Ashby","p":"Diretor da prisão de Black Rock, 60 anos","r":"Black Rock e a Ponte","d":"Ex-capelão militar que acredita genuinamente na reabilitação pelo trabalho. Criou a biblioteca e a oficina de carpintaria da ilha.","v":"Nenhum preso foi espancado até a morte sob sua direção, ao contrário do antecessor.","pe":"Aluga presos à empreiteira por 2 dólares por cabeça e embolsa metade; mantém em celas homens que Voss lhe pede para “guardar”.","q":"Aposentar-se como reformador; ter seu nome numa ala da prisão.","t":"Uma fuga, ou uma rebelião, nas vésperas da aposentadoria.","a":"Voss (envia presos), Lyman (aluga presos); simpatiza com Irmã Agnes. · Fala com: Respeito,"},{"n":"\"Dutch\" Kessler","p":"Preso nº 1187, ex-matador de Moretti, 42 anos","r":"Black Rock e a Ponte","d":"Holandês de Nova Jersey, assassino profissional condenado por um único crime que não cometeu. Matou nove homens para Moretti antes de ser entregue por ele à polícia. Lê Dostoiévski na biblioteca da prisão.","v":"Protege os presos mais jovens dos guardas e dos estupradores no pátio.","pe":"Matou nove homens por dinheiro, um deles na frente do filho.","q":"Vingança contra Moretti — ou um acordo que o tire da ilha.","t":"Morrer na prisão sem que ninguém saiba a verdade sobre Moretti.","a":"Sem aliados; aceita qualquer um que o ajude a fugir (evento de setembro da Linha do Tempo). ·"},{"n":"Sargento Hank Purcell","p":"Chefe da guarda de Black Rock, 51 anos","r":"Black Rock e a Ponte","d":"Guarda veterano de olhos cansados, que já viu presos morrerem afogados tentando fugir. Conhece cada cela e cada segredo da ilha.","v":"Leva cartas dos presos às famílias por conta própria.","pe":"Contrabandeia rum, cigarros e mensagens para dentro da prisão a mando de Mae Calloway; deixa os presos de Voss na solitária sem comida.","q":"Comprar um barco de pesca e nunca mais ver a ilha.","t":"Que Ashby descubra o contrabando; ser preso na própria prisão.","a":"Mae Calloway (pagamento), Voss (ordens), presos (respeito mútuo). · Fala com: Jargão de Polícia,"},{"n":"Ezra Pike","p":"Faroleiro da ilha, 78 anos","r":"Black Rock e a Ponte","d":"Velho marinheiro que mora no farol há quarenta anos e se recusou a sair quando ele foi automatizado. O Estado desistiu de despejá-lo.","v":"Viu tudo o que passou pela baía à noite e anota em seus diários de bordo, com hora e direção.","pe":"Vende essas informações para quem pagar: Mae, Moretti, o FBI. Às vezes para todos ao mesmo tempo.","q":"Morrer no farol, e não num asilo.","t":"Que alguém queime seus diários — ou que o queime junto com eles.","a":"Ninguém e todos; tem um fraco por Irmã Agnes, que lhe leva comida. · Fala com: Bajulação,"},{"n":"Lin Mei-Hua","p":"Dona da casa de chá, líder secreta do Lótus, 44 anos","r":"Chinatown","d":"Nascida em Saint Village, filha de um comerciante e de uma mulher vendida a um bordel. Educada na Missão, fala cantonês, inglês, italiano e francês. Oficialmente, o líder do Lótus é seu tio idoso; na prática, todas as decisões são dela.","v":"Manteve Chinatown longe da guerra entre italianos e irlandeses; financia em segredo a Missão que resgata mulheres dos bordéis.","pe":"Controla o comércio de ópio e mandou matar três homens do Junco Negro em 1932, incluindo um de 17 anos.","q":"Que Chinatown sobreviva à Lei de Exclusão; ser respeitada como líder em público, um dia.","t":"Que descubram que ela, uma mulher, comanda o tong — e que os velhos se voltem contra ela.","a":"Aliada ocasional de Moretti (ópio), parceira de Mae (túneis); paga Ruth Sayer. · Fala com:"},{"n":"Chan Wing-Sun","p":"Tio de Lin, líder oficial do Lótus, 71 anos","r":"Chinatown","d":"Ex-ferroviário que sobreviveu à construção da Central Pacific e ao incêndio de 1906. Sentado na casa de chá, recebe os visitantes, sorri e diz sim a tudo, depois deixa a sobrinha decidir.","v":"Ainda paga o enterro e o retorno dos ossos para a China de qualquer homem do bairro, sem perguntar o clã.","pe":"Em 1906, vendeu as filhas de vizinhos mortos no incêndio para pagar a reconstrução do tong.","q":"Morrer com honra e ter os ossos levados a Cantão.","t":"Ser lembrado pelo que fez em 1906.","a":"Protege Lin; respeitado pelas Seis Companhias. · Fala com: Respeito"},{"n":"Kwan Ah-Lee","p":"Líder do Tong do Junco Negro, 35 anos","r":"Chinatown","d":"Imigrante chegado em 1922 com papéis falsos, ambicioso e ressentido. Acha que o Lótus vendeu Chinatown aos brancos e quer substituí-lo.","v":"Paga salários dignos nas lavanderias e defendeu operários chineses agredidos pela polícia.","pe":"Trafica mulheres de Cantão para os bordéis de Saint Edwiges; aceita dinheiro da Irmandade para sabotar o ópio de Moretti.","q":"Comandar Chinatown e acabar com o Lótus.","t":"Ser deportado — ele é um “filho de papel” e os papéis podem ser revelados.","a":"Irmandade Irlandesa (armas e dinheiro); inimigo de Lin; usa Patrulheiro Dunne. · Fala com:"},{"n":"Ada Pryor","p":"Missionária presbiteriana, 39 anos","r":"Chinatown","d":"Escocesa de Glasgow, enviada pela igreja em 1919. Já resgatou 300 mulheres dos bordéis com a polícia, com machados e, quando necessário, com mentiras. Os tongs a chamam de “a Mãe Fantasma”.","v":"Arrisca a vida diariamente; nenhuma mulher que bateu à sua porta foi devolvida.","pe":"Converte as mulheres resgatadas à força e as casa com quem a Missão escolhe; entrega à polícia homens chineses com base em boatos.","q":"Fechar todos os bordéis de Chinatown.","t":"Que Lin Mei-Hua, sua aluna mais brilhante, seja o que ela suspeita que é.","a":"Recebe dinheiro de White Hills (Eleanor Whitcombe); tolerada pelo Lótus; inimiga do Junco"},{"n":"Detetive Ruth Sayer","p":"Detetive de Narcóticos, 36 anos","r":"Chinatown","d":"Uma das únicas mulheres detetives da cidade, designada para Chinatown porque nenhum homem queria o cargo. Conhece o bairro melhor que qualquer tira e é respeitada pelos velhos.","v":"Impediu a polícia de incendiar o bairro durante uma batida em 1931.","pe":"Guarda o ópio apreendido e o revende ao Lótus, que lhe paga uma quantia mensal.","q":"Pagar o sanatório do irmão, veterano de guerra viciado em morfina.","t":"Que o irmão morra; que Voss descubra quanto ela recebe.","a":"Lin Mei-Hua (pagamento), Voss (nominalmente), Delgado (amizade antiga). · Fala com: Jargão"},{"n":"Dr. Ng Tai-Po","p":"Herbalista e médico, 58 anos","r":"Chinatown","d":"Formado em medicina ocidental em Hong Kong, proibido de clinicar nos Estados Unidos. Atende na loja de ervas quem não pode ir ao hospital: chineses, mexicanos, prostitutas e baleados.","v":"Trata qualquer um, de graça se for preciso, e nunca faz perguntas.","pe":"Também não faz perguntas quando o Lótus lhe traz homens que precisam “desaparecer” e quando faz abortos para Saint Edwiges.","q":"Que seu diploma seja reconhecido; voltar a operar num hospital de verdade.","t":"Que um paciente morra e a polícia descubra a clínica.","a":"Neutro; o Lótus o protege; Lindqvist o respeita. · Fala com: Medicina Legal, Idiomas"},{"n":"Henry Lee","p":"Jovem advogado, 27 anos","r":"Chinatown","d":"Nascido em Saint Village, cidadão americano e formado em Berkeley — o primeiro advogado chinês da cidade. Defende imigrantes nos tribunais de deportação.","v":"Ganhou casos impossíveis; já impediu 40 deportações.","pe":"Falsifica certidões de nascimento para os “filhos de papel” das Seis Companhias, cobrando caro dos que podem pagar.","q":"Que os chineses de Saint Village sejam cidadãos de verdade.","t":"Ser cassado; trair o bairro por medo.","a":"Seis Companhias (clientes); o promotor Crane, que o vê como peão. · Fala com: Burocracia,"},{"n":"Wong Shu","p":"Penhorista, 63 anos","r":"Chinatown","d":"Homem de óculos grossos que compra tudo e nunca pergunta de onde veio. Sua loja é o banco dos pobres de Chinatown e o cemitério de provas da cidade.","v":"Empresta dinheiro sem juros às viúvas do bairro.","pe":"Compra objetos de mortos, armas de crimes e joias roubadas; guarda a arma de bolsa de Vivian Ashcroft e sabe o que ela significa.","q":"Uma loja na Rua Grant para o neto, com nome em inglês na fachada.","t":"Ser envolvido num crime de branco: um chinês não pode testemunhar, mas pode ser enforcado.","a":"Vende a quem pagar; deve favores ao Lótus. · Fala com: Bajulação, Jogatina"},{"n":"Don Salvatore \"Sal\" Moretti","p":"Chefe da Família Moretti, 60 anos","r":"Saint Edwiges","d":"Chegou da Sicília aos 12 anos, engraxou sapatos em Saint Edwiges e construiu um império com uma navalha e uma régua de contador. Fala baixo, cita Dante e trata cada um pelo nome. Sabe que a Lei Seca vai acabar e que, sem ela, sua família precisa virar respeitável ou morrer.","v":"Mantém um fundo para as viúvas da família e paga a faculdade de filhos de imigrantes italianos que nunca soube quem são.","pe":"Ordenou dezenas de mortes; entregou Dutch Kessler à polícia para fazer as pazes com Voss; financia em segredo o promotor Crane para destruir os irlandeses.","q":"Legalizar os cassinos e ver o neto formado em direito.","t":"Morrer como gângster, e não como homem de negócios; que Vincent destrua tudo.","a":"Voss (paga), Lin Mei-Hua (ópio), Crane (secreto), juiz Hale; inimigo mortal de Byrne. · Fala com:"},{"n":"Vincent Moretti","p":"Filho de Sal, 31 anos","r":"Saint Edwiges","d":"Educado em Stanford, elegante, impaciente. Acha que o pai é um velho que não entende o futuro. Quer transformar a família em empresa — mais rápido do que o pai permitiria.","v":"Foi ele quem convenceu o pai a parar com o tráfico de mulheres em 1931.","pe":"Vende informações à Irmandade para enfraquecer o pai e forçá-lo a se aposentar; não sabe que Byrne matou seu avô.","q":"Comandar a família e levá-la para Las Vegas.","t":"Que o pai descubra a traição; viver para sempre à sombra dele.","a":"Irmandade (secreta), Mae Calloway (negócios); despreza Kowalski. · Fala com: Bajulação,"},{"n":"Lola Marchetti","p":"Cantora do Farol Azul e do Clube Savoy, 30 anos","r":"Saint Edwiges","d":"Voz rouca, olhos tristes e um passado em Chicago que ela não discute. Amante do prefeito Whitcombe há dois anos. Perdeu um bebê depois de ser “assustada” por Kowalski a mando de Eleanor Whitcombe.","v":"Protege as dançarinas mais jovens, ensinando-as a não depender de nenhum homem.","pe":"Seduziu o prefeito por encomenda de Sal Moretti; passa a Sal tudo o que Whitcombe diz na cama.","q":"Vingança contra Eleanor; sair da cidade com dinheiro suficiente para nunca mais cantar.","t":"Que Moretti a descarte quando ela não for mais útil.","a":"Moretti (empregador), Whitcombe (amante), Hattie Brooks (desconfiança). · Fala com:"},{"n":"Gus Halloran","p":"Barman do Farol Azul, 45 anos","r":"Saint Edwiges","d":"Ex-pugilista peso médio de Boston, nariz quebrado três vezes, memória perfeita. Serve bebida ilegal com a calma de um padre.","v":"Já escondeu três pessoas perseguidas no porão do bar, arriscando tudo.","pe":"Deve 2 mil dólares aos Moretti e paga entregando informações sobre clientes, inclusive sobre amigos.","q":"Comprar o próprio bar quando a Lei Seca cair.","t":"Ser obrigado a escolher entre um amigo e a dívida.","a":"Moretti (dívida), Irmandade (é irlandês), PJs (se pagarem bem). · Fala com: Bajulação, Gíria das"},{"n":"Madame Celeste Duval","p":"Dona da Casa da Madame Celeste, 52 anos","r":"Saint Edwiges","d":"Nascida Mary Kowalczyk em Pittsburgh, reinventou-se como francesa em 1912. Sua casa é a mais discreta da cidade, e seu livro de clientes é o documento mais perigoso de Saint Village.","v":"Paga médico, escola e uma pensão para cada mulher que deixa sua casa; ninguém é forçado a ficar.","pe":"Chantageia clientes há vinte anos e já vendeu o nome de uma garota grávida ao pai dela, para que a “levassem de volta”.","q":"Aposentar-se em Paris de verdade.","t":"Que o livro seja roubado e ela, morta por ele.","a":"Paga Moretti; protegida por Pell e pelo juiz Hale (clientes). · Fala com: Bajulação, Respeito"},{"n":"Sargento \"Mão Pesada\" Kowalski","p":"Sargento de Saint Edwiges, 40 anos","r":"Saint Edwiges","d":"Polonês do Distrito de Waterford, ex-estivador, enorme. Coleta a propina dos clubes toda sexta e decide qual lugar sofre batida. Bate em quem não pode revidar.","v":"Sustenta sozinho a mãe doente e três irmãs; nunca bebe em serviço.","pe":"Espancou Lola Marchetti grávida a mando de Eleanor Whitcombe e não perdeu uma noite de sono.","q":"Ser tenente e ter uma casa com quintal no Distrito de Waterford.","t":"Que alguém mais forte cobre o que ele fez.","a":"Moretti, Voss, Eleanor Whitcombe (serviços); primo distante de Madame Celeste, que não sabe. ·"},{"n":"Clarence \"Cuff\" Baptiste","p":"Líder da orquestra do Clube Savoy, 38 anos","r":"Saint Edwiges","d":"Trompetista de Nova Orleans que tocou com os maiores e veio para o oeste fugir das leis Jim Crow. Sua orquestra enche o Savoy toda noite e lhe dá um poder que ninguém mais negro tem na cidade.","v":"Contrata músicos negros e garante que sejam pagos igual aos brancos; enfrentou Moretti para isso.","pe":"Vende heroína a outros músicos para manter a orquestra funcionando; já viu dois deles morrerem de overdose.","q":"Gravar um disco e tocar no Carnegie Hall.","t":"Ser linchado; que Saint Edwiges acabe junto com a Lei Seca.","a":"Moretti (empregador), Lin Mei-Hua (heroína), Lola (amizade). · Fala com: Respeito, Bajulação"},{"n":"Nick \"Moeda\" Santangelo","p":"Crupiê do Il Paradiso, 29 anos","r":"Saint Edwiges","d":"Mãos rápidas, sorriso fácil, sobrinho distante de Sal. Sabe exatamente quem deve quanto à família — e quanto vale essa informação.","v":"Perdoa discretamente as dívidas de jogo de operários desesperados, mexendo nos registros.","pe":"Rouba o cofre do cassino há seis meses, centavo por centavo; já culpou um garçom, que desapareceu.","q":"Juntar 10 mil dólares e fugir para Havana com uma dançarina.","t":"Que Sal descubra o roubo (gancho do Caso 3 da tabela SV.8).","a":"Vincent Moretti (amigo), dançarinas do Savoy; teme todos os outros. · Fala com: Jogatina,"},{"n":"Declan \"o Padre\" Byrne","p":"Líder da Irmandade Irlandesa, 47 anos","r":"Embarcadouro e Píer 9","d":"Ex-seminarista de Cork que trocou a batina pela causa operária depois de ver estivadores morrerem de fome no shape-up. Fala em salmos e em salários. Para quatro mil homens, ele é a única voz que os defende. Para Sal Moretti, é o homem que matou seu pai.","v":"Criou o fundo de greve, a escola noturna e o seguro para viúvas do sindicato; tirou milhares de famílias da miséria.","pe":"Matou Don Vito Moretti, pai de Sal e avô de Vincent, com as próprias mãos na guerra de 1929; chantageia o prefeito com o concreto da Ponte em vez de salvar os operários; usa o Junco Negro para traficar armas.","q":"Controle total das docas — e, com ele, da cidade.","t":"Que seus homens descubram que ele negocia com o prefeito às escondidas.","a":"Seamus Doyle, Peg Donnelly, Kwan Ah-Lee, Vincent Moretti (secreto), Dunne. · Fala com:"},{"n":"\"Rainha\" Mae Calloway","p":"Contrabandista de rum, 45 anos","r":"Embarcadouro e Píer 9","d":"Viúva de um capitão norueguês, herdou o barco e a rota do marido e fez dela a maior rede de contrabando da Costa Oeste. Pilota as próprias lanchas, atira melhor que seus homens e não paga ninguém em dia.","v":"Emprega viúvas e filhos de pescadores mortos; nunca vendeu rum envenenado, ao contrário dos rivais.","pe":"Está vendendo a rota ao FBI em troca de imunidade, o que vai entregar à cadeia todos que trabalham para ela.","q":"Sair do contrabando antes da Lei Seca acabar, com um banco no seu nome.","t":"Prisão; ser morta por Moretti se ele descobrir a delação.","a":"Lin Mei-Hua (túneis), Banco Pacific Trust, Capitão Hollis, Sargento Purcell, Agente Prescott"},{"n":"Tommy \"Faísca\" Riordan","p":"Pistoleiro da Irmandade, 22 anos","r":"Embarcadouro e Píer 9","d":"Nascido no Distrito de Waterford, órfão de um estivador esmagado por uma carga. Byrne o criou como um filho e o transformou em arma. Tommy quer ser lenda — e tem medo de ser só mais um nome na parede do sindicato.","v":"Dá metade do que ganha à mãe de um amigo morto.","pe":"Já matou quatro homens, um deles pelas costas.","q":"Casar-se com Angela Moretti, filha de Sal, e fugir.","t":"Que Byrne descubra o romance; que Angela o veja matar.","a":"Leal a Byrne até que Angela peça o contrário. · Fala com: Intimidação, Bajulação (com Angela)"},{"n":"Patrulheiro Mickey Dunne","p":"Patrulheiro do Embarcadouro, 34 anos","r":"Embarcadouro e Píer 9","d":"Primo do Padre Byrne, uniforme sempre amarrotado, mão sempre aberta. Patrulha o cais há dez anos sem fazer uma única prisão de irlandês.","v":"Avisa as famílias quando um estivador morre, antes que leiam no jornal.","pe":"Encobre os crimes da Irmandade e entregou à polícia dois fura-greves que depois apareceram mortos.","q":"Ver a Irmandade no poder e ganhar uma promoção.","t":"Que a Corregedoria de Garrity o use para chegar a Byrne.","a":"Byrne (família), Kwan Ah-Lee (troca de favores), Voss (nominalmente). · Fala com: Jargão de"},{"n":"Big Lou Ferraro","p":"Capataz dos armazéns Moretti, 50 anos","r":"Embarcadouro e Píer 9","d":"Italiano enorme e cordial, que trata seus homens como família e os paga melhor que a Irmandade. Recruta fura-greves entre italianos e mexicanos desempregados.","v":"Nunca abandona um homem ferido; pagou o tratamento de um estivador irlandês ferido nos armazéns.","pe":"Comanda os fura-greves que enfrentam os grevistas com barras de ferro; fez desaparecer um ladrão de carga no ano passado.","q":"Que a greve fracasse e ele ganhe um armazém próprio.","t":"Ser o próximo corpo no Píer 9.","a":"Moretti (lealdade), Garagem Ferraro (é seu irmão). · Fala com: Respeito, Intimidação"},{"n":"Irmã Agnes O’Malley","p":"Freira da Igreja de São Brendan, 56 anos","r":"Embarcadouro e Píer 9","d":"Dirige a cantina dos estivadores e conhece o nome de cada filho do cais. Despreza Byrne por ter trocado Deus pela política e despreza Moretti por ter trocado Deus pelo dinheiro.","v":"Alimenta trezentos homens por dia; já levou presos de Black Rock ao Dr. Marlowe para salvá-los da solitária.","pe":"Escreve cartas anônimas ao FBI denunciando irlandeses e italianos, mesmo sabendo que inocentes vão cair junto.","q":"Ver o cais livre dos dois — mesmo que isso custe a greve.","t":"Que descubram as cartas e queimem a igreja.","a":"Marlowe, Ezra Pike, Sra. Rosales; ninguém nas facções. · Fala com: Tranquilizar"},{"n":"Capitão Hollis","p":"Comandante da Guarda Costeira local, 58 anos","r":"Embarcadouro e Píer 9","d":"Oficial de cabelos brancos, trinta anos de mar, a um ano da aposentadoria. Conhece cada corrente da baía e cada lancha que a atravessa.","v":"Já salvou dezenas de pescadores de naufrágios, inclusive contrabandistas que pediram socorro.","pe":"Recebe de Mae Calloway para estar de folga nas noites certas; deixou um contrabandista rival se afogar.","q":"Aposentar-se com pensão integral e uma casa na costa.","t":"Que o FBI audite seus horários.","a":"Mae Calloway (pagamento), Agente Prescott (que o vigia). · Fala com: Respeito, Burocracia"},{"n":"Rosa Benedetti","p":"Viúva de estivador, 28 anos","r":"Embarcadouro e Píer 9","d":"Seu marido “caiu” de um guindaste no mês passado. Deixou um bilhete dizendo que tinha visto algo no Galpão 14. Rosa não acredita em acidente e não tem dinheiro para um advogado.","v":"Coragem para fazer perguntas que ninguém mais faz no cais.","pe":"Foi amante de Big Lou Ferraro antes de se casar; sabe que o marido descobriu e o odiava por isso.","q":"Justiça — ou ao menos a indenização para os três filhos.","t":"Que a verdade seja pior do que ela imagina.","a":"Ninguém; procura os PJs (gancho 1 da tabela SV.8). · Fala com: Tranquilizar, Faro para Mentiras"},{"n":"Padre Michael Feeney","p":"Pároco de São Brendan, 63 anos","r":"Distrito de Waterford","d":"Velho padre de Galway que batizou metade do bairro e enterrou a outra metade. Foi professor do jovem Declan Byrne no seminário e o viu trocar Deus pela causa.","v":"Abre a Igreja para dormir a quem não tem onde; nunca entregou ninguém à polícia.","pe":"Guarda armas da Irmandade na sacristia e ouviu Byrne confessar o assassinato do velho Vito Moretti — e o absolveu.","q":"Que Byrne volte para Deus antes que seja tarde.","t":"Ter de escolher entre o segredo da confissão e uma vida.","a":"Ama Byrne como filho; tolera Irmã Agnes, que o critica. · Fala com: Tranquilizar, Respeito"},{"n":"Kathleen Byrne","p":"Irmã do Padre Byrne, 42 anos","r":"Distrito de Waterford","d":"Viúva de um estivador, mãe de cinco, dona de uma pequena mercearia. É a voz das mulheres do bairro e a única pessoa que Declan ainda escuta.","v":"Alimenta fiado metade da rua e organiza as mães quando a polícia invade.","pe":"Foi ela quem entregou à Irmandade o nome do fura- greve que apareceu morto em 1932; nunca se arrependeu.","q":"Que os filhos não terminem no cais nem no cemitério.","t":"Que o irmão a faça escolher entre ele e os filhos — o mais velho quer entrar na Irmandade.","a":"Declan (irmão), Peg Donnelly (prima), Irmã Agnes (desconfiança mútua). · Fala com:"},{"n":"Dolores Rosales","p":"Dona de pensão, 50 anos","r":"Distrito de Waterford","d":"Viúva mexicana, terço na mão e olhos na janela. Hospedou Pedro Alvarado e esconde um sindicalista procurado no sótão.","v":"Hospeda de graça quem chega à cidade sem nada, sem perguntar a origem.","pe":"Vende informações sobre seus hóspedes ao Patrulheiro Dunne para não ser despejada pela Irmandade, dona do prédio.","q":"Que os mexicanos tenham voz no sindicato.","t":"Ser despejada; ser descoberta por quem ela entrega.","a":"Irmã Agnes, Pedro Alvarado (falecido); paga a Irmandade. · Fala com: Tranquilizar, Idiomas"},{"n":"Seán Murphy","p":"Agiota e penhorista, 55 anos","r":"Distrito de Waterford","d":"Homem gordo e jovial que empresta a quem ninguém mais empresta, a juros que ninguém mais cobra. Conhece a miséria de cada família e a chama de “clientela”.","v":"É a única fonte de crédito no bairro; sem ele, muitas famílias passariam fome antes do pagamento.","pe":"Cobra 20% por semana; manda quebrar dedos de quem atrasa; repassa um terço à Irmandade.","q":"Comprar um pub e virar respeitável.","t":"Que Byrne decida que ele se tornou um constrangimento.","a":"Irmandade (paga), Mae Calloway (lava dinheiro). · Fala com: Intimidação, Jogatina"},{"n":"Bridget \"Biddy\" Riordan","p":"Mãe adotiva de Tommy Riordan, 61 anos","r":"Distrito de Waterford","d":"Lavadeira que criou Tommy depois que o pai dele morreu no cais. Sabe que ele mata para Byrne e reza por ele todas as noites.","v":"Criou sete crianças que não eram suas; nunca recusou um prato.","pe":"Esconde a arma de Tommy embaixo do colchão e mentiu à polícia três vezes por ele.","q":"Que Tommy saia da Irmandade vivo.","t":"Ver Tommy no Píer 9.","a":"Leal a Tommy acima de tudo, inclusive de Byrne. · Fala com: Tranquilizar"},{"n":"Jerzy Kowalski","p":"Pai do Sargento Kowalski, 70 anos","r":"Distrito de Waterford","d":"Velho fundidor polonês, mãos queimadas, que mora numa casa de madeira na beirada do Distrito de Waterford. Envergonha-se do filho tira e se orgulha das netas.","v":"Ensinou o ofício a dezenas de jovens do bairro, sem cobrar.","pe":"Sabe o que o filho fez a Lola Marchetti e nunca disse nada; aceita o dinheiro sujo que o filho traz para casa.","q":"Que as netas estudem e saiam do bairro.","t":"Que o filho seja morto pelos irlandeses ou preso pelos federais.","a":"Neutro; respeitado pelos irlandeses; temido pelo próprio filho. · Fala com: Respeito, Idiomas"},{"n":"Liam Doherty","p":"Organizador sindical, 29 anos","r":"Distrito de Waterford","d":"Jovem idealista que voltou de Nova York com ideias socialistas e um livro de Marx no bolso. Quer uma greve geral de verdade, não uma chantagem de Byrne.","v":"Fala a verdade aos operários, inclusive sobre Byrne; é o único que defende a entrada dos mexicanos no sindicato.","pe":"Está disposto a explodir um armazém de Moretti para provocar a greve, mesmo que um vigia morra.","q":"Uma greve geral que mude a cidade, com ou sem Byrne.","t":"Que Byrne o mande matar por desafiá-lo.","a":"Rosales (esconde-o), Irmã Agnes; inimigo silencioso de Byrne. · Fala com: Política, Tranquilizar"},{"n":"Angela Moretti","p":"Filha de Sal Moretti, 20 anos","r":"Distrito de Waterford","d":"A filha caçula de Sal, estudante de enfermagem no Hospital Gratuito Ashcroft, onde vai disfarçada para ver Tommy Riordan. Corajosa, ingênua e teimosa como o pai.","v":"Trata feridos irlandeses e italianos no hospital sem distinção.","pe":"Mente para o pai, para Tommy e para si mesma: sabe o que Tommy faz e finge não saber.","q":"Fugir com Tommy para Los Angeles.","t":"Ser a causa de uma guerra entre as duas famílias.","a":"Tommy (amor), Dr. Ng (aprendizado); o pai ignora tudo. · Fala com: Tranquilizar, Bajulação"},{"n":"Rita \"Lanterna\" Mendez","p":"Chefe dos ratos de túnel, 26 anos","r":"Esgotos e túneis","d":"Ex-operária de fábrica de conservas, demitida em 1931. Organizou os catadores dos esgotos como uma pequena guilda: dividem o que acham e cobram pedágio de quem passa.","v":"Ninguém do grupo dela passa fome","pe":"Cobra caro de quem precisa fugir, e às vezes entrega a fuga a quem paga mais","q":"Um teto de verdade para os doze que dependem dela","t":"A polícia inundar as galerias com as bombas","a":"Mae Calloway (pedágio), Lin Mei-Hua (trégua) · Fala com: Gíria das Ruas, Barganha"},{"n":"Inspetor Walter Doane","p":"Inspetor de saneamento da Prefeitura, 58 anos","r":"Esgotos e túneis","d":"O único funcionário da cidade que conhece os mapas reais dos esgotos. Bebe café com gim e fala de tubulações como quem fala de poesia.","v":"Avisa o Distrito de Waterford quando a maré vai alagar os porões","pe":"Vende cópias dos mapas a quem pagar, inclusive à Irmandade e a Moretti","q":"Uma aposentadoria antes de a Grande Galeria rachar","t":"Que descubram que ele vendeu o mapa usado num assalto","a":"Prefeitura (salário), Mae Calloway (dinheiro) · Fala com: Burocracia, Arquitetura"},{"n":"Samuel Price","p":"Carregador da Pullman, 44 anos","r":"Estação Ferroviária Central","d":"Vinte anos carregando malas e ouvindo segredos nos vagões-leito. Sabe ler um passageiro em três segundos.","v":"Paga a faculdade de direito do filho com gorjetas","pe":"Vende o que vê aos Moretti, que controlam os carregadores de bagagem","q":"Ver o filho advogado","t":"Ser o próximo corpo nos trilhos","a":"Moretti (por medo), Sindicato dos Carregadores (por lealdade) · Fala com: Bajulação, Respeito"},{"n":"Capitão Boyd Harlan","p":"Chefe dos vigias ferroviários, 50 anos","r":"Estação Ferroviária Central","d":"Ex-sargento do Texas, chapéu de vaqueiro e cassetete de carvalho. Comanda os “touros” do pátio e acredita que andarilhos são ladrões até prova em contrário.","v":"Nunca deixou um trem sair com uma criança perdida a bordo","pe":"Espancou até a morte um andarilho de 15 anos em 1932","q":"Que a ferrovia o promova a superintendente","t":"Que alguém da Vila Hoover testemunhe","a":"Southern Pacific, Capitão Voss · Fala com: Jargão de Polícia, Intimidação"},{"n":"Mãe Josephine","p":"Líder da Vila Hoover, 60 anos","r":"Estação Ferroviária Central","d":"Viúva de um fazendeiro de Oklahoma, chegou num vagão de carga com sete netos. Organizou o acampamento com regras próprias: ninguém rouba de ninguém, e todo mundo divide a sopa.","v":"Duzentas pessoas comem graças a ela","pe":"Esconde na Vila um homem procurado por assassinato, porque ele salvou seu neto","q":"Casas de verdade para todos antes do inverno","t":"Que a polícia queime a Vila, como em Seattle","a":"Irmã Agnes, Liam Doherty · Fala com: Tranquilizar"},{"n":"Hank Dorsey","p":"Sinaleiro da torre, 37 anos","r":"Estação Ferroviária Central","d":"Ferroviário do sindicato, controla as agulhas do pátio. Calado, metódico, leal à Irmandade.","v":"Impediu duas colisões com o próprio corpo","pe":"Desvia vagões de carga para os armazéns de quem paga","q":"Que a greve chegue à ferrovia","t":"Um acidente com mortos na sua torre","a":"Irmandade, Sindicato Ferroviário · Fala com: Gíria das Ruas, Política"},{"n":"Agente Clara Wynn","p":"Agente federal infiltrada, 31 anos","r":"Estação Ferroviária Central","d":"Trabalha na bilheteria como funcionária comum, mas é os olhos do agente Prescott na estação. Conhece cada passageiro que compra passagem só de ida.","v":"Protegeu uma testemunha federal com a própria vida","pe":"Lê a correspondência dos colegas e entrega amigos para subir na carreira","q":"Ser a primeira mulher agente de campo do FBI","t":"Ser descoberta pelos Moretti","a":"Agente Prescott; ninguém mais · Fala com: Burocracia, Faro para Mentiras"}],"textos":{"White Hills":"REGIÃO EM PROFUNDIDADE · 1 DE 7\nWhite Hills\nWhite Hills é a crista mais íngreme de Saint Village, e o dinheiro sobe por ela como água subindo ao contrário.\nO bonde da Rua Califórnia leva quatro minutos de Downtown até o topo; os criados levam quarenta, a pé,\nporque a passagem custa o que eles ganham por hora. No alto, casarões vitorianos de madeira pintada, salvos\ndo incêndio de 1906 por mangueiras pagas a preço de ouro enquanto Chinatown ardia, olham a baía por\njanelas que nunca são abertas para a neblina.\nAs fortunas daqui nasceram na Corrida do Ouro, nas ferrovias e nos navios de carga, e morreram em parte no\ncrash de 1929. Metade das famílias ainda é rica; a outra metade finge, vendendo prataria às escondidas para\nWong Shu em Chinatown e alugando quartos dos fundos a hóspedes “discretos”. Ninguém em White Hills\nadmite estar falido, porque estar falido aqui é pior que estar morto: os mortos ao menos recebem flores.\nWhite Hills não tem gangue. Não precisa. Tem advogados, juízes que jantam às quintas no Clube Pacífico e um\ndelegado de distrito, o Capitão Walter Pell, cuja única função é garantir que nenhuma viatura suba a colina\nsem ser convidada. Os crimes daqui não aparecem no jornal:\naparecem nos testamentos, nos casamentos apressados e nos sanatórios do interior onde filhas “nervosas”\npassam temporadas.\nPara os investigadores, White Hills é o território mais perigoso de todos, não pela violência, mas pela memória\nlonga. Um tira que ofende um morador de White Hills não é demitido; é transferido para Black Rock. Um\ndetetive particular não é espancado; perde a licença por um erro de papelada ninguém consegue explicar.\nque\nCRÔNICA · CINCO DA MANHÃ NA WHITE HILLS Nora Keane, 19 anos, copeira da Mansão Vance\nO primeiro bonde passa às 5h10, mas eu não pego bonde. Subo a Rua Califórnia a pé, no escuro, com as outras meninas do\nDistrito de Waterford, e a gente conta os degraus para não pensar no frio. São 412. Na porta de serviço, a Sra. Hargrove\nconfere minhas unhas e meu avental antes de me deixar entrar na cozinha.\nÀs seis acendo as lareiras dos quartos sem fazer barulho. Lá em cima, eles dormem como gente que nunca deveu nada a\nninguém. No quarto do Sr. Vance tem sempre um copo de uísque pela metade e uma carta que ele não terminou. Não leio. A\nPeg Donnelly, da casa dos Ashcroft, me ensinou: “a gente não lê, menina, a gente lembra”.\nOntem à noite houve jantar. Lavei sangue de uma toalha de linho branco. A patroa disse que foi vinho. Era sangue, eu sei\ncomo o sangue sai da água fria. Dobrei a toalha e guardei na gaveta de baixo, como ela mandou. Ganho quatro dólares por\nsemana. Mando três para casa. O outro eu guardo, porque um dia alguém vai me perguntar sobre aquela toalha, e eu quero\nsaber quanto vale a minha memória.\nC heguei de Cork em 1904 com uma carta de recomendação de um padre que nunca tinha me visto e um baú de\nfolha com as iniciais da minha mãe. A velha Sra. Ashcroft me contratou para a rouparia. Nos primeiros dois\nanos eu não subi ao andar de cima uma única vez. Conhecia a família pelos lençóis: quem dormia mal, quem\nsangrava pelo nariz, quem levava uma visita para o quarto às terças.\nHoje sou governanta. Tenho as chaves de tudo, menos da biblioteca do Sr. Cornelius, onde ele guarda o testamento e\numa garrafa de Armagnac que não oferece a ninguém. Já vi esse testamento ser mudado três vezes. Na última, ele\nmandou chamar o advogado da Thorne & Vance às onze da noite e eu servi chá aos dois até as duas. Não me pediram\npara sair. Nesta casa, ninguém pede à governanta que saia de uma sala. Esquecem que estou ali.\nÀs quintas, desço a ladeira de bonde e vou ao Distrito de Waterford comprar pão na mercearia da minha prima\nKathleen. Ela me pergunta como vai a família, e eu conto. Conto tudo. Ela embrulha o pão em papel de jornal e, na\nsemana seguinte, alguma coisa que eu contei aparece num lugar onde não devia. Eu sei para quem ela conta.\nContinuo comprando o pão.\nP E G D O N N E L L Y, G O V E R N A N T A D A M A N S Ã O A S H C R O F T\nO QUE MANTÉM A WHITE HILLS DE PÉ\nTabela SV.CA.1 · Poder em White Hills\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nO dinheiro\nvelho\nEmpréstimos, hipotecas e cadeiras no conselho dos bancos\nde Downtown\nDo silêncio dos criados e dos contadores\nO Clube\nPacífico\nAli se escolhe o próximo juiz, o próximo vereador e o\npróximo bode expiatório\nDo rum de Mae Calloway e das mesas de\nMoretti\nA Prefeitura · Whitcombe sobe a colina para pedir bênção e dinheiro de\ncampanha\nDe White Hills, que pode trocá-lo pelo\npromotor Crane\nOs criados · Ouvem tudo, entram em todos os quartos, lavam todo\nsangue\nDo salário — e de serem invisíveis\nLUGARES DA WHITE HILLS\nTabela SV.CA.2 · Endereços de White Hills\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nMansão Ashcroft · Casarão de 30 cômodos, metade fechada para\neconomizar carvão; os retratos de família escondem\nmanchas na parede onde havia quadros vendidos\nA família está falida; Vivian deve ao\nIl Paradiso; o testamento do velho\nAshcroft foi alterado\nClube Pacífico · Clube de cavalheiros com biblioteca, sala de bilhar e um\nbar que, oficialmente, serve só água tônica\nQuem jantou com quem; os\nacordos da Ponte; o nome do\npróximo juiz\nSanatório de Santa\nÚrsula\nCasa de repouso “para nervos” no topo da colina;\njanelas com grade decorada\nFilhas, esposas e irmãos internados\npor saberem demais\nCatedral da Graça · Catedral episcopal onde White Hills se casa, se enterra e\nse confessa aos domingos\nRegistros de batismo de filhos que\n“não existem”\nEscritório Thorne\n&amp; Vance\nAdvocacia que redige os testamentos, divórcios e\nacordos de silêncio de White Hills\nCópias de acordos de silêncio;\nquem pagou para quem calar\nEstação do Bonde do\nTopo\nPonto final do bonde; criados esperam ali às 5h da\nmanhã\nO que os patrões fizeram na noite\nanterior\nCasa de Penhores\nFairbanks\nLoja “de antiguidades” discreta na encosta, onde White\nHills vende o que não pode admitir ter vendido\nQuem está falido; joias de família\ntrocadas por imitações\nGENTE DA WHITE HILLS\nNinguém aqui é inocente e ninguém é monstro. Cada um tem algo que ama, algo que fez para protegê-lo e\nalgo que faria de novo. Use as quatro linhas de cada perfil — virtude, pecado, quer e teme — para interpretá-\nlos e para decidir de que lado ficam quando a situação muda.\nCornelius Ashcroft III\nPAT R I A R C A , B A N Q U E I R O A P O S E N T A D O, 74 A N O S\nConstruiu metade da cidade e perdeu metade da fortuna em 1929. Preso a uma cadeira de rodas depois\nde um derrame, ainda governa a família com a voz e com o testamento. Ama Teddy, o filho fraco, e\ndespreza Vivian, que é parecida demais com ele.\nVIRTUDE\nFundou o hospital gratuito do Distrito de Waterford e o\nmantém em segredo, com o dinheiro que lhe resta.\nP ECADO\nEm 1906, pagou bombeiros para salvar White Hills e\ndeixar Chinatown queimar. Ainda sonha com o fogo.\nQUER\nQue o nome Ashcroft sobreviva, limpo, por mais uma\ngeração.\nTEM E\nMorrer e ver Vivian herdar tudo.\nAlianças: Clube Pacífico, juiz Hale; despreza Whitcombe, mas financia sua campanha. · Fala com:\nRespeito, Burocracia\nVivian Ashcroft\nH E R D E I R A , 2 9 A N O S , C L I E N T E D O C A S O 1\nLinda, inteligente e encurralada. Foi criada para ser esposa decorativa e se recusou. Joga nas mesas de\nMoretti porque é o único lugar onde suas decisões têm consequência.\nVIRTUDE\nProtege as criadas da casa dos avanços do pai e paga\nmédicos para elas.\nP ECADO\nAtirou no irmão por acidente e deixou um tira sumir\ncom o corpo, em vez de confessar.\nQUER\nLiberdade: dinheiro próprio, longe de White Hills.\nTEM E\nA cadeia, mas mais ainda o sanatório de Santa Úrsula.\nAlianças: Deve a Moretti; usa Brannigan; seduz quem for útil. · Fala com: Faro para Mentiras, Bajulação\nTheodore “Teddy” Ashcroft\nH E R D E I R O D E S A PA R E C I D O, 2 6 A N O S ( M O R T O )\nO filho gentil e covarde, que virou contador da empreiteira da Ponte para provar ao pai que sabia ganhar\ndinheiro. Descobriu a fraude e, pela primeira vez na vida, quis ser corajoso.\nVIRTUDE\nIa entregar o livro-caixa a Delgado, de graça.\nP ECADO\nAntes disso, tentou vendê-lo ao prefeito por 20 mil\ndólares. Whitcombe recusou.\nQUER\n— (morto) Seu diário, escondido no Clube, revela os dois\nlados dele. Alianças: — · Fala com: Pesquisa (diário)\nTEM E\n—\nJuiz Lucius Hale\nJ U I Z DA S U P R E M A C O R T E E S T A D U A L , 6 1 A N O S\nJurista brilhante, autor de sentenças que protegeram trabalhadores contra os bancos. Também é o\nhomem que decide, no Clube Pacífico, quais processos nunca chegarão à sua mesa.\nVIRTUDE\nAbsolveu grevistas em 1932, contra a pressão de toda\nWhite Hills.\nP ECADO\nAceita “doações” de Moretti para a fundação da esposa;\nem troca, Moretti nunca é julgado por ele.\nQUER\nSer lembrado como o maior juiz da Costa Oeste.\nTEM E\nQue uma única fotografia de Raymond Holt chegue à\nprimeira página.\nAlianças: Ashcroft, Moretti; inimigo íntimo do promotor Crane, seu ex-pupilo. · Fala com: Respeito,\nJargão de Polícia (Direito)\nEleanor Whitcombe\nE S P O S A D O P R E F E I T O, 4 8 A N O S\nNascida em White Hills, casou-se com um homem de baixo para lhe dar um sobrenome e ganhou um\nmarido infiel e ambicioso. É ela quem escreve os discursos e conta os votos.\nVIRTUDE\nDirige a Liga de Mulheres que distribui sopa no Distrito\nde Waterford; ela própria serve as filas.\nP ECADO\nSabe da amante do marido (Lola Marchetti) e pagou\nKowalski para “assustá-la”. Lola perdeu um bebê.\nQUER\nQue o marido seja reeleito — e depois governador, e\ndepois ela.\nTEM E\nQue descubram que a ideia da fraude da Ponte foi dela.\nAlianças: Usa Whitcombe; financia Holt às escondidas; despreza White Hills que a criou. · Fala com:\nBajulação, Política\nDr. Augustin Marlowe\nD I R E T O R D O S A N AT Ó R I O D E S A N T A Ú R S U L A\nPsiquiatra formado em Viena, culto, cansado. Acredita sinceramente na cura pela palavra e trata seus\npacientes com mais dignidade que qualquer hospital público.\nVIRTUDE\nRecusa eletrochoque e lobotomia, mesmo quando as\nfamílias pagam a mais.\nP ECADO\nAceita internar pessoas sãs se a família pagar; diz a si\nmesmo que lá dentro elas estão mais seguras do que lá\nfora.\nQUER\nManter o sanatório aberto e independente.\nTEM E\nQue uma paciente sã fuja e conte tudo.\nAlianças: Serve White Hills; secretamente protege Irmã Agnes, que lhe traz pacientes do Distrito de\nWaterford. · Fala com: Psicologia, Tranquilizar\nMargaret “Peg” Donnelly\nG O V E R N A N T A DA M A N S ÃO A S H C R O F T , 5 5 A N O S\nIrlandesa, viúva, trabalha para os Ashcroft há trinta anos. Criou Teddy e Vivian mais do que a própria\nmãe deles. Sabe onde cada osso da família está enterrado, inclusive o mais recente.\nVIRTUDE\nAma as crianças Ashcroft como se fossem dela;\nprotegeria Vivian da forca.\nP ECADO\nLimpou o sangue de Teddy do tapete do escritório e\nqueimou o vestido de Vivian. Passa informações de\nWhite Hills ao Padre Byrne, seu primo.\nQUER\nQue Vivian fique livre, e que a Irmandade lhe garanta\numa velhice digna.\nTEM E\nSer descartada pela família como um móvel velho.\nAlianças: Leal aos Ashcroft e à Irmandade — até que os dois entrem em conflito. · Fala com: Tranquilizar\n(nunca Intimidação)\nCapitão Walter Pell\nC A P I T ÃO D O D I S T R I T O DA W H I T E H I L L S\nPolicial educado, de luvas brancas, que nunca levantou a voz. Seu distrito tem a menor taxa de crimes da\ncidade porque ele nunca registra nenhum.\nVIRTUDE\nProtegeu o filho de uma criada acusado injustamente de\nroubo, arriscando o cargo.\nP ECADO\nSua função é esconder crimes dos ricos; ele os chama de\n“assuntos de família”. Recebe de cada casarão uma cesta\nde Natal com envelope.\nQUER\nAposentar-se em dois anos com pensão e honra.\nTEM E\nQue Voss, que o despreza, o use como bode expiatório.\nAlianças: Serve White Hills, não a Voss; troca favores com Delgado quando lhe convém. · Fala com:\nRespeito, Jargão de Polícia\nTEIA DE INTERESSES\nQuem precisa de quem em White Hills. Uma seta não é amizade: é dependência. Quando um fio se rompe,\nalguém cai.\nTabela SV.CA.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nCornelius Ashcroft · Prefeito\nWhitcombe\nDinheiro de campanha em troca de\nnão desapropriar terrenos Ashcroft\nWhitcombe descobrir que\nAshcroft financia Crane\ntambém\nJuiz Hale · Don Moretti · Imunidade em tribunal em troca de\ndoações\nHolt publicar a foto da\ndoação\nEleanor\nWhitcombe\nRaymond Holt · Furos sobre adversários em troca de\nsilêncio sobre o marido\nHolt ganhar mais\npublicando do que calando\nPeg Donnelly · Padre Byrne · Segredos de White Hills em troca de\nproteção para sua família\nByrne ameaçar os Ashcroft\nDr. Marlowe · Famílias de White Hills Internações discretas em troca de\nfinanciamento\nUma paciente sã fugir\nCapitão Pell · Clube Pacífico · Ruas sem viaturas em troca de\nenvelopes e da promessa de pensão\nVoss assumir a chefia de\npolícia\nVivian Ashcroft · Tenente Brannigan · Silêncio sobre o tiro em troca do\nperdão de dívidas de jogo\nBrannigan precisar de um\nculpado\nEleanor\nWhitcombe\nKowalski · Serviços sujos em troca de dinheiro\nvivo\nKowalski ser preso e falar\nRUMORES DA WHITE HILLS (1D8)\nTabela SV.CA.4 · O que se diz nos salões\nD 8 R U MO R · V ER D AD E?\n1 O velho Ashcroft vai deserdar Vivian e deixar tudo para um\nhospital\nVerdade\n2 O juiz Hale tem uma segunda família em Chinatown · Meia verdade: tem uma filha, que não sabe quem é o\npai\n3 Há um túnel do Clube Pacífico até Saint Edwiges · Falso (mas há um até o Hotel St. Clair)\n4 Eleanor Whitcombe escreve os discursos do marido · Verdade\n5 Ninguém sai de Santa Úrsula · Falso: saem, mas mudados ou mudos\n6 Teddy Ashcroft fugiu para o México com uma dançarina · Falso; é a versão espalhada por Brannigan\n7 A família Vance (advogados) vendeu a prataria · Verdade; metade de White Hills vendeu\n8 O Capitão Pell guarda um diário com todos os “assuntos de\nfamília”\nVerdade; está no cofre da Catedral da Graça\nCONDUZINDO A WHITE HILLS.\nAumente em +1 a Dificuldade de qualquer teste social de investigadores que não estejam bem vestidos\n(Preparação Dif. 4 para ter um terno à altura). Intimidação aqui não funciona com os patrões — funciona com\nos criados, e eles nunca esquecem. Respeito e Bajulação abrem portas; Burocracia abre cofres.","Downtown":"REGIÃO EM PROFUNDIDADE · 2 DE 7\nDowntown\nEx-banqueiros vendem maçãs na escadaria do Fórum.\nDowntown é o coração de granito de Saint Village: a Prefeitura de cúpula de cobre esverdeado, a Delegacia\nCentral de tijolo vermelho, o Fórum, os bancos com colunas gregas e, no meio deles, a redação da Gazeta da\nManhã, cujos linotipos fazem o chão tremer às três da madrugada. É o único bairro da cidade onde todas as\nfacções têm escritório — e onde nenhuma delas dispara um tiro, porque aqui as armas são canetas.\nDe dia, a Rua Montgomery é um rio de chapéus de feltro: corretores, advogados, contínuos, engraxates e\nhomens de terno puído que vendem maçãs a cinco centavos porque o banco onde trabalhavam fechou em\n1931. Na fila do pão, na escadaria do Fórum, há ex-banqueiros ao lado de ex-estivadores. A Depressão é a única\ncoisa democrática no Distrito.\nA Gazeta tem um arquivo no subsolo que os repórteres chamam de necrotério, porque é onde vão parar as\nmatérias mortas. Eu tenho a chave. Lá embaixo, em caixas de papelão etiquetadas por ano, estão as fotos que\nnão publicamos: um juiz saindo da casa da Madame Celeste às cinco da manhã com a gravata no bolso; a\nprimeira esposa do prefeito, de olho roxo, num banco do Hospital Municipal; o Capitão Voss apertando a mão do\nvelho Moretti no casamento de uma sobrinha, ao lado de um bolo de seis andares.\nNenhuma dessas fotos é segredo para quem está nela. Cada uma dessas pessoas sabe que eu tenho a fotografia, e eu sei\nque elas sabem. Dessa maneira a Gazeta sobrevive há quinze anos sem que nenhum anunciante grande saia, sem que\nnenhuma licença de impressão seja contestada e sem que eu seja convidado para jantar em White Hills, o que é um\nalívio.\nÀs três da manhã, quando os linotipos começam a trabalhar, o prédio inteiro treme, e o pó das caixas do arquivo cai\ndevagar sobre a minha mesa. Às vezes desço e fico olhando. Não tenho vergonha de dizer que é a parte do dia de que eu\nmais gosto.\nR A Y M O N D H O L T , E D I T O R - C H E F E D A G A Z E T A D A M A N H Ã\nDe noite, o Distrito esvazia, e começa o verdadeiro expediente. Contadores queimam livros-caixa nos porões,\nvereadores sobem ao sexto andar do Hotel St. Clair para quartos “de trabalho” e o Capitão Voss recebe\nvisitantes pela porta dos fundos da Delegacia. As luzes que ficam acesas depois das dez valem mais que\nqualquer pista.\nPara os investigadores, o Distrito é onde as provas viram papel — e onde o papel desaparece. Um processo\npode ser arquivado por um carimbo; uma testemunha pode ser deportada por um formulário; um laudo\npode mudar entre o necrotério e o Fórum. Aqui, Burocracia é arma, e quem domina o arquivo domina a\nverdade.\nCRÔNICA · MAÇÃS A CINCO CENTAVOS Arthur Penn, 46 anos, ex-caixa do Banco Continental\nFui caixa do Continental por dezenove anos. Tinha uma caneta-tinteiro com meu nome gravado e um guarda-chuva inglês.\nO banco fechou numa quinta-feira de outubro de 1931; o gerente se matou na sexta. Na segunda eu estava aqui, na\nescadaria do Fórum, com um caixote de maçãs que comprei fiado de um italiano da Costa.\nDaqui eu vejo tudo. Às oito chegam os advogados; às nove, os vereadores; às dez, os tiras com os presos algemados. Às onze,\num homem de chapéu cinza entra pela porta lateral da Prefeitura com uma pasta de couro e sai sem ela. Toda terça. Às vezes\nele compra uma maçã e paga com uma nota de um dólar. Não pede troco.\nNinguém olha para quem vende maçã. Por isso o rapaz da Gazeta, a moça Brooks, me paga um café por semana para eu\ncontar quem entrou e quem saiu. Não é muito, mas é mais do que o banco me deu quando fechou. À noite, volto para o quarto\nalugado no Distrito de Waterford e conto as moedas na mesa. Ainda tenho a caneta-tinteiro. Não tenho mais nada para\nassinar.\nO QUE MOVE O DISTRITO\nTabela SV.DD.1 · Poder em Downtown\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nA Prefeitura · Contratos públicos, licenças de bares e táxis,\nnomeações para cargos\nDos votos do Distrito de Waterford\ne do dinheiro de White Hills\nA Delegacia Central · Decide quem é preso, quem é solto e qual prova chega\nao Fórum\nDos envelopes de Moretti e da\nIrmandade\nO Fórum e a\nPromotoria\nAcusa ou arquiva; o promotor Crane é o único que\nacusa\nDe provas que a Delegacia entrega\n— ou não\nOs bancos · Hipotecas, falências, crédito para a Ponte · De White Hills e do rum lavado\npor Mae Calloway\nA Gazeta da Manhã · Define o que a cidade pensa no café da manhã · De anunciantes e de quem paga\npara não sair no jornal\nLUGARES DO DISTRITO\nTabela SV.DD.2 · Endereços de Downtown\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nPrefeitura · Cúpula de cobre, escadaria de mármore, gabinete do\nprefeito no terceiro andar\nAgenda de Whitcombe, visitantes\nfora do horário, licitações da Ponte\nDelegacia Central · Tijolo vermelho, café queimado, celas no porão e um\ndepósito de provas sem inventário\nQuem foi solto sem fiança, provas\ndesaparecidas, quem visitou Voss\nFórum Municipal · Corredores de mármore onde advogados negociam\npenas no bebedouro\nProcessos arquivados, juízes\n“impedidos”, testemunhas que não\ncompareceram\nNecrotério Municipal · Porão gelado ao lado do Fórum; gavetas numeradas e\num legista bêbado\nCausas de morte reais, corpos sem\nnome, laudos reescritos\nRedação da Gazeta da\nManhã\nLinotipos, fumaça e um arquivo morto de fotografias\nno subsolo\nFotos, manchetes que nunca\nsaíram, quem paga para não ser\nnotícia\nHotel St. Clair · Hotel de luxo; o sexto andar é reservado a vereadores e\n“consultores”\nQuem dormiu com quem;\nreuniões entre facções inimigas\nBanco Pacific Trust · Banco que sobreviveu a 1929 porque lava dinheiro do\nrum\nDepósitos de Mae Calloway e de\nMoretti; hipotecas de White Hills\nCartório de Registros · Arquivo municipal de empresas, terrenos e certidões · Empresas de fachada, donos reais\nde terrenos, certidões falsas\nGENTE DO DISTRITO\nNo Distrito, todos trabalham para alguém e quase todos para mais de um. Leia cada perfil pelas quatro linhas\n— virtude, pecado, quer e teme — e lembre: aqui ninguém trai por ódio, só por cálculo.\nPrefeito Edmund Whitcombe\nP R E F E I T O D E S A I N T V I L L AG E , 5 2 A N O S\nFilho de um carroceiro do Distrito de Waterford, subiu de contínuo a vereador a prefeito em vinte anos\nde apertos de mão. Acredita sinceramente que é o único capaz de manter a cidade inteira — e que\nmanter a cidade inteira justifica qualquer coisa.\nVIRTUDE\nCriou o primeiro programa de empregos públicos da\nCosta Oeste; 4 mil homens trabalham na Ponte por\ncausa dele.\nP ECADO\nAceita o superfaturamento da Ponte, protege os\ncunhados e deixou Brannigan sumir com o corpo de\nTeddy.\nQUER\nSer reeleito e chegar a governador antes de envelhecer.\nTEM E\nVoltar a ser ninguém; ser preso na frente do filho.\nAlianças: Precisa de Moretti e de Byrne ao mesmo tempo; é usado por Eleanor; teme Crane. · Fala com:\nBajulação, Política\nCapitão Harlan Voss\nC A P I T ÃO DA D E L E G AC I A C E N T R A L , 5 7 A N O S\nVeterano da Grande Guerra, rosto de pedra e terço no bolso. Voss não se vê como corrupto: vê-se como o\nhomem que impede uma guerra entre italianos e irlandeses que encheria a cidade de corpos. Recebe dos\ndois para que nenhum vença.\nVIRTUDE\nDesde que assumiu, os homicídios caíram pela metade. É\nverdade.\nP ECADO\nDecide quem é preso por dinheiro; mandou atirar em\ngrevistas em 1932; planta provas em quem ameaça o\nequilíbrio.\nQUER\nSer Chefe de Polícia e se aposentar com a cidade em paz.\nTEM E\nQue uma das máfias vença a outra; morrer sem\nconfessar.\nAlianças: Paga e é pago por todos; despreza Whitcombe; respeita Delgado e por isso o mantém no\narquivo. · Fala com: Jargão de Polícia, Respeito\nPromotor Elliot Crane\nP R O M OT O R P Ú B L I C O, C A N D I DAT O A P R E F E I T O, 3 8 A N O S\nReformista de óculos redondos, ex-pupilo do juiz Hale, que denuncia a corrupção em todos os discursos.\nOs jornais o chamam de “o Incorruptível”. Ele gosta do apelido.\nVIRTUDE\nLeva a julgamento casos que nenhum outro promotor\ntocaria; já prendeu três tiras de Voss.\nP ECADO\nSua campanha é financiada em segredo por Sal Moretti,\nque quer um prefeito capaz de destruir a Irmandade.\nCrane sabe e aceita.\nQUER\nSer prefeito e limpar a cidade — começando pelos\nirlandeses.\nTEM E\nQue descubram de onde vem o dinheiro; que Hale o\nrenegue.\nAlianças: Moretti (secreto), Delgado, Holt (quando convém); inimigo de Whitcombe e Voss. · Fala com:\nRespeito, Retórica\nRaymond Holt\nE D I T O R - C H E F E DA G A Z E T A DA M A N H Ã , 5 0 A N O S\nGravata solta, cigarro eterno, cinismo de quem viu tudo duas vezes. Holt não acredita em verdade;\nacredita em circulação. Publica o que vende e cala o que paga, mas tem um limite que nem ele conhece\naté chegar nele.\nVIRTUDE\nRecusou-se a publicar o nome de uma criança vítima de\nabuso, mesmo sob pressão de toda a redação.\nP ECADO\nGuarda um arquivo de fotos comprometedoras de\nmetade da cidade e vende o silêncio; destruiu a carreira\nde um vereador honesto porque ele não comprou\nanúncios.\nQUER\nUma manchete que derrube um prefeito — e o prêmio\nque vem com ela.\nTEM E\nFicar irrelevante; que o rádio mate o jornal.\nAlianças: Eleanor Whitcombe (furos), Crane, Moretti (anúncios do Il Paradiso); inimigo de ninguém,\namigo de ninguém. · Fala com: Jargão de Imprensa, Jogatina\nHattie Brooks\nR E P Ó R T E R DA G A Z E T A , 2 7 A N O S\nUma das duas mulheres da redação policial, rápida no gatilho da câmera e mais rápida na língua. Quer\num furo que a tire das páginas de culinária para sempre.\nVIRTUDE\nArrisca a vida para expor os acidentes da Ponte que\nninguém quer publicar.\nP ECADO\nTirou as fotos de Whitcombe com Lola e as vendeu a\nHolt, sabendo que Lola seria destruída junto.\nQUER\nSeu nome assinando a primeira página.\nTEM E\nVoltar para a casa dos pais em Sacramento.\nAlianças: Usa os PJs como fonte; desconfia de Holt; tem um caso com Delgado. · Fala com: Jargão de\nImprensa, Bajulação\nTenente Earl Brannigan\nT E N E N T E D E H O M I C Í D I O S , 4 4 A N O S\nDetetive competente que se perdeu nas mesas do Il Paradiso. Deve 6 mil dólares a Moretti e paga\nencerrando casos que incomodam a Prefeitura.\nVIRTUDE\nAinda resolve os homicídios de gente pobre que\nninguém mais investiga; é o único tira que vai a enterros\nno Distrito de Waterford.\nP ECADO\nSumiu com o corpo de Teddy Ashcroft e falsificou o\nrelatório; já espancou um suspeito até a morte.\nQUER\nQuitar a dívida e voltar a ser o detetive que era.\nTEM E\nQue Moretti cobre a dívida de outra forma; que a filha\ndescubra.\nAlianças: Prefeitura (por ordem), Moretti (por dívida), Vivian (por chantagem mútua). · Fala com: Jargão\nde Polícia, Jogatina\nDr. Axel Lindqvist\nL E G I S T A M U N I C I PA L , 6 3 A N O S\nSueco, ex-cirurgião militar, mãos firmes até a terceira dose. Faz as melhores autópsias da Costa Oeste e as\nvende para quem pagar.\nVIRTUDE\nFaz autópsias gratuitas para famílias pobres e as assina\ncomo “causa natural” para que recebam o seguro.\nP ECADO\nAssinou o atestado de afogamento de Teddy; troca\nlaudos por 5 dólares e por garrafas.\nQUER\nMorrer em paz, de preferência bêbado.\nTEM E\nSóbrio, lembrar-se de tudo o que assinou.\nAlianças: Trabalha para qualquer um; tem carinho por Delgado. · Fala com: Medicina Legal, Bajulação\n(garrafa)\nFrank Delgado\nD E T E T I V E N O A R Q U I V O M O R T O, 4 1 A N O S\nMexicano-americano, filho de lavadeira, entrou na polícia para que ninguém mais tratasse sua mãe\ncomo seu pai foi tratado. Um dos últimos tiras limpos — e o mais isolado.\nVIRTUDE\nJunta provas contra Voss há três anos, sem um centavo,\narriscando a vida.\nP ECADO\nPara obter essas provas, plantou drogas em um\ninformante dos Moretti e deixou um homem inocente\nser preso por um ano.\nQUER\nVer Voss no banco dos réus.\nTEM E\nQue sua causa justa o transforme em Voss.\nAlianças: Crane (aliado incômodo), Hattie Brooks (amante), Pell (favores). · Fala com: Jargão de Polícia,\nTranquilizar\nTEIA DE INTERESSES\nNo Distrito, as alianças têm prazo de validade: duram até a próxima eleição, o próximo processo ou a próxima\nmanchete.\nTabela SV.DD.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nWhitcombe · Voss · Paz nas ruas em troca de um\ndepartamento sem auditoria\nVoss apoiar Crane nas\neleições\nVoss · Moretti e Byrne · Equilíbrio de poder em troca de dois\nenvelopes semanais\nUm dos dois ficar forte\ndemais\nCrane · Moretti · Dinheiro de campanha em troca de\numa guerra contra a Irmandade\nByrne descobrir e vazar\npara Holt\nHolt · Eleanor\nWhitcombe\nSilêncio sobre o prefeito em troca de\nfuros sobre rivais\nUma manchete valer mais\nque o acordo\nBrannigan · Prefeitura · Casos encerrados em troca de\nproteção da dívida\nWhitcombe precisar de um\nbode expiatório\nLindqvist · Quem pagar · Laudos sob medida em troca de\ndinheiro e garrafas\nFicar sóbrio por uma\nsemana\nDelgado · Crane · Provas contra Voss em troca de um\nprocesso sério\nDelgado descobrir o\ndinheiro de Moretti\nHattie Brooks · PJs · Informação em troca de\nexclusividade\nOs PJs falarem com Holt\nprimeiro\nBanco Pacific Trust · Mae Calloway · Lavagem do rum em troca de\ndepósitos que mantêm o banco\naberto\nO FBI de Prescott auditar o\nbanco\nRUMORES DO DISTRITO (1D8)\nTabela SV.DD.4 · O que se diz nos corredores\nD 8 R U MO R · V ER D AD E?\n1 Whitcombe tem um filho ilegítimo no Distrito de Waterford · Verdade; ele paga a escola do menino\n2 O promotor Crane é incorruptível · Falso\n3 Há um cofre sob a Prefeitura cheio de dinheiro vivo · Meia verdade: há o cofre, mas está vazio desde 1931\n4 Voss foi herói de guerra · Verdade; ganhou uma medalha em Argonne\n5 O Banco Pacific Trust vai falir · Falso, enquanto houver rum\n6 Holt guarda um arquivo que derrubaria a cidade inteira · Verdade\n7 Lindqvist já foi preso na Suécia · Verdade: por eutanásia de um paciente\n8 O depósito de provas da Delegacia pega fogo uma vez por ano Verdade, sempre em dezembro\nPAPELADA COMO ARMA\nNo Distrito, uma pista pode ser destruída sem violência. Quando os PJs entregam uma prova às autoridades, o\nDiretor rola 1d6 para saber o que acontece com ela, a menos que os PJs paguem pelo caminho seguro.\nTabela SV.DD.5 · O destino de uma prova (1d6)\nD 6 · D ESTINO · C O MO EV ITAR\n1 · Desaparece do depósito · Gasto de Jargão de Polícia (2): um tira honesto guarda a prova\n2 · Laudo alterado · Medicina Legal (1): pedir uma segunda autópsia a Lindqvist (por 5 dólares)\n3 · Processo arquivado · Burocracia (2): levá-la direto ao promotor Crane\n4 · Vaza para a Gazeta · Jargão de Imprensa (1): negociar com Holt o momento da publicação\n5–6 Chega ao Fórum · —\nCONDUZINDO O DISTRITO.\nAqui ninguém fala de graça e ninguém fala em voz alta. Burocracia substitui Intimidação; Jargão de Polícia e\nJargão de Imprensa abrem as duas portas mais importantes. Toda conversa no Distrito é ouvida por alguém:\ndepois de cada cena aqui, avance 1 segmento de um relógio de facção de escolha do Diretor, se os PJs não\ntomaram cuidado (Discrição Dif. 4).","Black Rock e a Ponte":"REGIÃO EM PROFUNDIDADE · 3 DE 7\nBlack Rock e a Black Rock Bridge\nO andaime do Pilar 3 balança quando venta do noroeste, e o vento do noroeste sopra quase todo dia de setembro\na março. A duzentos metros, você sente o pilar se mexer embaixo de você como o lombo de um cavalo. Os\nrapazes novos se agarram na estrutura. Os velhos aprendem a balançar junto.\nLá de cima, quando a neblina abre, dá para ver a ilha inteira: o farol, as torres, o pátio onde os presos andam em fila\nàs quatro da tarde. Os rapazes apostam um dólar em quem cai primeiro, a ponte ou a prisão. Eu não aposto. Enterrei\nonze homens desta obra desde março do ano passado, com caixão e missa em São Brendan, porque o Sindicato paga.\nO Pedro Alvarado me mostrou em janeiro um pedaço do concreto do Pilar 3 que ele esfarelou entre os dedos, como pão\ndormido. Eu levei o pedaço ao Byrne embrulhado num lenço. O Byrne ficou um tempo olhando, guardou no bolso e\ndisse que ia resolver. Duas semanas depois o Pedro caiu. Na manhã seguinte, nós despejamos a camada nova do pilar.\nEu estava na equipe. Só fui pensar onde ele tinha caído uma semana depois, numa noite em que não conseguia dormir.\nS E A M U S D O Y L E , S I N D I C A T O D O S F E R R E I R O S\nRebitadores no Pilar 3; lá embaixo, Black Rock na baía.\nNo extremo norte da península, onde o estreito se abre para o Pacífico, Saint Village está construindo seu\nmonumento. A Black Rock Bridge será a mais longa do mundo quando ficar pronta, em 1937: dois pilares de\naço pintados de vermelho, cabos do diâmetro de um homem e a promessa de ligar a cidade ao condado do\nnorte, onde as terras valem centavos — por enquanto. Quem comprar essas terras agora será rico quando o\nprimeiro carro atravessar.\nMetade da Prefeitura já comprou.\nO canteiro é uma cidade própria: barracões, guindastes, caldeiras, cantinas e quatro mil homens que vieram de\ntodo o país atrás do único emprego que paga em dinheiro vivo toda sexta. Trabalham a duzentos metros de\naltura, sem rede, na neblina e no vento. A empreiteira paga uma “indenização”\nde 50 dólares por morte. Desde janeiro, já pagou onze.\nLá embaixo, no meio da baía, a ilha de Black Rock assiste. Antiga fortaleza militar, hoje é a prisão estadual de\nsegurança máxima: muros de granito, correntes de água gelada que matam qualquer nadador e um farol que\ngira a noite toda. Os presos veem a ponte crescer pelas grades. Alguns deles trabalham nela, em turnos de\n“reabilitação” que o diretor aluga à empreiteira por dois dólares por cabeça.\nPara os investigadores, esta é a região onde os segredos da cidade vão morrer: no concreto do pilar, no fundo\ndo estreito ou numa cela de Black Rock. É também onde a cidade inteira se cruza — irlandeses no sindicato,\nMoretti no fornecimento, a Prefeitura nos contratos, a Delegacia nas celas e a Gazeta na inauguração.\nCRÔNICA · DUZENTOS METROS ACIMA DA ÁGUA Joe Szabo, 31 anos, rebitador húngaro\nO sino toca às seis e meia e a gente sobe pelo elevador de carga até o topo do pilar. Lá em cima o vento fala húngaro, juro por\nDeus. Fala igual ao meu avô. Meu parceiro, o Tony, esquenta os rebites na forja até ficarem cor de laranja e joga para mim\ncom a pinça, por cima de três metros de nada. Eu pego com o balde. Se errar, o rebite cai no estreito, e o capataz desconta um\ndólar. Se eu errar o passo, a empreiteira paga cinquenta para a minha mulher.\nNa hora do almoço sentamos na viga, as pernas penduradas sobre a neblina, e comemos pão com linguiça. Ninguém fala de\nmorte em cima do cabo. Falamos de beisebol, das moças do Savoy, da greve. O Doyle diz que vai ter rede de proteção em\nagosto. O Doyle diz isso desde janeiro.\nDesde que o mexicano caiu, ninguém trabalha no pilar 3 se puder evitar. Dizem que o concreto range à noite. Eu não\nacredito em fantasma. Acredito em areia. Na sexta recebo vinte e dois dólares em dinheiro vivo, pago um ao capataz, um à\nIrmandade e vou para casa contar ao meu filho que hoje eu toquei uma nuvem.\nO QUE SUSTENTA A PONTE\nTabela SV.PN.1 · Poder na Ponte e em Black Rock\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nEmpreiteira\nWhitcombe-Lyman\nContrato de 35 milhões; compra material, contrata e\ndemite\nDo prefeito e do silêncio dos\nengenheiros\nSindicato dos\nFerreiros\nControla quem sobe nos cabos; pode parar a obra\nnuma manhã\nDa Irmandade Irlandesa\nFornecedores · Cimento, areia, cabos de aço, comida da cantina · De Moretti, que fornece quase\ntudo\nDiretoria de Pedra\nNegra\nCelas, guardas, aluguel de presos para a obra · Da Delegacia Central e do\norçamento estadual\nEspeculadores · Compram as terras do condado do norte · De que a ponte fique pronta —\ninteira ou não\nLUGARES DA PONTE E DA ILHA\nTabela SV.PN.2 · Endereços\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nCanteiro Sul · Barracões, caldeiras e o escritório da empreiteira,\nsempre de cortinas fechadas\nFolhas de pagamento, guias de\nentrega de material, lista de\nmortos real\nPilar 3 · Torre de aço e concreto a 230 m de altura; o pilar do\nconcreto adulterado\nRachaduras na base; amostras que\nse esfarelam\nCantina do Canteiro · Café, ensopado e apostas sobre quem cai na próxima\nsemana\nFofocas dos operários; quem\nreclamou do concreto\nBarracão do\nSindicato\nSede do Sindicato dos Ferreiros, com retratos dos\nmortos na parede\nQuem está organizando a greve; a\nlista negra da empreiteira\nCais de Black Rock · Único desembarque da ilha; lancha da prisão duas\nvezes ao dia\nQuem visitou qual preso; o que\nentra escondido nas caixas\nPrisão de Pedra\nNegra\nCelas de granito, pátio exposto ao vento, solitária no\nsubsolo\nTestemunhas presas por crimes\nque não cometeram; acordos com\no diretor\nFarol da Ilha · Farol automático, mas com um faroleiro velho que se\nrecusa a sair\nO que passa pela baía à noite:\nlanchas de rum, corpos, fugitivos\nTerras do Condado\nNorte\nPastos e ranchos à venda do outro lado do estreito · Quem comprou cada terreno (os\nnomes no Cartório de Downtown)\nGENTE DA PONTE E DA ILHA\nNa ponte, todos arriscam a vida; na ilha, todos já a perderam de algum jeito. Cada um faz o que precisa para\nchegar ao fim do turno — e alguns fazem mais.\nOtto Brandt\nE N G E N H E I R O - C H E F E A D J U N T O, 4 9 A N O S\nEngenheiro alemão formado em Dresden, que projetou pontes no Reno antes de fugir dos nazistas. Sabe\nque o concreto do pilar 3 é areia da baía desde março e bebe gim no café da manhã para não pensar\nnisso.\nVIRTUDE\nÉ o único engenheiro que sobe aos cabos todo dia para\ninspecionar; já salvou dois operários com as próprias\nmãos.\nP ECADO\nAssinou os laudos de qualidade do pilar 3 por 3 mil\ndólares. Mandou o dinheiro para a irmã em Berlim.\nQUER\nQue a ponte não caia — e não ser o culpado se cair.\nTEM E\nSer deportado; ver a ponte ruir com gente em cima.\nAlianças: Chantageado pela empreiteira; procura os PJs em segredo (Caso 2). · Fala com: Arquitetura,\nTranquilizar\nHarold Lyman\nD I R E T O R DA E M P R E I T E I R A W H I T C O M B E - LY M A N , 4 6 A N O S\nCunhado do prefeito, ex-vendedor de seguros, que ganhou o contrato da Ponte sem nunca ter construído\numa garagem. É simpático, generoso com caridades e incapaz de entender por que alguém se importaria\ncom um pouco de areia.\nVIRTUDE\nPaga escola para os filhos dos operários mortos — do\npróprio bolso, sem publicidade.\nP ECADO\nDesvia um terço da verba da ponte; mandou demitir e\ncolocar na lista negra todos que reclamaram.\nQUER\nTerminar a ponte e se mudar para White Hills.\nTEM E\nIr para Black Rock — que ele vê todo dia pela janela.\nAlianças: Whitcombe (família), Moretti (fornecedor), Eleanor (que o despreza e o usa). · Fala com:\nBajulação, Burocracia\nSeamus Doyle\nP R E S I D E N T E D O S I N D I C AT O D O S F E R R E I R O S , 3 8 A N O S\nFerreiro irlandês de braços tatuados, sobrevivente de uma queda de 40 metros em Nova York. Fala\npouco e é ouvido por quatro mil homens.\nVIRTUDE\nOrganizou o fundo de viúvas e enterra cada morto com\ncaixão e missa, pagos pelo sindicato.\nP ECADO\nRecebe ordens do Padre Byrne e sabe que Byrne está\nchantageando o prefeito em vez de salvar os operários.\nObedece porque precisa da Irmandade para não ser\nesmagado.\nQUER\nSegurança nos cabos: rede de proteção e salário de risco.\nTEM E\nQue Byrne o descarte; que a greve fracasse e os homens\npassem fome.\nAlianças: Leal à Irmandade, mas não a ponto de deixar a ponte cair. · Fala com: Tranquilizar, Política\nPedro Alvarado\nO P E R Á R I O M O R T O, 2 4 A N O S ( V E R C A S O 2 )\nRebitador mexicano que caiu do pilar 3 “por acidente” em janeiro. Ia denunciar o concreto adulterado no\nsindicato. Seu corpo nunca foi encontrado.\nVIRTUDE\nSustentava a mãe e quatro irmãos no Distrito de\nWaterford.\nP ECADO\nAntes de procurar o sindicato, tentou vender a\ninformação à Gazeta por 200 dólares. Hattie Brooks\nrecusou: “não é notícia ainda”.\nQUER\n— (morto) Seu diário está na Pensão Rosales. Alianças: —\n· Fala com: Pesquisa (diário)\nTEM E\n—\nDiretor Warren Ashby\nD I R E T O R DA P R I S ÃO D E B L AC K R O C K , 6 0 A N O S\nEx-capelão militar que acredita genuinamente na reabilitação pelo trabalho. Criou a biblioteca e a\noficina de carpintaria da ilha.\nVIRTUDE\nNenhum preso foi espancado até a morte sob sua\ndireção, ao contrário do antecessor.\nP ECADO\nAluga presos à empreiteira por 2 dólares por cabeça e\nembolsa metade; mantém em celas homens que Voss lhe\npede para “guardar”.\nQUER\nAposentar-se como reformador; ter seu nome numa ala\nda prisão.\nTEM E\nUma fuga, ou uma rebelião, nas vésperas da\naposentadoria.\nAlianças: Voss (envia presos), Lyman (aluga presos); simpatiza com Irmã Agnes. · Fala com: Respeito,\nBurocracia\n“Dutch” Kessler\nP R E S O N º 1 1 87, E X - M AT A D O R D E M O R E T T I , 4 2 A N O S\nHolandês de Nova Jersey, assassino profissional condenado por um único crime que não cometeu. Matou\nnove homens para Moretti antes de ser entregue por ele à polícia. Lê Dostoiévski na biblioteca da prisão.\nVIRTUDE\nProtege os presos mais jovens dos guardas e dos\nestupradores no pátio.\nP ECADO\nMatou nove homens por dinheiro, um deles na frente do\nfilho.\nQUER\nVingança contra Moretti — ou um acordo que o tire da\nilha.\nTEM E\nMorrer na prisão sem que ninguém saiba a verdade\nsobre Moretti.\nAlianças: Sem aliados; aceita qualquer um que o ajude a fugir (evento de setembro da Linha do Tempo). ·\nFala com: Intimidação, Gíria das Ruas\nSargento Hank Purcell\nC H E F E DA G U A R DA D E B L AC K R O C K , 5 1 A N O S\nGuarda veterano de olhos cansados, que já viu presos morrerem afogados tentando fugir. Conhece cada\ncela e cada segredo da ilha.\nVIRTUDE\nLeva cartas dos presos às famílias por conta própria.\nP ECADO\nContrabandeia rum, cigarros e mensagens para dentro\nda prisão a mando de Mae Calloway; deixa os presos de\nVoss na solitária sem comida.\nQUER\nComprar um barco de pesca e nunca mais ver a ilha.\nTEM E\nQue Ashby descubra o contrabando; ser preso na\nprópria prisão.\nAlianças: Mae Calloway (pagamento), Voss (ordens), presos (respeito mútuo). · Fala com: Jargão de Polícia,\nSubmundo\nEzra Pike\nFA R O L E I R O DA I L H A , 7 8 A N O S\nVelho marinheiro que mora no farol há quarenta anos e se recusou a sair quando ele foi automatizado.\nO Estado desistiu de despejá-lo.\nVIRTUDE\nViu tudo o que passou pela baía à noite e anota em seus\ndiários de bordo, com hora e direção.\nP ECADO\nVende essas informações para quem pagar: Mae,\nMoretti, o FBI. Às vezes para todos ao mesmo tempo.\nQUER\nMorrer no farol, e não num asilo.\nTEM E\nQue alguém queime seus diários — ou que o queime\njunto com eles.\nAlianças: Ninguém e todos; tem um fraco por Irmã Agnes, que lhe leva comida. · Fala com: Bajulação,\nIdiomas (gíria de marinheiro)\nTEIA DE INTERESSES\nA ponte é o único projeto em que todas as facções ganham — enquanto ela não cair.\nTabela SV.PN.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nHarold Lyman · Prefeito\nWhitcombe\nComissões da obra em troca do\ncontrato\nUma morte pública demais\nna obra\nLyman · Don Moretti · Contratos de fornecimento em troca\nde material barato (areia)\nO pilar 3 cair antes da\ninauguração\nSeamus Doyle · Padre Byrne · Força sindical em troca da proteção\nda Irmandade\nByrne preferir o acordo\ncom o prefeito aos\noperários\nOtto Brandt · Empreiteira · Laudos assinados em troca de\ndinheiro e de silêncio sobre seu\npassado\nBrandt ficar sóbrio por\numa semana\nDiretor Ashby · Lyman · Presos trabalhadores em troca de\ndinheiro\nUm preso morrer na obra\ne virar manchete\nDiretor Ashby · Capitão Voss · Celas para inimigos de Voss em troca\nde verbas e de proteção\nAshby ganhar consciência\n— ou medo\nSargento Purcell · Mae Calloway · Contrabando na ilha em troca de\ndinheiro\nO FBI vigiar o cais\nEzra Pike · Quem pagar · Horários e rotas da baía em troca de\ndinheiro e comida\nDuas facções descobrirem\nque ele vende para as duas\nRUMORES DO CANTEIRO E DA ILHA (1D8)\nTabela SV.PN.4 · O que se diz nas cantinas e nas celas\nD 8 R U MO R · V ER D AD E?\n1 Há corpos no concreto do pilar 3 · Verdade: um, o de Pedro Alvarado\n2 A ponte vai cair no dia da inauguração · Possível, se o pilar 3 não for reforçado\n3 O diretor Ashby vende presos como escravos · Meia verdade: aluga, e embolsa metade\n4 Dutch Kessler está planejando fugir · Verdade; foge em setembro\n5 O prefeito comprou todas as terras do condado norte · Meia verdade: Eleanor comprou, em nome da irmã\n6 O farol tem um fantasma · Falso; tem Ezra Pike\n7 A Irmandade vai parar a obra em maio · Verdade, se Byrne não conseguir o porto\n8 Moretti fornece areia da baía como se fosse cimento · Verdade\nPERIGOS DA ALTURA E DA ÁGUA\nCenas na ponte e na baía usam estas regras de perigo, na escala leve, moderado e extremo do Capítulo 5.\nTabela SV.PN.5 · Perigos\nSITU AÇ ÃO · TESTE · SE FALH AR\nAndar nos cabos com\nvento\nAtletismo Dif. 4\n(5 na neblina)\nEscorrega: −2 de Saúde e fica pendurado; outro PJ precisa de Atletismo\nDif. 4 para puxá-lo\nQueda do andaime · Atletismo Dif. 5 1d6 + 2 de dano; acima de 30 m, é morte certa na água\nÁgua do estreito · Atletismo Dif. 5\npor minuto\n−1 de Saúde por minuto (frio e correnteza); após 10 min, rolagem de\nConsciência\nRebite incandescente · Faro de Encrenca\nDif. 4\n−1 de Saúde (queimadura leve); Sangue-Frio −1 ao ver um colega atingido\nFuga de Black Rock · Furtividade Dif.\n7, depois disputa\nde Atletismo\ncontra os\nguardas\nVolta à cela, com +1 ano de pena e −2 de Sangue-Frio\nCONDUZINDO A PONTE.\nO canteiro tem uma regra que todos respeitam: ninguém fala de morte em cima do cabo. Investigadores que\nchegam fazendo perguntas sobre acidentes recebem +2 nas Dificuldades sociais até ganharem a confiança dos\noperários (Tranquilizar Dif. 4 ou trabalhar um turno com eles). Na ilha, o único idioma é o dinheiro:\nBurocracia para entrar, Intimidação com os presos e Gíria das Ruas para ser ouvido.","Chinatown":"REGIÃO EM PROFUNDIDADE · 4 DE 7\nChinatown\nChinatown ocupa doze quarteirões entre Downtown e Saint Edwiges, mas a cidade de verdade é maior:\nestende-se para baixo, por porões, adegas e túneis cavados depois do incêndio de 1906, quando os bombeiros\npagos por White Hills deixaram o bairro queimar. Os moradores reconstruíram tudo em dois anos — com\npagodes de fachada para atrair turistas e, embaixo, um labirinto que a polícia nunca mapeou.\nA Lei de Exclusão de 1882 ainda vale. Os homens chineses não podem trazer mortos, e os tongs, sociedades\nfraternas que protegem os fracos e controlam o jogo, o ópio e as mulheres. A polícia de Voss só entra quando é\nconvidada, e só sai quando recebe.\nDe dia, a Rua Grant é uma vitrine para turistas: lanternas de papel, lojas de seda, restaurantes com cardápio em\ninglês. À noite, abrem-se as outras portas — salas de fan-tan, fumadouros de ópio, casas de chá onde negócios\nentre facções inimigas são fechados sobre porcelana fina. Chinatown é neutra asporque todos precisam dela:\nE u tinha onze anos em abril de 1906. Lembro do barulho antes do tremor, um ronco que vinha de baixo da terra,\ncomo um trem passando debaixo da Rua Grant. Depois a parede da loja do meu tio caiu inteira para a rua, sem\nquebrar, e ficou deitada na calçada com a janela ainda no lugar.\nO fogo começou numa cozinha da Rua Washington à tarde. Meu tio me levou até a esquina da Rua Clay para buscar\nágua e eu vi os carros dos bombeiros parados na subida da Califórnia, com as mangueiras enroladas. Os homens\nfumavam. Um deles me jogou um cigarro aceso para ver se eu pegava. Eu peguei.\nTrês dias depois não havia mais Chinatown. Os jornais disseram que o fogo tinha começado por nossa causa e que o\nbairro devia ser reconstruído fora da cidade, perto dos matadouros. Os velhos das Seis Companhias foram à\nPrefeitura com os documentos de propriedade que tinham salvado dentro das roupas. Reconstruímos em dois anos, no\nmesmo lugar. Por cima, pagodes de madeira pintada, para os turistas. Por baixo, outra coisa.\nAté hoje, quando passo pela Califórnia, olho para a subida.\nC H A N W I N G - S U N , D A S S E I S C O M P A N H I A S\nMoretti compra esposas, não podem se naturalizar, não podem testemunhar contra um branco. Por isso\nChinatown tem sua própria lei: as Seis Companhias, associações de clãs que julgam disputas, cobram impostos\ne enterram os ópio, Mae usa os túneis, a Prefeitura cobra licenças, e a Irmandade odeia, mas não ousa entrar.\nPara os investigadores, Chinatown é o lugar onde as perguntas encontram silêncio educado.\nNinguém mente;\nsimplesmente ninguém entende inglês quando não quer.\nQuem respeita as regras do bairro pode encontrar ali a testemunha que ninguém mais encontra. Quem as\nviola desaparece num túnel que não existe.\nCRÔNICA · O VAPOR DA LAVANDERIA Wu Ah-Fook, 58 anos, lavadeiro da Rua Jackson\nAcendo a caldeira às quatro. Às cinco a água já ferve e o vapor sobe pela escada até o quarto onde durmo com outros cinco\nhomens. Nenhum de nós tem esposa aqui. A lei não deixa. Tenho uma mulher em Taishan que não vejo há vinte e dois anos e\num filho que conheço por fotografia. Mando dinheiro todo mês pela Companhia Ning Yung. Eles cobram, mas chegam.\nOs brancos trazem as camisas e não olham para o meu rosto. Leio os bolsos antes de lavar: bilhetes de aposta, recibos de\nhotel, endereços de mulheres, uma vez um dente de ouro. Guardo tudo numa lata embaixo da tábua. O homem do Lótus passa\nàs sextas, toma chá comigo e pergunta o que achei nos bolsos dos irlandeses. Respondo. Ele me protege dos rapazes do Junco\nNegro, que querem minha lavanderia.\nÀ noite jogo fan-tan no Bom Augúrio. Perco sempre um pouco, ganho às vezes. Quando o vento vem da baía, sinto cheiro de\nfumaça, mesmo sem fogo. Todo mundo que viu 1906 sente. A gente reconstruiu tudo em dois anos. A cidade acha que somos\nestrangeiros. Estamos aqui há mais tempo que a maioria deles.\nQUEM MANTÉM A ORDEM EM CHINATOWN\nTabela SV.CH.1 · Poder em Chinatown\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nAs Seis Companhias · Tribunais de clã, empréstimos, enterros, a voz oficial do\nbairro diante da Prefeitura\nDa legitimidade e do respeito dos\nvelhos\nTong da Flor de\nLótus\nJogo, ópio, proteção, cobrança e punição nos túneis · Do silêncio da Delegacia e dos\nclientes brancos\nTong do Junco Negro · Rival menor, que controla as lavanderias e o tráfico de\npessoas\nDos irlandeses, que o usam contra\nMoretti\nA Delegacia\n(Narcóticos)\nBatidas seletivas e apreensões revendidas · Dos envelopes do Lótus\nA Missão\nPresbiteriana\nAbriga mulheres fugidas dos bordéis e ensina inglês · De doações de White Hills — e da\ntolerância dos tongs\nLUGARES DE CHINATOWN\nTabela SV.CH.2 · Endereços\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nCasa de Chá do\nDragão Jade\nSalão de chá elegante na Rua Grant; nos fundos, a sala\nonde o Lótus recebe visitas\nAcordos entre facções; o que Lin\nMei-Hua sabe sobre todos\nFumadouro da Rua\nGrant\nPorão de catres e fumaça doce; clientes chineses,\nmarinheiros e filhos de White Hills\nQuem está viciado; informantes; o\nópio que chega pelo Galpão 14\nSalão de Fan-Tan\nBom Augúrio\nSala de jogo chinês atrás de uma loja de ervas · Dívidas de jogo; quem perde\nfortunas e para quem\nSede das Seis\nCompanhias\nPrédio de três andares com um tribunal de clã no\núltimo piso\nRegistros de imigração falsos\n(“filhos de papel”); disputas entre\nfamílias\nLavanderia Wah Sing · Lavanderia a vapor do Tong do Junco Negro · Roupas ensanguentadas dos\nirlandeses; o tráfico de mulheres\nMissão Presbiteriana · Casa de tijolos onde a missionária Ada Pryor abriga\nmulheres fugidas\nTestemunhas dos bordéis; quem as\nestá procurando\nTemplo de Tin Hau · Templo da deusa do mar, no último andar de um\nprédio comercial\nEntrada para os túneis do Hotel St.\nClair; oferendas pelos mortos no\nmar\nPenhores Wong Shu · Loja escura onde tudo tem preço e nada tem origem · Objetos roubados da cidade\ninteira; a arma de bolsa de Vivian\nGENTE DE CHINATOWN\nEm Chinatown, a sobrevivência é coletiva e a culpa também. Cada pessoa aqui carrega a família, o clã e o\nbairro nas costas, e cada escolha moral é pesada contra todos eles.\nLin Mei-Hua\nD O N A DA C A S A D E C H Á , L Í D E R S E C R E T A D O LÓT U S , 4 4 A N O S\nNascida em Saint Village, filha de um comerciante e de uma mulher vendida a um bordel. Educada na\nMissão, fala cantonês, inglês, italiano e francês. Oficialmente, o líder do Lótus é seu tio idoso; na prática,\ntodas as decisões são dela.\nVIRTUDE\nManteve Chinatown longe da guerra entre italianos e\nirlandeses; financia em segredo a Missão que resgata\nmulheres dos bordéis.\nP ECADO\nControla o comércio de ópio e mandou matar três\nhomens do Junco Negro em 1932, incluindo um de 17\nanos.\nQUER\nQue Chinatown sobreviva à Lei de Exclusão; ser\nrespeitada como líder em público, um dia.\nTEM E\nQue descubram que ela, uma mulher, comanda o tong\n— e que os velhos se voltem contra ela.\nAlianças: Aliada ocasional de Moretti (ópio), parceira de Mae (túneis); paga Ruth Sayer. · Fala com:\nIdiomas, Respeito\nChan Wing-Sun\nT I O D E L I N , L Í D E R O F I C I A L D O LÓT U S , 7 1 A N O S\nEx-ferroviário que sobreviveu à construção da Central Pacific e ao incêndio de 1906. Sentado na casa de\nchá, recebe os visitantes, sorri e diz sim a tudo, depois deixa a sobrinha decidir.\nVIRTUDE\nAinda paga o enterro e o retorno dos ossos para a China\nde qualquer homem do bairro, sem perguntar o clã.\nP ECADO\nEm 1906, vendeu as filhas de vizinhos mortos no\nincêndio para pagar a reconstrução do tong.\nQUER\nMorrer com honra e ter os ossos levados a Cantão.\nTEM E\nSer lembrado pelo que fez em 1906.\nAlianças: Protege Lin; respeitado pelas Seis Companhias. · Fala com: Respeito\nKwan Ah-Lee\nL Í D E R D O T O N G D O J U N C O N E G R O, 3 5 A N O S\nImigrante chegado em 1922 com papéis falsos, ambicioso e ressentido. Acha que o Lótus vendeu\nChinatown aos brancos e quer substituí-lo.\nVIRTUDE\nPaga salários dignos nas lavanderias e defendeu\noperários chineses agredidos pela polícia.\nP ECADO\nTrafica mulheres de Cantão para os bordéis de Saint\nEdwiges; aceita dinheiro da Irmandade para sabotar o\nópio de Moretti.\nQUER\nComandar Chinatown e acabar com o Lótus.\nTEM E\nSer deportado — ele é um “filho de papel” e os papéis\npodem ser revelados.\nAlianças: Irmandade Irlandesa (armas e dinheiro); inimigo de Lin; usa Patrulheiro Dunne. · Fala com:\nIntimidação, Gíria das Ruas\nAda Pryor\nG U E T OÁ R I A P R E S B I T E R I A N A , 3 9 A N O S\nEscocesa de Glasgow, enviada pela igreja em 1919. Já resgatou 300 mulheres dos bordéis com a polícia,\ncom machados e, quando necessário, com mentiras. Os tongs a chamam de “a Mãe Fantasma”.\nVIRTUDE\nArrisca a vida diariamente; nenhuma mulher que bateu à\nsua porta foi devolvida.\nP ECADO\nConverte as mulheres resgatadas à força e as casa com\nquem a Missão escolhe; entrega à polícia homens\nchineses com base em boatos.\nQUER\nFechar todos os bordéis de Chinatown.\nTEM E\nQue Lin Mei-Hua, sua aluna mais brilhante, seja o que\nela suspeita que é.\nAlianças: Recebe dinheiro de White Hills (Eleanor Whitcombe); tolerada pelo Lótus; inimiga do Junco\nNegro. · Fala com: Tranquilizar, Respeito\nDetetive Ruth Sayer\nD E T E T I V E D E N A R C ÓT I C O S , 3 6 A N O S\nUma das únicas mulheres detetives da cidade, designada para Chinatown porque nenhum homem queria\no cargo. Conhece o bairro melhor que qualquer tira e é respeitada pelos velhos.\nVIRTUDE\nImpediu a polícia de incendiar o bairro durante uma\nbatida em 1931.\nP ECADO\nGuarda o ópio apreendido e o revende ao Lótus, que lhe\npaga uma quantia mensal.\nQUER\nPagar o sanatório do irmão, veterano de guerra viciado\nem morfina.\nTEM E\nQue o irmão morra; que Voss descubra quanto ela\nrecebe.\nAlianças: Lin Mei-Hua (pagamento), Voss (nominalmente), Delgado (amizade antiga). · Fala com: Jargão\nde Polícia, Idiomas\nDr. Ng Tai-Po\nH E R B A L I S T A E M É D I C O, 5 8 A N O S\nFormado em medicina ocidental em Hong Kong, proibido de clinicar nos Estados Unidos. Atende na loja\nde ervas quem não pode ir ao hospital: chineses, mexicanos, prostitutas e baleados.\nVIRTUDE\nTrata qualquer um, de graça se for preciso, e nunca faz\nperguntas.\nP ECADO\nTambém não faz perguntas quando o Lótus lhe traz\nhomens que precisam “desaparecer” e quando faz\nabortos para Saint Edwiges.\nQUER\nQue seu diploma seja reconhecido; voltar a operar num\nhospital de verdade.\nTEM E\nQue um paciente morra e a polícia descubra a clínica.\nAlianças: Neutro; o Lótus o protege; Lindqvist o respeita. · Fala com: Medicina Legal, Idiomas\nHenry Lee\nJ O V E M A D V O G A D O, 2 7 A N O S\nNascido em Saint Village, cidadão americano e formado em Berkeley — o primeiro advogado chinês da\ncidade. Defende imigrantes nos tribunais de deportação.\nVIRTUDE\nGanhou casos impossíveis; já impediu 40 deportações.\nP ECADO\nFalsifica certidões de nascimento para os “filhos de\npapel” das Seis Companhias, cobrando caro dos que\npodem pagar.\nQUER\nQue os chineses de Saint Village sejam cidadãos de\nverdade.\nTEM E\nSer cassado; trair o bairro por medo.\nAlianças: Seis Companhias (clientes); o promotor Crane, que o vê como peão. · Fala com: Burocracia,\nIdiomas\nWong Shu\nP E N H O R I S T A , 6 3 A N O S\nHomem de óculos grossos que compra tudo e nunca pergunta de onde veio. Sua loja é o banco dos\npobres de Chinatown e o cemitério de provas da cidade.\nVIRTUDE\nEmpresta dinheiro sem juros às viúvas do bairro.\nP ECADO\nCompra objetos de mortos, armas de crimes e joias\nroubadas; guarda a arma de bolsa de Vivian Ashcroft e\nsabe o que ela significa.\nQUER\nUma loja na Rua Grant para o neto, com nome em inglês\nna fachada.\nTEM E\nSer envolvido num crime de branco: um chinês não pode\ntestemunhar, mas pode ser enforcado.\nAlianças: Vende a quem pagar; deve favores ao Lótus. · Fala com: Bajulação, Jogatina\nTEIA DE INTERESSES\nChinatown negocia com todos e não confia em ninguém. Suas alianças são contratos, e contratos têm cláusulas\nde saída.\nTabela SV.CH.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nLin Mei-Hua · Don Moretti · Ópio para Saint Edwiges em troca de\nnão serem invadidos pelos italianos\nMoretti tentar controlar o\nópio diretamente\nLin Mei-Hua · Mae Calloway · Uso dos túneis em troca de uma\nparte do rum\nO FBI de Prescott\ndescobrir os túneis\nLin Mei-Hua · Ruth Sayer · Mesada em troca de batidas só no\nJunco Negro\nSayer ser transferida por\nVoss\nKwan Ah-Lee · Padre Byrne · Sabotagem do ópio de Moretti em\ntroca de armas e dinheiro\nByrne fazer as pazes com\nMoretti\nSeis Companhias · Prefeitura · Votos e ordem no bairro em troca de\nlicenças e de vista grossa\nA Prefeitura apoiar a\ndeportação\nAda Pryor · Eleanor\nWhitcombe\nDoações em troca da imagem de\ncaridade de White Hills\nEleanor descobrir quem\nfinancia a Missão de fato\n(Lin)\nHenry Lee · Promotor Crane · Testemunhas chinesas contra os\nirlandeses em troca de proteção\ncontra deportações\nCrane perder a eleição\nWong Shu · Quem pagar · Objetos sem origem em troca de\ndinheiro\nUm objeto valer uma forca\nRUMORES DE CHINATOWN (1D8)\nTabela SV.CH.4 · O que se sussurra nas casas de chá\nD 8 R U MO R · V ER D AD E?\n1 O verdadeiro chefe do Lótus é uma mulher · Verdade\n2 Há uma cidade inteira sob Chinatown · Exagero: há túneis, adegas e galerias fechadas\n3 O Junco Negro recebe armas dos irlandeses · Verdade\n4 Ada Pryor resgata mulheres com um machado · Verdade\n5 O Templo de Tin Hau esconde ouro de 1906 · Falso; esconde a entrada para o Hotel St. Clair\n6 Ruth Sayer é amante de Lin Mei-Hua · Falso; é paga por ela\n7 Os ossos de Pedro Alvarado foram levados para Chinatown · Falso; estão no pilar 3\n8 Wong Shu tem a arma de um assassinato de White Hills · Verdade\nOS TÚNEIS\nOs túneis ligam porões de Chinatown a três outros lugares da cidade. Quem os conhece se move sem ser visto;\nquem não os conhece se perde.\nTabela SV.CH.5 · Rede de túneis\nSAÍD A · ENTR AD A EM C H INATO WN · U SO · PAR A U SAR\nPorão do Farol Azul\n(Saint Edwiges)\nCasa de Chá do Dragão\nJade\nRum de Mae e clientes do Lótus que\nnão querem ser vistos\nRep. +1 com o\nLótus\nGalpão 14\n(Embarcadouro)\nFumadouro da Rua\nGrant\nÓpio que chega pelo porto · Rep. +2 com o\nLótus\nAdega do Hotel St. Clair\n(Downtown)\nTemplo de Tin Hau · Vereadores que visitam Chinatown sem\npassar pela rua\nRep. +2 ou\nSubmundo (2)\nGalerias fechadas · — · Antigos depósitos lacrados em 1906;\nusados como prisão pelo Lótus\nAchar a entrada:\nArquitetura (2)\nSem guia, cada travessia exige um teste de Atletismo ou Furtividade Dif. 5. Uma falha deixa o PJ perdido por 1\nhora e o põe diante de um guarda do tong.\nCONDUZINDO CHINATOWN.\nOs investigadores brancos recebem +2 nas Dificuldades sociais, que caem para +0 se vierem acompanhados por\nalguém do bairro ou se usarem Idiomas (cantonês). Intimidação provoca represálias do tong na mesma noite.\nRespeito funciona com os velhos das Seis Companhias; Bajulação, com os comerciantes; Tranquilizar, com as\nmulheres da Missão. Evite estereótipos: cada morador tem nome, família e motivos próprios, como em\nqualquer outro bairro.","Saint Edwiges":"REGIÃO EM PROFUNDIDADE · 5 DE 7\nSaint Edwiges\nC omecei a cantar no Farol Azul em 1929, por dois dólares a noite e o jantar. O jantar era uma tigela de\nespaguete que o Gus fazia numa panela de alumínio atrás do bar, e era melhor que o de qualquer restaurante\nda Colina. Hoje ganho vinte por noite e canto também no Savoy, às duas, depois que a orquestra do Cuff fecha\no segundo set.\nO público das onze e o das duas não se misturam. Às onze vêm os homens de terno com a aliança no bolso do colete,\npedem as canções que as esposas gostam e vão embora antes da meia-noite. Às duas vêm os músicos de outras casas, as\ndançarinas do Golden Slipper com os pés inchados, um ou outro estivador que ganhou na escala e quer gastar antes de\nchegar em casa. Esses não pedem nada. Ficam ouvindo. Quando acaba, alguns batem palma com a mão aberta na\nmesa, que é como se aplaude no Savoy.\nTenho um apartamento pequeno na Rua Pacific que o Sr. Moretti paga. Tenho também um homem importante que sobe\na minha escada às quintas e acha que fui eu quem escolheu ele. Eu não conto ao Sr. Moretti o que esse homem diz.\nEscrevo. O Sr. Moretti manda buscar o caderno aos sábados.\nL O L A M A R C H E T T I , C A N T O R A\nNoite no Clube Savoy.\nSaint Edwiges nasceu como a zona dos marinheiros da Corrida do Ouro: saloons, pensões, bordéis e homens\ndopados para acordar em navios rumo a Xangai. Os reformistas a fecharam em 1917. A Lei Seca a reabriu em\n1920, e Sal Moretti a transformou na capital da noite da Costa Oeste. Hoje são seis quarteirões de luz néon\nentre Chinatown e o Embarcadouro, onde o jazz toca até as quatro e o rum corre mais que a água.\nNada aqui é o que parece. A loja de chapéus é um cassino; a barbearia vende apostas; a floricultura é uma\nagência de garotas; o salão de dança “familiar” tem quartos no andar de cima. Cada porta tem um olho\nmágico, e cada olho mágico tem um preço. Os Moretti não precisam de capangas nas esquinas: precisam de\ncontadores, porque Saint Edwiges rende mais que o porto inteiro.\nÉ também o único bairro onde a cidade se mistura de verdade. Herdeiros de White Hills dançam com\nestivadores; músicos negros de Nova\nOrleans tocam para vereadores; dançarinas mexicanas, italianas e irlandesas dividem camarins; tiras de folga\nbebem ao lado de quem prenderam na semana anterior. A noite iguala todos, desde que paguem.\nPara os investigadores, Saint Edwiges é o mercado de informações da cidade. Tudo se compra aqui — inclusive\na verdade. O problema é que tudo também se vende, e quem faz perguntas demais no Il Paradiso amanhece\nno Píer 9. Com o fim da Lei Seca à vista, os Moretti precisam legalizar omundo nervoso. império antes que o\nrum barato os torne obsoletos, e essa corrida está deixando todo\nCRÔNICA · DEZ CENTAVOS POR DANÇA Dottie Flynn, 22 anos, dançarina de aluguel do Salão Golden\nSlipper\nAcordo às três da tarde com a boca amarga. Passo o vestido verde, o único que não tem remendo à vista, e pinto as unhas no\nquarto que divido com a Rita na Pensão do Marinheiro. Às oito estou no salão. Cada dança custa um bilhete de dez centavos;\neu fico com quatro. Uma noite boa são cento e vinte danças. Meus pés sangram a partir da octogésima.\nOs homens vêm de toda parte. Estivador que dança como quem carrega saco. Herdeiro de White Hills que pisa no meu pé e\npede desculpa em francês. Vereador que dá um dólar inteiro para eu dizer que ele é bonito. Um tira de folga que me segura\nforte demais e diz que, se eu quiser, ele “cuida de mim”. Não quero. Sei como os tiras cuidam.\nÀs quatro da manhã o Cuff Baptiste toca a última no Savoy, do outro lado da rua, e a gente vai ouvir encostada na porta. É\na única música da noite que ninguém paga para dançar. Depois volto para a pensão sob a neblina, sapatos na mão, com\nonze dólares no sutiã. Mando cinco para minha mãe em Sacramento. Ela pensa que trabalho numa loja de chapéus. De certa\nforma, trabalho.\nO QUE MOVE A NOITE\nTabela SV.CB.1 · Poder em Saint Edwiges\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nFamília Moretti · Dona de quase todos os cassinos e clubes; cobra\n“aluguel” dos demais\nDa Delegacia (Kowalski), do rum de\nMae e do ópio do Lótus\nOs músicos · Sem eles, os clubes ficam vazios; o sindicato dos\nmúsicos negocia direto com Moretti\nDos donos dos clubes e da\ntolerância racial da noite\nAs casas das\nmadames\nBordéis independentes que pagam taxa a Moretti · De clientes de White Hills e da\nPrefeitura que precisam de\ndiscrição\nSargento Kowalski · Coleta a propina e decide qual clube sofre batida · De Voss e de Moretti\nA Liga da\nTemperança\nProtestos, petições e pressão sobre a Prefeitura · Das senhoras de White Hills,\nalgumas casadas com clientes\nLUGARES DA SAINT EDWIGES\nTabela SV.CB.2 · Endereços\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nCassino Il Paradiso · Roleta, pôquer e bacará atrás da Chapelaria Moretti;\nescritório de Sal no mezanino\nDívidas de jogo da cidade inteira;\nquem se reuniu com Sal\nFarol Azul · Bar de fachada com porão de jazz e uma porta para os\ntúneis de Chinatown\nTudo o que Gus Halloran ouviu até\nas 4h\nClube Savoy · Salão de dança com orquestra de 12 músicos negros; o\núnico lugar da cidade onde negros e brancos dançam\nno mesmo salão\nQuem dançou com quem; os\nsegredos de Lola Marchetti\nCasa da Madame\nCeleste\nBordel elegante de três andares, com clientes de White\nHills e da Prefeitura\nLivro de clientes (nomes, datas,\npreferências)\nBarbearia Fratelli · Barbearia de dia, banca de apostas de noite · Apostas em lutas e corridas\ncombinadas; quem está devendo\nFloricultura Bella\nRosa\nAgência de “acompanhantes” para hotéis do Distrito · Quem pediu uma garota ao Hotel\nSt. Clair, e o que ela viu\nSalão de Boxe\nGallagher\nAcademia e ringue de lutas clandestinas · Lutadores comprados; capangas de\naluguel\nPensão do\nMarinheiro\nQuartos por hora; marinheiros, fugitivos e gente sem\nnome\nQuem chegou à cidade e não quer\nser encontrado\nGENTE DA NOITE\nEm Saint Edwiges, todos vendem alguma coisa: música, corpo, sorte, silêncio. A pergunta não é quem é\nhonesto, mas quem ainda se lembra do preço que pagou para estar ali.\nDon Salvatore “Sal” Moretti\nC H E F E DA FA M Í L I A M O R E T T I , 6 0 A N O S\nChegou da Sicília aos 12 anos, engraxou sapatos em Saint Edwiges e construiu um império com uma\nnavalha e uma régua de contador. Fala baixo, cita Dante e trata cada um pelo nome. Sabe que a Lei Seca\nvai acabar e que, sem ela, sua família precisa virar respeitável ou morrer.\nVIRTUDE\nMantém um fundo para as viúvas da família e paga a\nfaculdade de filhos de imigrantes italianos que nunca\nsoube quem são.\nP ECADO\nOrdenou dezenas de mortes; entregou Dutch Kessler à\npolícia para fazer as pazes com Voss; financia em segredo\no promotor Crane para destruir os irlandeses.\nQUER\nLegalizar os cassinos e ver o neto formado em direito.\nTEM E\nMorrer como gângster, e não como homem de negócios;\nque Vincent destrua tudo.\nAlianças: Voss (paga), Lin Mei-Hua (ópio), Crane (secreto), juiz Hale; inimigo mortal de Byrne. · Fala com:\nRespeito\nVincent Moretti\nF I L H O D E S A L , 3 1 A N O S\nEducado em Stanford, elegante, impaciente. Acha que o pai é um velho que não entende o futuro. Quer\ntransformar a família em empresa — mais rápido do que o pai permitiria.\nVIRTUDE\nFoi ele quem convenceu o pai a parar com o tráfico de\nmulheres em 1931.\nP ECADO\nVende informações à Irmandade para enfraquecer o pai\ne forçá-lo a se aposentar; não sabe que Byrne matou seu\navô.\nQUER\nComandar a família e levá-la para Las Vegas.\nTEM E\nQue o pai descubra a traição; viver para sempre à\nsombra dele.\nAlianças: Irmandade (secreta), Mae Calloway (negócios); despreza Kowalski. · Fala com: Bajulação,\nJogatina\nLola Marchetti\nC A N T O R A D O FA R O L A Z U L E D O C L U B E S AV OY, 3 0 A N O S\nVoz rouca, olhos tristes e um passado em Chicago que ela não discute. Amante do prefeito Whitcombe há\ndois anos. Perdeu um bebê depois de ser “assustada” por Kowalski a mando de Eleanor Whitcombe.\nVIRTUDE\nProtege as dançarinas mais jovens, ensinando-as a não\ndepender de nenhum homem.\nP ECADO\nSeduziu o prefeito por encomenda de Sal Moretti; passa\na Sal tudo o que Whitcombe diz na cama.\nQUER\nVingança contra Eleanor; sair da cidade com dinheiro\nsuficiente para nunca mais cantar.\nTEM E\nQue Moretti a descarte quando ela não for mais útil.\nAlianças: Moretti (empregador), Whitcombe (amante), Hattie Brooks (desconfiança). · Fala com:\nBajulação, Tranquilizar\nGus Halloran\nB A R M A N D O FA R O L A Z U L , 4 5 A N O S\nEx-pugilista peso médio de Boston, nariz quebrado três vezes, memória perfeita. Serve bebida ilegal\ncom a calma de um padre.\nVIRTUDE\nJá escondeu três pessoas perseguidas no porão do bar,\narriscando tudo.\nP ECADO\nDeve 2 mil dólares aos Moretti e paga entregando\ninformações sobre clientes, inclusive sobre amigos.\nQUER\nComprar o próprio bar quando a Lei Seca cair.\nTEM E\nSer obrigado a escolher entre um amigo e a dívida.\nAlianças: Moretti (dívida), Irmandade (é irlandês), PJs (se pagarem bem). · Fala com: Bajulação, Gíria das\nRuas\nMadame Celeste Duval\nD O N A DA C A S A DA M A DA M E C E L E S T E , 5 2 A N O S\nNascida Mary Kowalczyk em Pittsburgh, reinventou-se como francesa em 1912. Sua casa é a mais discreta\nda cidade, e seu livro de clientes é o documento mais perigoso de Saint Village.\nVIRTUDE\nPaga médico, escola e uma pensão para cada mulher que\ndeixa sua casa; ninguém é forçado a ficar.\nP ECADO\nChantageia clientes há vinte anos e já vendeu o nome de\numa garota grávida ao pai dela, para que a “levassem de\nvolta”.\nQUER\nAposentar-se em Paris de verdade.\nTEM E\nQue o livro seja roubado e ela, morta por ele.\nAlianças: Paga Moretti; protegida por Pell e pelo juiz Hale (clientes). · Fala com: Bajulação, Respeito\nSargento “Mão Pesada” Kowalski\nS A R G E N T O DA S A I N T E D W I G E S , 4 0 A N O S\nPolonês do Distrito de Waterford, ex-estivador, enorme. Coleta a propina dos clubes toda sexta e decide\nqual lugar sofre batida. Bate em quem não pode revidar.\nVIRTUDE\nSustenta sozinho a mãe doente e três irmãs; nunca bebe\nem serviço.\nP ECADO\nEspancou Lola Marchetti grávida a mando de Eleanor\nWhitcombe e não perdeu uma noite de sono.\nQUER\nSer tenente e ter uma casa com quintal no Distrito de\nWaterford.\nTEM E\nQue alguém mais forte cobre o que ele fez.\nAlianças: Moretti, Voss, Eleanor Whitcombe (serviços); primo distante de Madame Celeste, que não sabe. ·\nFala com: Intimidação (só funciona se o PJ for maior), Jargão de Polícia\nClarence “Cuff” Baptiste\nL Í D E R DA O R Q U E S T R A D O C L U B E S AV OY, 3 8 A N O S\nTrompetista de Nova Orleans que tocou com os maiores e veio para o oeste fugir das leis Jim Crow. Sua\norquestra enche o Savoy toda noite e lhe dá um poder que ninguém mais negro tem na cidade.\nVIRTUDE\nContrata músicos negros e garante que sejam pagos igual\naos brancos; enfrentou Moretti para isso.\nP ECADO\nVende heroína a outros músicos para manter a orquestra\nfuncionando; já viu dois deles morrerem de overdose.\nQUER\nGravar um disco e tocar no Carnegie Hall.\nTEM E\nSer linchado; que Saint Edwiges acabe junto com a Lei\nSeca.\nAlianças: Moretti (empregador), Lin Mei-Hua (heroína), Lola (amizade). · Fala com: Respeito, Bajulação\nNick “Moeda” Santangelo\nC R U P I Ê D O I L PA R A D I S O, 2 9 A N O S\nMãos rápidas, sorriso fácil, sobrinho distante de Sal. Sabe exatamente quem deve quanto à família — e\nquanto vale essa informação.\nVIRTUDE\nPerdoa discretamente as dívidas de jogo de operários\ndesesperados, mexendo nos registros.\nP ECADO\nRouba o cofre do cassino há seis meses, centavo por\ncentavo; já culpou um garçom, que desapareceu.\nQUER\nJuntar 10 mil dólares e fugir para Havana com uma\ndançarina.\nTEM E\nQue Sal descubra o roubo (gancho do Caso 3 da tabela\nSV.8).\nAlianças: Vincent Moretti (amigo), dançarinas do Savoy; teme todos os outros. · Fala com: Jogatina,\nBajulação\nTEIA DE INTERESSES\nEm Saint Edwiges, as alianças duram enquanto o dinheiro entra. Quando a música para, todos procuram a\nporta dos fundos.\nTabela SV.CB.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nSal Moretti · Capitão Voss · Envelopes semanais em troca de\nbatidas só nos rivais\nVoss se aliar a Crane — ou\nCrane ganhar sem Voss\nSal Moretti · Lola Marchetti · Proteção e salário em troca dos\nsegredos de Whitcombe\nLola se apaixonar de\nverdade pelo prefeito\nVincent Moretti · Padre Byrne · Informações sobre o pai em troca de\napoio para assumir a família\nVincent descobrir que\nByrne matou seu avô\nMadame Celeste · Juiz Hale e Capitão\nPell\nDiscrição em troca de proteção legal O livro de clientes vazar\nKowalski · Eleanor\nWhitcombe\nServiços sujos em troca de dinheiro\nvivo\nLola falar com os PJs\nCuff Baptiste · Lin Mei-Hua · Heroína para os músicos em troca de\ndinheiro e de silêncio sobre a origem\nUm músico morrer em\npúblico\nGus Halloran · Moretti · Informações sobre clientes em troca\nde mais prazo na dívida\nPedirem a ele que entregue\num amigo\nNick Santangelo · Vincent Moretti · Cobertura nos livros em troca de\nlealdade\nVincent precisar de um\nbode expiatório\nRUMORES DA NOITE (1D8)\nTabela SV.CB.4 · O que se ouve no balcão\nD 8 R U MO R · V ER D AD E?\n1 Sal Moretti vai se aposentar depois da Lei Seca · Falso; vai legalizar e continuar\n2 Lola Marchetti é espiã de alguém · Verdade: de Moretti\n3 O livro da Madame Celeste derrubaria metade da Prefeitura · Verdade\n4 Há um cofre do Il Paradiso com o dinheiro de Mae Calloway · Falso; o dinheiro dela está no Banco Pacific Trust\n5 Kowalski matou um homem no ringue do Gallagher · Verdade, em 1928\n6 Vincent Moretti quer matar o pai · Exagero: quer aposentá-lo\n7 O Savoy vai ser fechado pela Liga da Temperança · Possível, se a Prefeitura recuar 2 segmentos\n8 Alguém está roubando o cassino por dentro · Verdade: Nick Santangelo\nUMA NOITE NA COSTA (1D6 POR HORA)\nQuando os PJs passam a noite circulando por Saint Edwiges atrás de alguém, role 1d6 a cada hora de jogo. Cada\nevento pode ser ignorado ou virar uma cena.\nTabela SV.CB.5 · Eventos noturnos\nD 6 EV ENTO · O Q U E O FER EC E O U AMEAÇ A\n1 Batida de Kowalski Um clube é fechado por uma hora; quem não pagar a propina é levado. Fuga: Atletismo Dif. 4.\n2 Briga no balcão · Dois estivadores irlandeses contra capangas de Moretti. Ajudar um lado: +1 de reputação com\nele, −1 com o outro.\n3 Um rosto\nconhecido\nUm PNJ de White Hills ou do Distrito onde não deveria estar. Pista bônus de chantagem.\n4 Mesa quente · Convite para o pôquer do Il Paradiso. Jogatina Dif. 5: ganhar 1d6 × 20 dólares ou uma\ninformação.\n5 Alguém está\nseguindo\nUm capanga de Moretti segue os PJs. Notar: Faro de Encrenca Dif. 4.\n6 A música para · Um tiro no salão. Sangue-Frio −2; a cena vira um novo homicídio para investigar.\nCONDUZINDO A SAINT EDWIGES.\nAqui a Dificuldade social é baixa (4), mas tudo custa dinheiro: cada informação de rua exige 5 a 20 dólares ou\num gasto de 1 ponto de Gíria das Ruas. Bajulação funciona com as dançarinas e os músicos; Jogatina, com os\ncrupiês; Respeito, apenas com os Moretti. Quem usa Intimidação no território de Moretti sem permissão\nperde 1 de reputação com a família na mesma noite.","Embarcadouro e Píer 9":"REGIÃO EM PROFUNDIDADE · 6 DE 7\nEmbarcadouro e Píer 9\nO Embarcadouro é uma avenida de três quilômetros ao longo da baía, onde cinquenta píeres numerados se\nestendem como dedos sobre a água. Navios de Xangai, Manila, Valparaíso e Vancouver descarregam café, seda,\nmadeira, açúcar — e, nos porões, tudo o que a lei proíbe. Galpões de ferro corrugado, guindastes a vapor,\ntrilhos de trem e um cheiro permanente de óleo, peixe e sal.\nTodo dia, às seis da manhã, mil e quinhentos estivadores se aglomeram diante do Píer 9 para o\n“shape-up”: o capataz aponta para quem vai trabalhar naquele dia. Os escolhidos pagam a ele um dólar por\ndia de trabalho; os outros voltam para casa sem nada. O sistema é a raiz de tudo no Embarcadouro: quem\ncontrola o capataz controla a fome de mil homens, e quem controla a fome controla os votos, os punhos e as\ngreves.\nE m 1912, quando fundamos a Irmandade no porão da Rua Dolores, éramos onze homens e um padre que tinha\nmedo de ser visto conosco. Tínhamos uma ideia simples: o capataz que escolhe quem trabalha no Píer 9 às seis\nda manhã não podia mais vender a vaga por um dólar. Levou cinco anos, três greves e quatro enterros para\nacabar com isso. Hoje o capataz é nosso. O dólar continua sendo cobrado. Vai para o fundo de greve, para a escola\nnoturna, para a pensão das viúvas, e um pouco, eu não nego, para mim.\nÀs seis, ainda vou ao píer olhar o shape-up. Mil e quinhentos homens em semicírculo, as mãos nos bolsos, fumaça\nsaindo das bocas no frio. O capataz aponta com o dedo, e os escolhidos vão para os guindastes sem olhar para trás,\nporque olhar para trás é ver os outros. Eu fico ali até o último ir embora. Alguns me cumprimentam. Outros me olham\ncomo olhavam o capataz de antes.\nO velho Moretti tomou os armazéns do Píer 12 ao 18 numa noite de 1922. O filho dele acha que fui eu quem matou o\navô dele em 1929. Ele está certo, mas não tem como provar, e eu me confessei com o Padre Feeney na semana seguinte.\nComunguei no domingo.\nD E C L A N “ O P A D R E ” B Y R N E , I R M A N D A D E\nA Irmandade Irlandesa manda na estiva: no sindicato, nos capatazes e nos homens. A Família Moretti manda\nnos armazéns: no que entra, no que sai e no que se perde no caminho. A fronteira entre os dois é o Píer 9, onde\nos dois mundos se encontram todo dia — e onde aparecem os corpos. A polícia chama de “acidentes de\ntrabalho”. Ninguém no cais acredita.\nPara os investigadores, o Embarcadouro é onde as provas chegam e partem pela água. É também o barril de\npólvora da cidade: a greve geral marcada para maio pode transformar o cais num campo de batalha entre\ngrevistas, fura-greves de Moretti e a polícia de Voss. Qualquer investigação aqui toca nessa ferida.\nCRÔNICA · O DEDO DO CAPATAZ Paddy Quinn, 38 anos, estivador sem vaga fixa\nÀs cinco e meia já tem mil homens na frente do Píer 9, ombro com ombro, bafo de café e tabaco. A neblina ainda está deitada\nna água. Às seis em ponto o capataz sobe no caixote e começa a apontar. Você, você, você. Ele não olha nos olhos. Olha para\nas mãos, para ver quem já pôs o dólar no bolso do casaco dele na noite anterior.\nHoje ele não apontou para mim. Ontem também não. Na semana passada, três dias. Tenho quatro filhos e uma mulher que\nlava roupa para fora. Fico parado enquanto os escolhidos entram, e os outros vão saindo devagar, cada um para um lado,\nsem conversar. Vergonha não se divide.\nVou até a cantina da Irmã Agnes. Sopa de batata e pão de ontem. Ela pergunta pelo meu filho mais velho, que anda com o\nTommy Riordan. Digo que ele está bem. Não está. À tarde, no pub, o rapaz do sindicato fala da greve de maio. Diz que vamos\nparar o porto e que eles vão ter que nos escolher todos. O Padre Byrne vai falar no domingo. Eu vou estar lá. Não porque\nacredito, mas porque não tenho mais nada para fazer às seis e um.\nQUEM MANDA NO CAIS\nTabela SV.EM.1 · Poder no Embarcadouro\nQ U EM · C O MO MAND A · D E Q U EM D EPEND E\nIrmandade Irlandesa · Sindicato dos Estivadores, capatazes do shape-up,\npunições no cais\nDa lealdade dos estivadores e da\npaciência deles\nFamília Moretti · Galpões, seguro “contra roubo”, fura-greves · De a carga chegar inteira e no\nprazo\nMae Calloway · Lanchas de rum, o Galpão 14, a Guarda Costeira\ncomprada\nDos capatazes que olham para o\noutro lado\nCompanhias de\nnavegação\nContratam e demitem, financiam os fura-greves · De um porto sem greve\nPatrulheiro Dunne e\na polícia\nPresença mínima, máxima conveniência · Da Irmandade, que os alimenta\nLUGARES DO CAIS\nTabela SV.EM.2 · Endereços\nLO C AL · O Q U E É · O Q U E SE D ESC O BR E ALI\nPíer 9 · O píer do shape-up, fronteira entre irlandeses e\nitalianos; os corpos boiam aqui\nTestemunhas da madrugada;\nmarcas de arrasto nas tábuas\nGalpão 14 · Armazém de “frutas” de Mae Calloway, com caixas que\ncheiram a rum e um alçapão para os túneis\nO livro-caixa de Teddy (Caso 1);\nrotas e horários do contrabando\nSalão do Sindicato\ndos Estivadores\nPorão com bancos, cerveja choca e a lista negra pregada\nna parede\nQuem está organizando a greve;\nquem foi expulso e por quê\nArmazéns Moretti\n(Píeres 12–18)\nGalpões guardados por homens de terno e cães · Carga desviada; o “seguro” que os\nnavios pagam\nBar do Otto · Taverna de marinheiros onde Otto Brandt bebe antes\nda obra\nO que os engenheiros da Ponte\nfalam quando estão bêbados\nCapitania do Porto · Escritório de registro de navios, cargas e tripulações · Manifestos falsos; navios que\nchegaram e não constam\nCantina da Irmã\nAgnes\nSopa grátis para estivadores desempregados, perto do\nPíer 9\nQuem está passando fome; quem\nfoi visto com quem na noite\nanterior\nCais da Guarda\nCosteira\nLanchas oficiais e o escritório do Capitão Hollis · Quais noites a patrulha “está de\nfolga”\nGENTE DO CAIS\nNo cais, a lealdade é medida em turnos de trabalho. Todo mundo tem uma família para alimentar, e a moral\nmuda de lado conforme o dia de pagamento.\nDeclan “o Padre” Byrne\nL Í D E R DA I R M A N DA D E I R L A N D E S A , 4 7 A N O S\nEx-seminarista de Cork que trocou a batina pela causa operária depois de ver estivadores morrerem de\nfome no shape-up. Fala em salmos e em salários. Para quatro mil homens, ele é a única voz que os\ndefende. Para Sal Moretti, é o homem que matou seu pai.\nVIRTUDE\nCriou o fundo de greve, a escola noturna e o seguro para\nviúvas do sindicato; tirou milhares de famílias da miséria.\nP ECADO\nMatou Don Vito Moretti, pai de Sal e avô de Vincent,\ncom as próprias mãos na guerra de 1929; chantageia o\nprefeito com o concreto da Ponte em vez de salvar os\noperários; usa o Junco Negro para traficar armas.\nQUER\nControle total das docas — e, com ele, da cidade.\nTEM E\nQue seus homens descubram que ele negocia com o\nprefeito às escondidas.\nAlianças: Seamus Doyle, Peg Donnelly, Kwan Ah-Lee, Vincent Moretti (secreto), Dunne. · Fala com:\nTranquilizar, Política\n“Rainha” Mae Calloway\nC O N T R A B A N D I S T A D E R U M , 4 5 A N O S\nViúva de um capitão norueguês, herdou o barco e a rota do marido e fez dela a maior rede de\ncontrabando da Costa Oeste. Pilota as próprias lanchas, atira melhor que seus homens e não paga\nninguém em dia.\nVIRTUDE\nEmprega viúvas e filhos de pescadores mortos; nunca\nvendeu rum envenenado, ao contrário dos rivais.\nP ECADO\nEstá vendendo a rota ao FBI em troca de imunidade, o\nque vai entregar à cadeia todos que trabalham para ela.\nQUER\nSair do contrabando antes da Lei Seca acabar, com um\nbanco no seu nome.\nTEM E\nPrisão; ser morta por Moretti se ele descobrir a delação.\nAlianças: Lin Mei-Hua (túneis), Banco Pacific Trust, Capitão Hollis, Sargento Purcell, Agente Prescott\n(secreto). · Fala com: Submundo, Jogatina\nTommy “Faísca” Riordan\nP I S T O L E I R O DA I R M A N DA D E , 2 2 A N O S\nNascido no Distrito de Waterford, órfão de um estivador esmagado por uma carga. Byrne o criou como\num filho e o transformou em arma. Tommy quer ser lenda — e tem medo de ser só mais um nome na\nparede do sindicato.\nVIRTUDE\nDá metade do que ganha à mãe de um amigo morto.\nP ECADO\nJá matou quatro homens, um deles pelas costas.\nQUER\nCasar-se com Angela Moretti, filha de Sal, e fugir.\nTEM E\nQue Byrne descubra o romance; que Angela o veja\nmatar.\nAlianças: Leal a Byrne até que Angela peça o contrário. · Fala com: Intimidação, Bajulação (com Angela)\nPatrulheiro Mickey Dunne\nPAT R U L H E I R O D O E M B A R C A D O U R O, 3 4 A N O S\nPrimo do Padre Byrne, uniforme sempre amarrotado, mão sempre aberta. Patrulha o cais há dez anos\nsem fazer uma única prisão de irlandês.\nVIRTUDE\nAvisa as famílias quando um estivador morre, antes que\nleiam no jornal.\nP ECADO\nEncobre os crimes da Irmandade e entregou à polícia\ndois fura-greves que depois apareceram mortos.\nQUER\nVer a Irmandade no poder e ganhar uma promoção.\nTEM E\nQue a Corregedoria de Garrity o use para chegar a\nByrne.\nAlianças: Byrne (família), Kwan Ah-Lee (troca de favores), Voss (nominalmente). · Fala com: Jargão de\nPolícia, Tranquilizar\nBig Lou Ferraro\nC A PAT A Z D O S A R M A Z É N S M O R E T T I , 5 0 A N O S\nItaliano enorme e cordial, que trata seus homens como família e os paga melhor que a Irmandade.\nRecruta fura-greves entre italianos e mexicanos desempregados.\nVIRTUDE\nNunca abandona um homem ferido; pagou o tratamento\nde um estivador irlandês ferido nos armazéns.\nP ECADO\nComanda os fura-greves que enfrentam os grevistas com\nbarras de ferro; fez desaparecer um ladrão de carga no\nano passado.\nQUER\nQue a greve fracasse e ele ganhe um armazém próprio.\nTEM E\nSer o próximo corpo no Píer 9.\nAlianças: Moretti (lealdade), Garagem Ferraro (é seu irmão). · Fala com: Respeito, Intimidação\nIrmã Agnes O’Malley\nF R E I R A DA I G R E JA D E S ÃO B R E N DA N , 5 6 A N O S\nDirige a cantina dos estivadores e conhece o nome de cada filho do cais. Despreza Byrne por ter trocado\nDeus pela política e despreza Moretti por ter trocado Deus pelo dinheiro.\nVIRTUDE\nAlimenta trezentos homens por dia; já levou presos de\nBlack Rock ao Dr. Marlowe para salvá-los da solitária.\nP ECADO\nEscreve cartas anônimas ao FBI denunciando irlandeses\ne italianos, mesmo sabendo que inocentes vão cair junto.\nQUER\nVer o cais livre dos dois — mesmo que isso custe a greve.\nTEM E\nQue descubram as cartas e queimem a igreja.\nAlianças: Marlowe, Ezra Pike, Sra. Rosales; ninguém nas facções. · Fala com: Tranquilizar\nCapitão Hollis\nC O M A N DA N T E DA G U A R DA C O S T E I R A LO C A L , 5 8 A N O S\nOficial de cabelos brancos, trinta anos de mar, a um ano da aposentadoria. Conhece cada corrente da baía\ne cada lancha que a atravessa.\nVIRTUDE\nJá salvou dezenas de pescadores de naufrágios, inclusive\ncontrabandistas que pediram socorro.\nP ECADO\nRecebe de Mae Calloway para estar de folga nas noites\ncertas; deixou um contrabandista rival se afogar.\nQUER\nAposentar-se com pensão integral e uma casa na costa.\nTEM E\nQue o FBI audite seus horários.\nAlianças: Mae Calloway (pagamento), Agente Prescott (que o vigia). · Fala com: Respeito, Burocracia\nRosa Benedetti\nV I Ú V A D E E S T I V A D O R , 2 8 A N O S\nSeu marido “caiu” de um guindaste no mês passado. Deixou um bilhete dizendo que tinha visto algo no\nGalpão 14. Rosa não acredita em acidente e não tem dinheiro para um advogado.\nVIRTUDE\nCoragem para fazer perguntas que ninguém mais faz no\ncais.\nP ECADO\nFoi amante de Big Lou Ferraro antes de se casar; sabe\nque o marido descobriu e o odiava por isso.\nQUER\nJustiça — ou ao menos a indenização para os três filhos.\nTEM E\nQue a verdade seja pior do que ela imagina.\nAlianças: Ninguém; procura os PJs (gancho 1 da tabela SV.8). · Fala com: Tranquilizar, Faro para Mentiras\nTEIA DE INTERESSES\nNo cais, irlandeses e italianos se odiam em público e negociam à noite. Todo o porto depende de que nenhum\ndos dois vença de vez.\nTabela SV.EM.3 · Alianças por interesse\nD E · PAR A · O Q U E U M D Á AO O U TR O · O Q U E R O MPER IA O LAÇ O\nPadre Byrne · Prefeito\nWhitcombe\nSilêncio sobre o concreto da Ponte\nem troca do controle das docas\nOs operários descobrirem\na chantagem\nPadre Byrne · Vincent Moretti · Apoio para Vincent assumir a família\nem troca de informações\nVincent descobrir quem\nmatou seu avô\nMae Calloway · Agente Prescott · A rota do rum em troca de\nimunidade\nMoretti descobrir a delação\nMae Calloway · Capitão Hollis · Dinheiro em troca de noites sem\npatrulha\nO FBI auditar a Guarda\nCosteira\nBig Lou Ferraro · Companhias de\nnavegação\nFura-greves em troca de contratos\npara Moretti\nA greve virar massacre e\nmanchete\nTommy Riordan · Angela Moretti · Amor em troca de uma saída das\nduas famílias\nQualquer um dos pais\ndescobrir\nMickey Dunne · Kwan Ah-Lee · Vista grossa no cais em troca de\ninformações sobre o Lótus\nLin Mei-Hua descobrir\nIrmã Agnes · Agente Prescott · Denúncias anônimas em troca de\nnada — só fé\nPrescott revelar a fonte\nRUMORES DO CAIS (1D8)\nTabela SV.EM.4 · O que se diz no shape-up\nD 8 R U MO R · V ER D AD E?\n1 A greve geral vai começar em maio · Verdade, se o relógio da Irmandade chegar a 4\n2 Mae Calloway está falando com os federais Verdade\n3 O marido de Rosa Benedetti foi morto por\nBig Lou\nMeia verdade: foi morto por ter visto o rum no Galpão 14; Big Lou\nsabe por quem\n4 Tommy Riordan namora a filha de Moretti Verdade\n5 Há um túnel do Galpão 14 até Chinatown · Verdade\n6 O Padre Byrne vai concorrer a vereador · Falso; quer mais que isso\n7 Os fura-greves vão chegar de trem de Los\nAngeles\nVerdade, se a greve durar mais de uma semana\n8 O Capitão Hollis nunca patrulha às sextas · Verdade\nO SHAPE-UP E A GREVE\nO shape-up é uma cena recorrente: os PJs podem usá-lo para se infiltrar entre os estivadores, encontrar\ntestemunhas ou sentir a temperatura da greve.\nTabela SV.EM.5 · Usando o shape-up\nO BJETIV O · TESTE O U G ASTO · R ESU LTAD O\nSer escolhido para\ntrabalhar\nAtletismo Dif. 4, ou 1\ndólar ao capataz\nUm dia inteiro no cais: acesso aos navios e aos galpões\nOuvir as conversas da fila · Gíria das Ruas (0) · Um rumor da tabela SV.EM.4\nEncontrar uma\ntestemunha\nTranquilizar (1) · Alguém que viu o que aconteceu no Píer 9, mas só fala longe\ndo capataz\nMedir a greve · Política (1) · O Diretor revela quantos segmentos faltam para a greve\ngeral (relógio da Irmandade)\nTabela SV.EM.6 · A greve de maio\nSE O S PJS… · C O NSEQ U ÊNC IA\nApoiarem a greve Irmandade +1 de reputação, Moretti −1. A greve dura 1d6 semanas; a “Quinta-feira Sangrenta” ( julho)\nacontece com certeza.\nSabotarem a greve Moretti +1, Irmandade −2. A greve acaba em 3 dias; o Padre Byrne quer os PJs mortos.\nMediarem um\nacordo\nExige Respeito (2) com os dois lados e uma prova contra Voss. Sem Quinta-feira Sangrenta; ambos os\nrelógios recuam 1.\nFicarem de fora · O Diretor resolve com a regra de Guerra de Territórios (SV.10).\nCONDUZINDO O EMBARCADOURO.\nNo cais, roupas de trabalho valem mais que um distintivo: investigadores de terno recebem +1 nas Dificuldades\nsociais. Intimidação funciona, mas sempre é retribuída. Respeito só funciona com os velhos estivadores; Gíria\ndas Ruas e Tranquilizar abrem quase todas as bocas. Depois das 18h, com a neblina, toda cena no cais tem 1\nchance em 6 de um encontro violento.","Distrito de Waterford":"REGIÃO EM PROFUNDIDADE · 7 DE 7\nDistrito de Waterford\nL avo roupa para fora desde os catorze anos, num tanque de cimento no quintal da Rua Dolores, com a água que\nesquento no fogão. Tenho as mãos rachadas no inverno e no verão. Criei sete crianças que não eram minhas,\numa de cada vez, conforme foram aparecendo na minha porta: filho de mulher que morreu de parto, filha de\nhomem que foi para Black Rock, um menino que dormia embaixo da escada da igreja e que o Padre Feeney trouxe pela\nmão.\nO Tommy chegou com quatro anos, numa noite de neve, com um casaco de homem que arrastava no chão. Hoje ele tem\nvinte e dois, usa duas pistolas e me beija na testa todo domingo antes da missa das nove. Quando a polícia vem\nperguntar por ele, eu digo que não o vejo há semanas, e a arma dele está embaixo do meu colchão, enrolada numa\nfronha. Dorme comigo. Já me acostumei com o volume.\nDuas das sete crianças estão no cemitério de São Brendan. Uma morreu de tifo em 1918. A outra, a Nora, levou uma\nbala na porta da Waterford em 1932, de passagem, com uma cesta de pão no braço. Não estava na greve. Estava indo\npara casa.\nB R I D G E T “ B I D D Y ” R I O R D A N , L AVA D E I R A\nVelório no Distrito de Waterford.\nO Distrito de Waterford se espalha pelo vale plano ao sul de Downtown, onde o vento da baía não chega e a\nneblina fica presa entre os cortiços. São trinta quarteirões de casas de madeira de três andares, varais cruzando\nas ruas, pubs em cada esquina e a torre da Igreja de São Brendan no centro, visível de qualquer telhado. Aqui\nmoram os estivadores, os ferreiros da Ponte, os carroceiros, as lavadeiras e os desempregados que fazem fila\npara a sopa da Irmã Agnes.\nOs irlandeses chegaram em 1850, fugindo da fome, e encontraram outra fome do lado de cá. Construíram o\nbairro com as próprias mãos, a Igreja com centavos e o sindicato com sangue. Nas ruas da beirada vivem os\nmais novos: mexicanos que chegaram depois da Revolução, poloneses das fundições, italianos pobres demais\npara Saint Edwiges. Eles dividem a miséria, mas não os pubs.\nA Irmandade Irlandesa nasceu aqui, num porão da Rua Dolores, em 1912. Para o bairro, ela não é uma gangue:\né a única coisa que fica entre uma família e a rua. A Irmandade paga o aluguel de quem foi demitido, o enterro\nde quem caiu do guindaste e a fiança de quem bateu num capataz. Em troca, pede silêncio, votos e, às vezes,\num filho. O Padre Byrne é santo para metade do bairro e demônio para a outra metade, e às vezes para as\nmesmas pessoas em dias diferentes.\nPara os investigadores, o Distrito de Waterford é o lugar onde a cidade sente a dor de tudo o que acontece nos\noutros bairros. Um estivador morto no\nPíer 9 deixa uma viúva aqui; um operário que cai da Ponte deixa quatro filhos aqui; um tira que atira em\ngrevistas volta para casa aqui, na mesma rua das vítimas. Ninguém confia em quem vem de fora, mas todos\nquerem justiça — o problema é que cada família tem uma ideia diferente do que ela seja.\nCRÔNICA · O JORNALEIRO DA RUA DOLORES Danny Mulvaney, 11 anos, jornaleiro\nPego os jornais às quatro e meia na porta da Gazeta, no Distrito. Cinquenta exemplares, fiado. Se vender todos, fico com\ncinquenta centavos. Desço correndo para o Distrito de Waterford gritando a manchete, mesmo quando não entendo o que ela\nquer dizer. Hoje era “ESCÂNDALO NA PONTE”. Vendi trinta antes das sete.\nConheço todo mundo pela janela. A Sra. Rosales compra um e lê de lupa. O velho Kowalski compra e joga fora a página da\npolícia, porque o filho dele aparece lá. O Murphy, o agiota, não compra: tira um da minha pilha e diz “fica na conta”. Minha\nmãe deve a ele. Todo mundo deve a ele.\nDepois da escola das freiras, faço recados para o O’Rourke’s. Levo bilhetes dobrados para o porão da Rua Dolores e não leio.\nGanho um níquel e um sanduíche. O Tommy Riordan me deu um dólar uma vez e disse que, quando eu crescer, posso\ntrabalhar para o Padre. Minha mãe chorou a noite inteira quando eu contei. Eu não entendi por quê. O Tommy tem sapato\nnovo.\nO QUE SEGURA O GUETO\nTabela SV.GI.1 · Poder no Distrito de Waterford\nQ U EM  · C O MO MAND A  · D E Q U EM D EPEND E\nIrmandade Irlandesa  · Fundo de greve, empregos, fiança, punição de traidores Da fé do bairro no Padre Byrne\nIgreja de São\nBrendan\nConfissão, escola, casamentos, enterros — e o perdão  · Das moedas da coleta e da\nIrmandade, que a protege\nOs pubs  · Onde se decide tudo: greves, casamentos, vinganças  · Do rum de Mae Calloway\nAs mães do bairro  · Sabem tudo, escondem todos, julgam sem tribunal  · De que os filhos voltem para casa\nOs agiotas  · Empréstimos de sexta para segunda, a 20% por semana Da fome — e do silêncio da\nIrmandade, que cobra sua parte\nLUGARES DO GUETO\nTabela SV.GI.2 · Endereços\nLO C AL  · O Q U E É  · O Q U E SE D ESC O BR E ALI\nIgreja de São\nBrendan\nIgreja de tijolo com torre visível de todo o bairro;\narmas escondidas na sacristia\nConfissões que o padre não pode\nrepetir; quem esconde o quê na\nIgreja\nPub O’Rourke’s  · Pub mais antigo do Distrito de Waterford, sede\ninformal da Irmandade, com uma mesa nos fundos\nonde ninguém senta\nPlanos da greve; quem está em\ndívida com Byrne\nPorão da Rua Dolores  · Onde a Irmandade nasceu em 1912; hoje, tribunal e\ndepósito de armas\nQuem foi julgado e o que\naconteceu com ele\nPensão da Sra.\nRosales\nPensão na beirada mexicana do bairro; a dona vê tudo\nda janela\nO diário de Pedro Alvarado; o\nsindicalista escondido no sótão\nGaragem Ferraro  · Oficina do irmão de Big Lou, na fronteira italiana do\nbairro\nCarros roubados, placas trocadas;\nquem pediu um carro na noite de\num crime\nEscola Paroquial\nSanta Brígida\nEscola das freiras; as crianças ouvem tudo em casa e\ncontam tudo no recreio\nO que os pais falam à noite\nCasa de Penhores\nMurphy\nAgiota e penhorista, a 20% por semana  · Quem está desesperado e quanto\ndeve\nHospital Gratuito\nAshcroft\nHospital simples mantido em segredo por Cornelius\nAshcroft\nFeridos sem nome; quem foi\natendido na noite de uma briga\nGENTE DO GUETO\nNo Distrito de Waterford, todo mundo é parente de alguém, deve algo a alguém e já perdoou alguém que não\nmerecia. A lealdade à família vem antes da lei, da Igreja e, às vezes, da Irmandade.\nPadre Michael Feeney\nPÁ R O C O D E S ÃO B R E N DA N , 6 3 A N O S\nVelho padre de Galway que batizou metade do bairro e enterrou a outra metade. Foi professor do jovem\nDeclan Byrne no seminário e o viu trocar Deus pela causa.\nVIRTUDE\nAbre a Igreja para dormir a quem não tem onde; nunca\nentregou ninguém à polícia.\nP ECADO\nGuarda armas da Irmandade na sacristia e ouviu Byrne\nconfessar o assassinato do velho Vito Moretti — e o\nabsolveu.\nQUER\nQue Byrne volte para Deus antes que seja tarde.\nTEM E\nTer de escolher entre o segredo da confissão e uma vida.\nAlianças: Ama Byrne como filho; tolera Irmã Agnes, que o critica. · Fala com: Tranquilizar, Respeito\nKathleen Byrne\nI R M Ã D O PA D R E B Y R N E , 4 2 A N O S\nViúva de um estivador, mãe de cinco, dona de uma pequena mercearia. É a voz das mulheres do bairro e\na única pessoa que Declan ainda escuta.\nVIRTUDE\nAlimenta fiado metade da rua e organiza as mães\nquando a polícia invade.\nP ECADO\nFoi ela quem entregou à Irmandade o nome do fura-\ngreve que apareceu morto em 1932; nunca se\narrependeu.\nQUER\nQue os filhos não terminem no cais nem no cemitério.\nTEM E\nQue o irmão a faça escolher entre ele e os filhos — o\nmais velho quer entrar na Irmandade.\nAlianças: Declan (irmão), Peg Donnelly (prima), Irmã Agnes (desconfiança mútua). · Fala com:\nTranquilizar, Bajulação\nDolores Rosales\nD O N A D E P E N S ÃO, 5 0 A N O S\nViúva mexicana, terço na mão e olhos na janela. Hospedou Pedro Alvarado e esconde um sindicalista\nprocurado no sótão.\nVIRTUDE\nHospeda de graça quem chega à cidade sem nada, sem\nperguntar a origem.\nP ECADO\nVende informações sobre seus hóspedes ao Patrulheiro\nDunne para não ser despejada pela Irmandade, dona do\nprédio.\nQUER\nQue os mexicanos tenham voz no sindicato.\nTEM E\nSer despejada; ser descoberta por quem ela entrega.\nAlianças: Irmã Agnes, Pedro Alvarado (falecido); paga a Irmandade. · Fala com: Tranquilizar, Idiomas\n(espanhol)\nSeán Murphy\nAG I OT A E P E N H O R I S T A , 5 5 A N O S\nHomem gordo e jovial que empresta a quem ninguém mais empresta, a juros que ninguém mais cobra.\nConhece a miséria de cada família e a chama de “clientela”.\nVIRTUDE\nÉ a única fonte de crédito no bairro; sem ele, muitas\nfamílias passariam fome antes do pagamento.\nP ECADO\nCobra 20% por semana; manda quebrar dedos de quem\natrasa; repassa um terço à Irmandade.\nQUER\nComprar um pub e virar respeitável.\nTEM E\nQue Byrne decida que ele se tornou um\nconstrangimento.\nAlianças: Irmandade (paga), Mae Calloway (lava dinheiro). · Fala com: Intimidação, Jogatina\nBridget “Biddy” Riordan\nM Ã E A D OT I V A D E T O M M Y R I O R DA N , 6 1 A N O S\nLavadeira que criou Tommy depois que o pai dele morreu no cais. Sabe que ele mata para Byrne e reza\npor ele todas as noites.\nVIRTUDE\nCriou sete crianças que não eram suas; nunca recusou\num prato.\nP ECADO\nEsconde a arma de Tommy embaixo do colchão e\nmentiu à polícia três vezes por ele.\nQUER\nQue Tommy saia da Irmandade vivo.\nTEM E\nVer Tommy no Píer 9.\nAlianças: Leal a Tommy acima de tudo, inclusive de Byrne. · Fala com: Tranquilizar\nJerzy Kowalski\nPA I D O S A R G E N T O K O WA L S K I , 70 A N O S\nVelho fundidor polonês, mãos queimadas, que mora numa casa de madeira na beirada do Distrito de\nWaterford. Envergonha-se do filho tira e se orgulha das netas.\nVIRTUDE\nEnsinou o ofício a dezenas de jovens do bairro, sem\ncobrar.\nP ECADO\nSabe o que o filho fez a Lola Marchetti e nunca disse\nnada; aceita o dinheiro sujo que o filho traz para casa.\nQUER\nQue as netas estudem e saiam do bairro.\nTEM E\nQue o filho seja morto pelos irlandeses ou preso pelos\nfederais.\nAlianças: Neutro; respeitado pelos irlandeses; temido pelo próprio filho. · Fala com: Respeito, Idiomas\n(polonês)\nLiam Doherty\nO R G A N I Z A D O R S I N D I C A L , 2 9 A N O S\nJovem idealista que voltou de Nova York com ideias socialistas e um livro de Marx no bolso. Quer uma\ngreve geral de verdade, não uma chantagem de Byrne.\nVIRTUDE\nFala a verdade aos operários, inclusive sobre Byrne; é o\núnico que defende a entrada dos mexicanos no sindicato.\nP ECADO\nEstá disposto a explodir um armazém de Moretti para\nprovocar a greve, mesmo que um vigia morra.\nQUER\nUma greve geral que mude a cidade, com ou sem Byrne.\nTEM E\nQue Byrne o mande matar por desafiá-lo.\nAlianças: Rosales (esconde-o), Irmã Agnes; inimigo silencioso de Byrne. · Fala com: Política, Tranquilizar\nAngela Moretti\nF I L H A D E S A L M O R E T T I , 2 0 A N O S\nA filha caçula de Sal, estudante de enfermagem no Hospital Gratuito Ashcroft, onde vai disfarçada para\nver Tommy Riordan. Corajosa, ingênua e teimosa como o pai.\nVIRTUDE\nTrata feridos irlandeses e italianos no hospital sem\ndistinção.\nP ECADO\nMente para o pai, para Tommy e para si mesma: sabe o\nque Tommy faz e finge não saber.\nQUER\nFugir com Tommy para Los Angeles.\nTEM E\nSer a causa de uma guerra entre as duas famílias.\nAlianças: Tommy (amor), Dr. Ng (aprendizado); o pai ignora tudo. · Fala com: Tranquilizar, Bajulação\nTEIA DE INTERESSES\nNo Distrito de Waterford, as alianças são de sangue — e o sangue é a primeira coisa a ser cobrada quando uma\ndelas falha.\nTabela SV.GI.3 · Alianças por interesse\nD E  · PAR A  · O Q U E U M D Á AO O U TR O  · O Q U E R O MPER IA O LAÇ O\nPadre Byrne  · O bairro  · Proteção, emprego e enterros em\ntroca de votos, silêncio e filhos\nO bairro descobrir que\nByrne negocia com o\nprefeito\nPadre Feeney  · Padre Byrne  · Abrigo na Igreja em troca de nada —\nsó amor e esperança\nByrne matar alguém\ndentro da paróquia\nKathleen Byrne  · Padre Byrne  · A voz das mães em troca de proteção\npara os filhos\nO filho mais velho dela\nentrar na Irmandade\nDolores Rosales  · Patrulheiro Dunne  · Informações sobre hóspedes em\ntroca de não ser despejada\nUm hóspede entregue\nmorrer\nSeán Murphy  · Irmandade  · Um terço dos juros em troca de\nproteção\nMurphy virar escândalo\npúblico\nLiam Doherty  · Operários\nmexicanos\nDefesa sindical em troca de apoio\npara desafiar Byrne\nByrne oferecer aos\nmexicanos o que Doherty\npromete\nTommy Riordan  · Angela Moretti  · Amor em troca de uma saída  · Um dos dois ter de\nescolher a família\nBiddy Riordan  · Tommy  · Esconderijo e mentiras em troca de\nque ele volte para casa\nTommy matar alguém do\nbairro\nRUMORES DO GUETO (1D8)\nTabela SV.GI.4 · O que se diz nos pubs e nos varais\nD 8 R U MO R  · V ER D AD E?\n1 O Padre Feeney sabe quem matou o velho Moretti  · Verdade; ouviu em confissão\n2 Liam Doherty é comunista e espião de Moscou  · Falso; é só sindicalista\n3 Há armas escondidas na Igreja  · Verdade\n4 Tommy Riordan namora uma italiana  · Verdade: a filha de Moretti\n5 Murphy vai ser morto por um devedor  · Possível\n6 O Hospital Ashcroft é pago pelo velho Ashcroft  · Verdade\n7 Kathleen Byrne manda mais que o irmão  · Exagero: só nas mulheres\n8 Há um fura-greve escondido no bairro  · Verdade: na Pensão Rosales, disfarçado de sindicalista\nA LEI DO BAIRRO\nO Distrito de Waterford tem regras que valem mais que as do Fórum. Quem as quebra paga, seja PJ ou PNJ.\nTabela SV.GI.5 · Código do Distrito de Waterford\nR EG R A  · SE O S PJS A Q U EBR AR EM\nNinguém fala com a\npolícia\nQuem for visto com um tira perde 1 de reputação com a Irmandade; as testemunhas param de\nfalar com ele por um caso\nNinguém fura greve  · Fura-greve é espancado na mesma semana; a família dele é expulsa do bairro\nNinguém toca na Igreja Revistar São Brendan sem permissão do padre: −2 com a Irmandade e o bairro inteiro fecha as\nportas\nAs dívidas se pagam  · Quem não paga um favor perde a proteção da Irmandade no Embarcadouro e no Distrito de\nWaterford\nEnterra-se os seus  · Comparecer a um velório no Distrito de Waterford: +1 de reputação com a Irmandade e acesso a\numa testemunha\nUM VELÓRIO NO GUETO\nVelórios irlandeses duram a noite inteira e reúnem o bairro todo. É a melhor cena para investigar no Distrito\nde Waterford: todos estão lá, todos bebem e alguém sempre fala demais.\nTabela SV.GI.6 · O que acontece no velório (1d6, duas vezes por noite)\nD 6 MO MENTO  · O Q U E O FER EC E\n1 A viúva chora  · Tranquilizar (0): ela revela o que o marido disse na última noite\n2 Um bêbado acusa\nalguém\nUm nome dito em voz alta; Faro para Mentiras (1) para saber se ele crê no que diz\n3 O Padre Byrne chega Todos se calam; quem falar com ele ganha +1 com a Irmandade ou −1, conforme a conversa\n4 Briga na cozinha  · Dois primos brigam por uma herança ou uma dívida; separar: Briga Dif. 4\n5 Alguém de fora  · Um homem de Moretti ou um tira veio “prestar condolências”; ele está procurando a mesma\ncoisa que os PJs\n6 A canção  · Uma canção antiga faz todos chorarem; Sangue-Frio +1 para todos os PJs presentes (um “ufa”\ndo bairro)\nCONDUZINDO O GUETO.\nA Dificuldade social para forasteiros é baixa (3), mas a confiança é frágil: uma única pergunta errada a um\nvizinho chega à Irmandade antes do anoitecer. Tranquilizar é a habilidade-rainha; Respeito funciona com os\nvelhos e com o padre; Intimidação só com os agiotas. PJs irlandeses ou criados no bairro recebem −1 nas\nDificuldades sociais aqui. Investigadores que comparecem a missas e velórios são lembrados — para o bem e\npara o mal.\nLUGAR EM PROFUNDIDADE · OS SUBTERRÂNEOS","Esgotos e túneis":"Os Esgotos de Saint Village\nNos esgotos, com a lanterna apontada para a galeria.\nSob Saint Village existe uma segunda cidade, mais velha e mais honesta: ali ninguém finge que não fede. Os\nprimeiros esgotos foram cavados em 1856 por presos irlandeses, em tijolo vermelho, seguindo os riachos que\ndesciam das colinas até a baía. Depois do terremoto de 1906, a Prefeitura construiu por cima deles a Grande\nGaleria de concreto, larga o bastante para um caminhão, e esqueceu de fechar os túneis antigos. Hoje são cento\ne vinte quilômetros de galerias, metade delas fora de qualquer mapa oficial.\nTrês redes se cruzam no escuro. A Grande Galeria, de concreto, corre sob a Rua Montgomery até o emissário\nda baía e é inspecionada uma vez por ano. Os túneis de tijolo de 1856 serpenteiam sob o Distrito de Waterford\ne Saint Edwiges, desabados em vários pontos. E os túneis de Chinatown, cavados à mão depois do incêndio,\nligam porões, adegas e armazéns — e às vezes se abrem, sem aviso, para os esgotos.\nD esci a primeira vez em 1919, atrás de um gato. Tinha dez anos e o gato era da minha irmã. Não achei o gato.\nAchei uma galeria de tijolo, alta, seca, com uma lamparina de óleo ainda pendurada num gancho, como se\nalguém tivesse acabado de sair. Fiquei lá embaixo a noite inteira. Quando subi, pela grade da Rua Kearny,\nera outra pessoa.\nHoje eu conheço os túneis melhor do que o homem da Prefeitura que fez o mapa oficial, porque ele nunca desceu, e eu\nnunca mais subi direito. Faço entregas: um pacote do porão de um banco para a adega de um hotel, um homem que\nnão pode ser visto de uma delegacia para um cais. Cobro por trecho. Os clientes nunca sabem meu nome, só o assobio.\nLá embaixo a água corre de White Hills para o porto. Chega limpa, com espuma de sabonete das casas grandes, e sai\nna baía grossa, trazendo o que o resto da cidade jogou fora no caminho. Já tirei dessa água um anel com brasão, uma\npistola sem número, um caderno de contabilidade amarrado num tijolo e, uma vez, uma mão de mulher com uma\naliança que eu não quis olhar duas vezes.\nU M R A T O D E T Ú N E L , Q U E S Ó R E S P O N D E P E L O A S S O B I O\nQuem vive lá embaixo são os esquecidos da Depressão: os ratos de túnel, catadores que recolhem moedas,\nanéis e restos das grelhas; andarilhos que fugiram dos albergues; e, segundo os boatos, um velho que mora lá\ndesde 1906 e conhece cada curva. Mae Calloway usa as galerias que dão na baía para mover rum na maré\nbaixa. A Irmandade guardou armas ali em 1929. E todo tira de Saint Village sabe que um corpo jogado na\nGrande Galeria chega à baía em dois dias — se não ficar preso nas grades do Emissário.\nPara os investigadores, os esgotos são atalho, esconderijo e armadilha. Eles ligam lugares que, na superfície,\nficam a quarteirões de distância. Mas a água sobe com a maré e a chuva, o gás se acumula nas galerias baixas, e\na escuridão é total. Quem desce sem guia, sem lanterna e sem saber a hora da maré, às vezes não sobe.\nCRÔNICA · NA GRADE DO EMISSÁRIO Old Sully, idade desconhecida, rato de túnel\nMoro aqui desde o fogo. Quando a cidade queimou, desci com minha mulher para fugir da fumaça. Ela não subiu. Eu não\nquis mais. Lá em cima é que é escuro, filho, aqui embaixo pelo menos a gente sabe onde está.\nToda manhã, na maré vazante, eu vou até a grade do Emissário, onde a Grande Galeria cospe na baía. A grade segura o\nque a água traz: sapatos, garrafas, cartas, dentaduras, às vezes uma carteira com dinheiro. Às vezes um homem. Esse mês\nforam dois. Um tinha as mãos amarradas com arame. O outro usava um anel de formatura de Stanford.\nEu não chamo a polícia. A polícia já sabe. Eu tiro os bolsos, guardo o que posso vender ao Wong Shu e anoto o resto num\ncaderno. Quarenta anos de caderno. Se alguém um dia quiser saber o que esta cidade jogou fora, é só descer e me pagar um\ncafé.\nLUGARES DOS SUBTERRÂNEOS\nTabela SV.ES.1 · Endereços sob a cidade\nLO C AL  · O Q U E É  · O Q U E SE D ESC O BR E ALI\nGrande Galeria  · Túnel de concreto de 5 m de largura sob a Rua\nMontgomery\nCorpos, armas descartadas, o que a\nPrefeitura joga fora\nEmissário da Baía  · Saída da Grande Galeria na baía, com uma grade\nenferrujada\nO que a maré não levou; o caderno de Old\nSully\nTúneis de 1856  · Galerias de tijolo sob o Distrito de Waterford e\nSaint Edwiges; parte desabada\nO antigo depósito de armas da Irmandade\n(1929)\nCâmara do Relógio  · Cisterna circular sob a Estação Ferroviária, com\neco perfeito\nPonto de encontro secreto; quem fala ali é\nouvido de longe\nLigação de\nChinatown\nPassagem entre os túneis do Lótus e o esgoto de\ntijolo\nRota de fuga de Lin Mei-Hua; guardas do\ntong\nGaleria do Rum  · Túnel que sai sob o Galpão 14 e dá na água na\nmaré baixa\nCaixas de Mae Calloway; horário das\nlanchas\nCapela Afogada  · Porão da primeira igreja da cidade, engolido em\n1906, agora alagado\nOs ossos da missão espanhola; refúgio dos\nratos de túnel\nEstação de Bombas\nda Rua 3\nCasa de máquinas que controla o nível da água  · Quem controla as bombas pode inundar\numa galeria inteira\nGENTE DOS SUBTERRÂNEOS\nOld Sully\nR AT O D E T Ú N E L , I DA D E D E S C O N H E C I DA\nViúvo do incêndio de 1906, mora nos esgotos desde então. Conhece cada curva, cada grade e cada maré.\nGuarda um caderno com tudo o que a água trouxe em quarenta anos.\nVIRTUDE\nGuia de graça quem está perdido e assustado\nP ECADO\nVende os pertences dos mortos que encontra, inclusive\nprovas\nQUER\nMorrer lá embaixo, perto da mulher\nTEM E\nQue o tirem dos túneis para um asilo\nAlianças: Wong Shu (compra), Irmã Agnes (comida) · Fala com: Tranquilizar, Barganha\nRita “Lanterna” Mendez\nC H E F E D O S R AT O S D E T Ú N E L , 2 6 A N O S\nEx-operária de fábrica de conservas, demitida em 1931. Organizou os catadores dos esgotos como uma\npequena guilda: dividem o que acham e cobram pedágio de quem passa.\nVIRTUDE\nNinguém do grupo dela passa fome\nP ECADO\nCobra caro de quem precisa fugir, e às vezes entrega a\nfuga a quem paga mais\nQUER\nUm teto de verdade para os doze que dependem dela\nTEM E\nA polícia inundar as galerias com as bombas\nAlianças: Mae Calloway (pedágio), Lin Mei-Hua (trégua) · Fala com: Gíria das Ruas, Barganha\nInspetor Walter Doane\nI N S P E T O R D E S A N E A M E N T O DA P R E F E I T U R A , 5 8 A N O S\nO único funcionário da cidade que conhece os mapas reais dos esgotos. Bebe café com gim e fala de\ntubulações como quem fala de poesia.\nVIRTUDE\nAvisa o Distrito de Waterford quando a maré vai alagar\nos porões\nP ECADO\nVende cópias dos mapas a quem pagar, inclusive à\nIrmandade e a Moretti\nQUER\nUma aposentadoria antes de a Grande Galeria rachar\nTEM E\nQue descubram que ele vendeu o mapa usado num\nassalto\nAlianças: Prefeitura (salário), Mae Calloway (dinheiro) · Fala com: Burocracia, Arquitetura\nPERIGOS DOS ESGOTOS\nTabela SV.ES.2 · Perigos\nPER IG O  · TESTE  · EFEITO\nGás de esgoto  · Faro de Encrenca Dif. 4 para notar  · −1 de Saúde por rodada; uma chama causa\nexplosão de 1d6 + 2\nMaré subindo  · Pesquisa (0) para saber a hora; Atletismo\nDif. 4 por rodada para avançar\nA água sobe 30 cm a cada 10 minutos; galerias\nbaixas fecham em 1 hora\nEscuridão total  · —  · Veja Tabela 3.7 do Guia; lanternas falham com\n1 em 1d6 por hora\nDesabamento nos\ntúneis de 1856\nFaro de Encrenca Dif. 5  · 1d6 + 1 e caminho bloqueado (desafio contínuo\nde Atletismo, reserva 10)\nRatos  · Atletismo Dif. 3 para afastar  · Mordidas: −1 de Saúde; infecção (Saúde Dif. 4\nno dia seguinte ou −2)\nÁgua contaminada  · Saúde Dif. 4 se engolir  · Febre por 2 dias: +1 nas Dificuldades gerais\nBombas da Rua 3\nacionadas\nMecânica Dif. 5 para parar  · Uma galeria inteira inunda em 5 minutos\nTabela SV.ES.3 · Encontros nos túneis (1d6 por hora)\nD 6 ENC O NTR O  · O Q U E O FER EC E O U AMEAÇ A\nD 6 ENC O NTR O  · O Q U E O FER EC E O U AMEAÇ A\n1 Ratos de túnel  · Pedem pedágio de $1 por pessoa; pagando, viram guias\n2 Um corpo preso numa grade  · Pista: quem é e como chegou ali (Medicina Legal)\n3 Caixas de rum de Mae  · Dois homens armados guardam a galeria (nível 1)\n4 Um morador em surto  · Grita que “eles” vêm buscá-lo; sabe onde está algo que os PJs procuram\n5 Água subindo  · A maré mudou: 30 minutos para sair\n6 Silêncio e eco  · Vozes vindas da Câmara do Relógio: alguém está fazendo um acordo\nTabela SV.ES.4 · Rumores do subsolo (1d6)\nD 6 R U MO R  · V ER D AD E?\n1  · Há um homem que mora nos esgotos desde 1906  · Verdade: Old Sully\n2  · Os túneis de Chinatown chegam ao Hotel St. Clair  · Verdade\n3  · Há crocodilos na Grande Galeria  · Falso\n4  · A Irmandade esqueceu armas nos túneis de 1856  · Verdade: duas caixas de rifles\n5  · Quem controla as bombas controla a cidade lá embaixo  · Verdade\n6  · Os ossos dos padres espanhóis estão na Capela Afogada  · Verdade\nCONDUZINDO OS ESGOTOS.\nSem guia, cada travessia entre duas regiões exige Arquitetura (1) ou Faro de Encrenca Dif. 5; falhar deixa o\ngrupo perdido por 1 hora (role um encontro). Com Old Sully ou um rato de túnel como guia ($2 a $5), não há\nteste. A maré alta fecha as galerias baixas por 4 horas: consulte a tábua de marés na Capitania do Porto\n(Pesquisa, 0).\nLUGAR EM PROFUNDIDADE · A PORTA DA CIDADE","Estação Ferroviária Central":"Estação Ferroviária Central\nC arrego malas na Estação Central desde 1912. Comecei com dezesseis anos, de boné vermelho emprestado, e hoje\nsou o carregador mais antigo da Pullman nesta cidade. Sei o horário de todos os trens de cor, sei qual\nplataforma alaga em fevereiro e qual chefe de estação aceita um dólar para não ver alguém embarcar sem\nbilhete.\nPelo peso da mala eu sei quase tudo. Os homens de White Hills que vão a Los Angeles a negócios viajam leves, duas\ncamisas e uma escova de prata, porque o resto vai por despacho. As moças que fogem de casa trazem malas pesadas\ndemais, cheias de coisas que não vão usar: o vestido do baile da escola, um álbum de fotografias, uma caixa de\nmúsica. Os homens que fogem da polícia não trazem mala. Chegam com as mãos nos bolsos e olham a plataforma do\ntrem das cinco e meia por cima do jornal.\nEm vinte e dois anos, carreguei a mala de dois governadores, de um campeão de pesos-pesados e de uma mulher que\nmatou o marido em Sacramento e embarcou aqui, para Chicago, de chapéu de véu. Ela me deu um dólar de prata. Eu\nainda tenho o dólar.\nM O S E S C A R T E R , C A R R E G A D O R D A P U L L M A N\nA Estação Central, pouco antes do trem das cinco e meia.\nA Estação Ferroviária Central fica no limite entre Downtown e o Embarcadouro, onde os trilhos da Southern\nPacific terminam diante da baía. Inaugurada em 1898 e reconstruída depois do terremoto, é um palácio de\ngranito com uma torre de relógio de quatro faces, um saguão de mármore com teto de vidro e vitrais que\nmostram a Corrida do Ouro como se tivesse sido uma aventura e não uma corrida de gente faminta. O relógio\nda torre está sete minutos adiantado desde 1906. Ninguém consertou. Os moradores dizem que Saint Village\nvive sete minutos à frente da própria culpa.\nPor ali passam todos os dias quarenta trens e oito mil pessoas: executivos de Nova York, estrelas de Hollywood\na caminho dos hotéis, famílias do Oklahoma fugindo da seca com tudo o que têm numa mala amarrada com\ncorda, soldados, vendedores, fugitivos. Os carregadores negros da Pullman Company conhecem cada\npassageiro importante e cada segredo que eles deixam nos vagões-leito. Os armários de bagagem do saguão\nguardam a metade das provas desaparecidas da cidade.\nAtrás da fachada fica o pátio de manobras: vinte linhas de trilhos, galpões de locomotivas, caixas-d’água e um\nmar de vagões de carga parados. Ali vivem os andarilhos que viajam de graça nos vagões e os vigias\nferroviários, os “touros”, que os espancam por isso. Do outro lado do pátio, o acampamento de barracos\nchamado Vila Hoover abriga duzentas pessoas que chegaram à cidade e nunca conseguiram entrar nela.\nPara os investigadores, a estação é o lugar de chegadas e fugas: um suspeito comprando uma passagem só de\nida, uma testemunha saindo da cidade no trem da meia-noite, uma mala trocada no guarda-volumes, um\ncorpo encontrado num vagão vindo de Sacramento. As facções sabem disso: Moretti controla os carregadores\nde bagagem, a Irmandade controla os ferroviários do sindicato, e o FBI de Prescott vigia a plataforma 1.\nCRÔNICA · O TREM DA MEIA-NOITE Samuel Price, 44 anos, carregador da Pullman\nEu sei quem viaja pelo que deixa no vagão. Um banqueiro deixa o jornal dobrado na página de ações e uma garrafa vazia\nque ele jura que não bebeu. Uma corista deixa batom no copo e um bilhete de um homem casado. O homem do quarto 6 não\ndeixou nada, nem um fio de cabelo no travesseiro.\nToda noite, o trem das 23h55 para Los Angeles leva alguém fugindo. Ontem foi uma moça loira com um casaco de raposa e\num olho roxo. Pagou a cabine com dinheiro trocado do Il Paradiso e me deu cinco dólares para eu dizer que não a vi. Eu\nnunca vejo ninguém. É meu trabalho. Também é minha sobrevivência: um carregador que vê demais vira o próximo homem\nencontrado nos trilhos.\nQuando o trem sai, eu fico na plataforma ouvindo o apito sumir na neblina. O relógio da torre marca meia-noite e sete.\nPenso no meu filho, que estuda em Oakland para ser advogado. Um dia ele vai entrar nesta estação pela porta da frente. Eu\nentro pela dos fundos há vinte anos, e ainda chamo isso de sorte.\nLUGARES DA ESTAÇÃO\nTabela SV.EF.1 · Endereços\nLO C AL  · O Q U E É  · O Q U E SE D ESC O BR E ALI\nSaguão Principal  · Mármore, vitrais da Corrida do Ouro e o relógio\nsete minutos adiantado\nQuem chegou e quem partiu; encontros\n“casuais”\nGuarda-volumes  · Trezentos armários numerados, chaves de latão Malas trocadas, provas escondidas, dinheiro\nde resgate\nPlataforma 1  · Trens de luxo para Los Angeles e Chicago; o FBI\nvigia daqui\nQuem embarcou no trem da meia-noite\nBilheteria  · Guichês de madeira, livros de registro de\npassagens\nNomes, destinos, pagamentos em dinheiro\nSala dos\nCarregadores\nVestiário dos carregadores negros da Pullman  · O que os passageiros deixaram nos vagões-\nleito\nPátio de\nManobras\nVinte linhas de trilhos, galpões e vagões parados Corpos em vagões, contrabando, andarilhos\nque viram tudo\nVila Hoover  · Acampamento de barracos atrás do pátio  · Testemunhas que ninguém escuta; quem\nchegou à cidade e se escondeu\nTorre de\nSinalização\nCabine elevada que controla as agulhas dos\ntrilhos\nDe lá se vê todo o pátio; um sabotador pode\ndesviar um trem\nGENTE DA ESTAÇÃO\nSamuel Price\nC A R R E G A D O R DA P U L L M A N , 4 4 A N O S\nVinte anos carregando malas e ouvindo segredos nos vagões-leito. Sabe ler um passageiro em três\nsegundos.\nVIRTUDE\nPaga a faculdade de direito do filho com gorjetas\nP ECADO\nVende o que vê aos Moretti, que controlam os\ncarregadores de bagagem\nQUER\nVer o filho advogado\nTEM E\nSer o próximo corpo nos trilhos\nAlianças: Moretti (por medo), Sindicato dos Carregadores (por lealdade) · Fala com: Bajulação, Respeito\nCapitão Boyd Harlan\nC H E F E D O S V I G I A S F E R R O V I Á R I O S , 5 0 A N O S\nEx-sargento do Texas, chapéu de vaqueiro e cassetete de carvalho. Comanda os “touros” do pátio e\nacredita que andarilhos são ladrões até prova em contrário.\nVIRTUDE\nNunca deixou um trem sair com uma criança perdida a\nbordo\nP ECADO\nEspancou até a morte um andarilho de 15 anos em 1932\nQUER\nQue a ferrovia o promova a superintendente\nTEM E\nQue alguém da Vila Hoover testemunhe\nAlianças: Southern Pacific, Capitão Voss · Fala com: Jargão de Polícia, Intimidação\nMãe Josephine\nL Í D E R DA V I L A H O O V E R , 6 0 A N O S\nViúva de um fazendeiro de Oklahoma, chegou num vagão de carga com sete netos. Organizou o\nacampamento com regras próprias: ninguém rouba de ninguém, e todo mundo divide a sopa.\nVIRTUDE\nDuzentas pessoas comem graças a ela\nP ECADO\nEsconde na Vila um homem procurado por assassinato,\nporque ele salvou seu neto\nQUER\nCasas de verdade para todos antes do inverno\nTEM E\nQue a polícia queime a Vila, como em Seattle\nAlianças: Irmã Agnes, Liam Doherty · Fala com: Tranquilizar\nHank Dorsey\nS I N A L E I R O DA T O R R E , 3 7 A N O S\nFerroviário do sindicato, controla as agulhas do pátio. Calado, metódico, leal à Irmandade.\nVIRTUDE\nImpediu duas colisões com o próprio corpo\nP ECADO\nDesvia vagões de carga para os armazéns de quem paga\nQUER\nQue a greve chegue à ferrovia\nTEM E\nUm acidente com mortos na sua torre\nAlianças: Irmandade, Sindicato Ferroviário · Fala com: Gíria das Ruas, Política\nAgente Clara Wynn\nAG E N T E F E D E R A L I N F I LT R A DA , 3 1 A N O S\nTrabalha na bilheteria como funcionária comum, mas é os olhos do agente Prescott na estação. Conhece\ncada passageiro que compra passagem só de ida.\nVIRTUDE\nProtegeu uma testemunha federal com a própria vida\nP ECADO\nLê a correspondência dos colegas e entrega amigos para\nsubir na carreira\nQUER\nSer a primeira mulher agente de campo do FBI\nTEM E\nSer descoberta pelos Moretti\nAlianças: Agente Prescott; ninguém mais · Fala com: Burocracia, Faro para Mentiras\nDESAFIOS DA ESTAÇÃO\nTabela SV.EF.2 · Desafios\nSITU AÇ ÃO  · TESTE  · EFEITO\nAtravessar o pátio com\ntrens manobrando\nFaro de Encrenca Dif. 4  · Falhou: atropelamento por vagão em manobra (1d6 +\n2)\nPular num trem em\nmovimento\nAtletismo Dif. 5  · Falhou: queda de 1d6; com 1 no dado, atropelamento\npor trem\nLutar no teto de um vagão  · Atletismo Dif. 4 a cada rodada Falhou: queda (1d6 + 1); túneis e pontes: Faro de\nEncrenca Dif. 5 ou 1d6 + 3\nSer pego pelos vigias  · Fuga ou Briga contra o nível 2 Surra (1d6) e uma noite na cela da estação\nVagão trancado  · Mecânica ou Fechaduras Dif. 4 Preso: fome, sede, frio ou calor (Tabela 3.8 do Guia)\nMultidão no saguão  · Campana Dif. 4 para não\nperder o alvo\nFalhou: o suspeito embarca sem ser visto\nIncêndio no galpão de\nlocomotivas\nVeja Tabela 3.5 do Guia  · Carvão e óleo: +1 no dano do fogo\nTabela SV.EF.3 · Horários que importam\nH O R A  · TR EM  · PO R Q U E IMPO R TA\n5h30 Expresso de Sacramento  · Chegam os jornais da capital e os políticos\n8h00 Trem dos operários de Oakland  · Mil pessoas no saguão: o melhor momento para sumir na multidão\n12h15 Daylight para Los Angeles  · Estrelas de cinema; o FBI vigia a plataforma 1\n18h00 Cargueiro do Oeste  · Vagões fechados no pátio; andarilhos embarcam escondidos\n23h55 Trem da meia-noite para Los Angeles  · O trem de quem foge\n3h00 Cargueiro do porto  · Mercadorias dos armazéns Moretti; nenhum fiscal acordado\nTabela SV.EF.4 · Rumores da plataforma (1d6)\nD 6 R U MO R  · V ER D AD E?\n1 O relógio da torre está adiantado de propósito  · Meia verdade: quebrou em 1906; ninguém quis consertar\n2 Há um armário do guarda-volumes que ninguém abre há\ndez anos\nVerdade: o nº 117; dentro, uma mala de 1924 com dinheiro\nmarcado\n3 A Câmara do Relógio, sob a estação, guarda segredos  · Verdade\n4 Os carregadores trabalham para Moretti  · Meia verdade: os de bagagem, sim; os da Pullman, só por\nmedo\n5 O FBI tem alguém dentro da estação  · Verdade: Clara Wynn\n6 Um trem fantasma passa às 4h sem horário  · Falso: é o cargueiro de Mae, fora do registro\nCONDUZINDO A ESTAÇÃO.\nDificuldade social 4 no saguão, 5 no pátio de manobras. Bajulação e Barganha funcionam com os carregadores;\nJargão de Polícia com os vigias (que respeitam distintivos e mais nada); Tranquilizar na Vila Hoover. Guarda-\nvolumes: um gasto de Burocracia (1) ou $2 ao atendente abre qualquer armário; Fechaduras Dif. 3 sem pedir."},"geral":"FAC Ç Õ ES\nAs seis facções da ficha de personagem. Cada uma tem um objetivo, um método, um líder e um relógio de\navanço de 6 segmentos: ao fim de cada caso, o Diretor avança 1 segmento das facções que os investigadores não\natrapalharam. Quando um relógio fecha, a facção conquista seu objetivo e a cidade muda.\nTabela SV.1 · As facções de Saint Village\nFAC Ç ÃO  · LÍD ER  · Q U ER  · MÉTO D O  · R ELÓ G IO FEC H A →\nFamília Moretti  · Don Salvatore\n“Sal” Moretti\nMonopólio do jogo e\ndo rum quando a Lei\nSeca cair\nCassinos, agiotagem,\npolícia comprada\nOs Moretti legalizam\nseus cassinos; Saint\nEdwiges vira vitrine\nIrmandade\nIrlandesa\nDeclan “o Padre”\nByrne\nControle total dos\nsindicatos das docas\nGreves, sabotagem,\nvotos de cabresto\nGreve geral paralisa o\nporto por semanas\nPrefeitura e\nvereadores\nPrefeito Edmund\nWhitcombe\nReeleição e o contrato\nda Ponte\nLicitações fraudadas,\nchantagem, imprensa\nWhitcombe reeleito;\ncontratos da Ponte\nvão para seus\ncunhados\nDelegacia\nCentral\nCapitão Harlan\nVoss\nManter as duas máfias\npagando e em paz\nBatidas seletivas, provas\nplantadas\nVoss vira Chefe de\nPolícia; prisões em\nmassa de inimigos\ndele\nContrabandistas\nde rum\n“Rainha” Mae\nCalloway\nEscoar o último\nestoque antes do fim\nda Lei Seca\nLanchas rápidas,\ngalpões, propinas na\nGuarda Costeira\nMae compra um\nbanco; o contrabando\nvira negócio legítimo\nImprensa (Gazeta\nda Manhã)\nEditor Raymond\nHolt\nVender jornal e\nderrubar quem não\npaga anúncio\nFotos, manchetes,\nsegredos de alcova\nUma manchete\ndestrói um aliado dos\nPJs\nTabela SV.2 · Reputação com facções\nR EP.  · EFEITO EM JO G O\n−3  · Jurado de morte: atacado ao ser visto no território\n−2  · Hostil: +2 nas Dificuldades sociais; ninguém da facção fala sem pressão\n−1  · Desconfiado: +1 nas Dificuldades sociais\n0  · Neutro\n+1  · Conhecido: −1 nas Dificuldades sociais\n+2  · Amigo: um favor por caso sem custo\nR EP.  · EFEITO EM JO G O\n+3  · Protegido: a facção intervém se você estiver em perigo no território\nA S FAC Ç Õ ES\nA reputação com cada facção vai de −3 a +3 e muda as Dificuldades sociais no bairro dela (−1 por ponto\npositivo, +1 por negativo). Cada facção tem um relógio de seis segmentos: ao fim de cada caso, avance 1\nsegmento das facções que os PJs não atrapalharam. Com o relógio cheio, a facção alcança o que quer e a cidade\nmuda.\nFAC Ç ÃO  · C H EFE  · Q U ER EM 1 9 3 4  · R ELÓ G IO C H EIO\nFamília Moretti Don Sal Moretti  · Legalizar o império: cassinos,\nlicenças, a Ponte\nO primeiro cassino legal da Costa\nOeste\nIrmandade\nIrlandesa\nDeclan “o Padre” Byrne  · As docas e o porto  · Greve geral; o porto para\nTong da Flor de\nLótus\nLin Mei-Hua (com Chan\nWing-Sun)\nA paz em Chinatown e os\ntúneis\nO Lótus controla o bairro inteiro,\nJunco Negro incluído\nDelegacia Central Capitão Harlan Voss  · A paz que lhe paga; uma\ncadeira na Câmara\nVoss vereador\nPrefeitura  · Prefeito Whitcombe e\nEleanor Whitcombe\nReeleição; a Ponte inaugurada A Ponte inaugurada, inteira ou não\nO contrabando  · Mae Calloway  · Sair viva do fim da Lei Seca  · Mae compra uma frota legal e some\nO FBI  · Agente Lyle Prescott  · Um caso federal contra alguém\ngrande\nUma prisão que vira manchete\nnacional\nQ UEM É Q UEM\nFIG U R A  · Q U EM É  · O ND E APAR EC E\nDon Sal Moretti  · Chefe da Família, chegou aos 12 anos em 1886  · Toda a cidade; Excalibur\nVincent Moretti  · Filho de Sal; Kessler ensinou-o a atirar  · Saint Edwiges\nDeclan “o Padre” Byrne  · Ex-seminarista que o Distrito de Waterford chama de “o\nPadre”; líder da Irmandade\nDistrito de Waterford;\nExcalibur\nMae Calloway  · Rainha do contrabando de rum  · Cais; Excalibur; Black\nRock\nCapitão Harlan Voss  · O tira que mantém a paz comprada  · Toda a cidade; Black Rock\nTenente Earl Brannigan  · Homem de Voss na Homicídios  · Gala no St. Clair; Silkroad\nDetetive Ruth Sayer  · Tira de Chinatown, paga por Lin e por Voss  · Silkroad\nDetetive Delgado  · O tira honesto que ainda confia em alguém  · Toda a cidade\nPromotor Elliot Crane  · O único que acusa; quer ser candidato  · Gala no St. Clair\nPrefeito Whitcombe e\nEleanor\nO poder da Prefeitura e quem o maneja  · Toda a cidade\nCornelius Ashcroft III  · Patriarca do dinheiro mais velho de White Hills  · White Hills\nLin Mei-Hua  · Chefe do Lótus  · Silkroad\nKwan Ah-Lee  · Chefe do Junco Negro  · Silkroad\nAgente Lyle Prescott  · FBI; compra chiclete na banca do Zack  · Toda a cidade\nHolt e Hattie Brooks  · A Gazeta da Manhã  · Toda a cidade\nDr. Lindqvist  · Legista bêbado e, às vezes, honesto  · Necrotério\nDr. Ng Tai-Po  · Médico sem perguntas de Chinatown  · Silkroad\nDr. Augustin Marlowe  · Diretor do Sanatório Santa Úrsula  · Black Rock\nDiretor Warren Ashby  · Diretor de Black Rock  · Black Rock\nFIG U R A  · Q U EM É  · O ND E APAR EC E\nSargento Hank Purcell  · Chefe da guarda de Black Rock  · Black Rock\nDutch Kessler  · Preso nº 1187, ex-matador de Moretti  · Black Rock\nEzra Pike  · Faroleiro da ilha  · Black Rock\nIrmã Agnes  · Freira de São Brendan  · Black Rock\nZack Dombrowski e Abe\nFeldscher\nA Zachary Hobby Store  · Capítulos 8 e 9\nConduzindo a cidade. Cada bairro tem sua língua: Burocracia em Downtown, Respeito em White Hills,\nIdiomas e Respeito em Chinatown, Gíria das Ruas no Distrito de Waterford e em Saint Edwiges, Jargão de\nPolícia em qualquer lugar onde haja um tira. Na ilha, o único idioma é o dinheiro.\nO estoque do porão da banca: uma Thompson, um revólver e soqueiras."},"1994":{"regioes":[{"nome":"Downtown","resumo":"Vidro espelhado onde a Petrolífera compra licenças no café da manhã. Em 1994 se atira de dia na Montgomery.","lugares":[["Torre Monarch","31 andares; o escritório de Preston no topo"],["Prefeitura","Detector de metais e fila de jornalistas"],["Delegacia Central","Uma gaveta de moedas tchecas na mesa de Brannigan"],["Fórum","O gabinete da juíza Molly Reilly"],["Cine Montgomery","Palácio de 1931; a cabine ouve a sala inteira"],["Canal 7","No prédio da antiga Gazeta"],["Zachary Video","O porão é outra loja"],["Palermo 24h","O antigo Café Palermo, aberto a noite toda"],["Hotel St. Clair","A suíte do sétimo andar é do cartel"]],"dono":"A Monarch Petróleo, pelo escritório do 31º andar, e a Prefeitura que ela financia.","gancho":"Ozzie Pak liga para os protagonistas dizendo que gravou algo que não devia, e some antes do encontro; a fita está dentro da lata de um filme de kung fu na cabine. Uma família do Waterford pede ajuda para provar que a assinatura na escritura da casa foi falsificada dentro da Prefeitura."},{"nome":"White Hills","resumo":"As mesmas ladeiras, novos donos. Muros altos, paparazzi e bunkers de 1962 sob as quadras de tênis.","lugares":[["Mansão Harrow","A casa de Cordelia, jardim aberto aos domingos"],["Clube Pacífico","Uma sala sem janelas onde se cheira"],["Mansão Ashcroft","Fechada desde 1979, vigiada pela Monarch"],["Abrigo dos Lyman","Bunker de 1962 para doze pessoas"],["Sanatório Santa Úrsula","Reabilitação para herdeiros"],["Estação do Bonde do Topo","Agora atração turística"]],"dono":"Ninguém, de verdade.","gancho":"Bunny Lyman contrata os protagonistas para fotografar o marido com alguém, e as fotos mostram Preston com um homem da Távola. Cordelia Harrow pede que encontrem Eddie Lum, que não aparece há três dias."},{"nome":"Hipódromo de San Ysidro","resumo":"O coração do poder italiano desde 1966. O Tio Sam não sai do camarote.","lugares":[["Camarote Moretti","Vidro blindado e uma rampa para a cadeira de rodas"],["Guichês","Apostas legais na frente, ilegais nos fundos"],["Cocheiras","A baia 19 não tem cavalo"],["Lago do paddock","Cinco metros de lama"],["Clube dos Jóqueis","Fotos de 1934 na parede"],["Sala de pesagem","Chumbo costurado na sela"]],"dono":"A família Moretti, sem sócios.","gancho":"Dolly Pemberton pede proteção para correr o páreo de Natal sem perder de propósito. O Tio Sam manda buscar os protagonistas no meio da noite e oferece um trabalho que não se recusa: descobrir quem pagou o barbeiro em 1946."},{"nome":"Saint Edwiges","resumo":"A Strip: néon, discoteca, punk e metal. Os Moretti cobram aluguel de todos.","lugares":[["Discoteca Savoy","Globo espelhado e camarote VIP"],["The Iron Coffin","Heavy metal, motoqueiros, briga às sextas"],["Porão 77","Clube punk na antiga adega do Farol Azul"],["Peep Palace","Cabines de 25 centavos e fotos de gente importante"],["Barbearia Fratelli","A cadeira onde Sal Moretti morreu"],["Comuna da Rua Clay","Hippies desde 1967"]],"dono":"Os Moretti são donos dos imóveis e cobram aluguel de todos.","gancho":"Spider contrata os protagonistas com uma caixa de sapato cheia de moedas para achar quem batizou o pó que matou a irmã. Vinnie Ascoli aparece pendurado na pista da Savoy na hora da abertura, com o globo espelhado girando."},{"nome":"Chinatown","resumo":"O bairro que mais cresceu: academias de kung fu, bordéis e uma guerra silenciosa com os 14 Dragões.","lugares":[["Academia Garra de Jade","No antigo Teatro Mandarim"],["Casa de Chá do Dragão Jade","Vidros à prova de bala desde 1979"],["Casa das Mil Lanternas","O maior bordel da Rua Grant"],["Cine Golden Harvest","Sessão das duas da manhã"],["Pátio do Poço Velho","Mercado de armas aos sábados"],["Túneis de Chinatown","A rede de 1906, ampliada"]],"dono":"O Lótus Vermelho de Lin Jade, que protege as academias e cobra das casas.","gancho":"Lin Jade desafia um dos protagonistas para uma luta na academia: se ele perder, trabalha para o Lótus por uma semana. Madame Su pede que achem uma de suas moças, que sumiu depois de atender um homem de terno da Petrolífera."},{"nome":"Embarcadouro","resumo":"Contêineres, guindastes e russos. O porto fala russo depois da meia-noite.","lugares":[["Terminal do Píer 30","Mil contêineres empilhados"],["Galpão 14","Quartel da Bratva"],["Sauna Odessa","Negocia-se sem roupa e sem escuta"],["Restaurante Tbilisi","Ninguém come"],["Píer 9","Abandonado desde 1971"],["Igreja Ortodoxa da Pequena Varsóvia","Refugiados e documentos falsos"]],"dono":"A Bratva de Odessa, de Yuri Volkov.","gancho":"Irina Volkova procura os protagonistas para tirá-la da cidade com os livros contábeis do pai e oferece metade do que eles provam. Um contêiner aberto no Píer 30 tem doze pessoas dentro, e só uma ainda respira."},{"nome":"Distrito de Waterford","resumo":"Cidade operária à sombra da refinaria. As casas de 1910 estão marcadas com tinta laranja.","lugares":[["Refinaria Monarch","Onde era a Waterford S.A."],["O’Rourke’s","O pub de 1934, agora de Mikey Riordan"],["Drive-in Estrela do Estreito","Encontros nos carros do fundo"],["Boliche Shamrock","Apostas, brigas, recrutas"],["Igreja de São Brendan","O padre esconde famílias despejadas"],["Calle del Horno","Oficinas e os soldados de La Patrona"]],"dono":"Ninguém.","gancho":"Na noite de uma desapropriação, os moradores bloqueiam a rua com carros e chamam os protagonistas para segurar a linha até o amanhecer. Um operário morre na refinaria, e a viúva tem certeza de que não foi acidente."},{"nome":"Monumental Island","resumo":"A antiga ilha-prisão virou cassino em 1982. Políticos e apostadores chegam de barco toda noite.","lugares":[["Cassino do Bloco A","Roleta nas antigas celas"],["Cabaré do Pátio","O pátio de recreio virou palco"],["Hotel do Pavilhão Leste","Câmeras em cada quarto"],["Cofre da Administração","No réveillon, o diamante"],["Farol","Restaurante giratório"],["Túnel de 1853","Uma saída que ninguém vigia"]],"dono":"No papel, um consórcio de investidores limpos.","gancho":"Gloria Vane contrata os protagonistas para recuperar as fotos que o cassino usa para chantageá- la. O Senador Hollis Pratt é encontrado morto no quarto 214, e a câmera escondida foi arrancada da parede."},{"nome":"Estrada do Estreito","resumo":"Motéis, lanchonetes e rachas até a cabeceira da ponte. Ninguém manda, e por isso todo mundo usa.","lugares":[["Golden Gate Motel","O quarto 11 nunca é alugado"],["Lanchonete Moonlite","Cromo, vinil vermelho e torta de cereja"],["Posto Texaco 24h","Um telefone público sem rastro"],["A Reta","Dois quilômetros de racha"],["Motel Starlite","Garagens fechadas"],["Ferro-velho Mendoza","Carros sem número"]],"dono":"Ninguém, e por isso todo mundo usa.","gancho":"Kid Ruiz pede aos protagonistas que corram com ele contra Sonny Moretti, com um carro como prêmio e a família Moretti apostando contra. Darlene telefona de madrugada dizendo que três homens de terno estão perguntando por um dos protagonistas. A"},{"nome":"Owenfield","resumo":"O antigo gueto à sombra da chama da refinaria.","lugares":[],"dono":"","gancho":""},{"nome":"Monarch Heights","resumo":"As torres operárias da Monarch; a Torre F foi interditada.","lugares":[],"dono":"","gancho":""},{"nome":"A Trincheira","resumo":"O mercado noturno e a cidade que a cidade prefere não ver.","lugares":[],"dono":"","gancho":""},{"nome":"Greenspring Streets e a Galleria","resumo":"Subúrbio novo, shopping de vidro e cartões de crédito.","lugares":[],"dono":"","gancho":""}],"npcs":[{"n":"Preston Harrow-Lyman","p":"Vice-presidente Regional da Monarch Petróleo, 45 Anos","r":"Downtown","d":"Bisneto de Cornelius Ashcroft pelo lado de Vivian, sorriso de comercial de TV, cabelo que não se mexe com o vento. Herdou o banco falido da família, vendeu-o à Monarch e ficou com o cargo e com o cofre. É o Rei da Távola, e ninguém sabe.","v":"Paga escola para os filhos de três funcionários mortos na refinaria. Em silêncio.","pe":"Mandou roubar o próprio diamante para receber o seguro e culpar os irlandeses do Waterford.","q":"O Waterford vazio até março e uma cadeira no conselho da Monarch em Houston.","t":"Que o Tio Sam descubra que foi enganado; que a mulher fale.","a":"A Prefeitura (comprada), Victoria Holt (por contrato), a Távola (sem que ela saiba quem paga)."},{"n":"Prefeito Edmund Whitcombe III","p":"Prefeito de Saint Village, 52 Anos","r":"Downtown","d":"Bisneto do prefeito de 1934, ex-ator de comerciais de carro, voz grave e dentes perfeitos. Governa pela televisão e assina o que a Petrolífera manda, porque a campanha é paga por ela.","v":"Fechou dois prostíbulos de menores em Saint Edwiges no primeiro mandato, contra a vontade dos Moretti.","pe":"Vendeu as licenças de desapropriação por um fundo de campanha.","q":"A reeleição e um cargo em Washington.","t":"O quarto 214 da Monumental Island: há fotos dele lá.","a":"Preston Harrow-Lyman, Victoria Holt. Paga o Tio Sam para não ser incomodado."},{"n":"Ozzie Pak","p":"Projecionista do Cine Montgomery, 61 Anos","r":"Downtown","d":"Trabalha na cabine desde 1952. Conhece cada filme pela textura do som. Desde 1979 grava, num gravador de rolo escondido, as conversas da última fila, onde se fecham negócios no escuro.","v":"Avisou a polícia de um sequestro em 1981, por telefone anônimo; a menina voltou para casa.","pe":"Vende trechos das gravações para quem pagar, inclusive para a Imprensa.","q":"Aposentar-se com dinheiro suficiente para abrir um cinema pequeno no interior.","t":"Que alguém descubra o gravador; que a fita da última semana seja ouvida.","a":"Ninguém. Tito Barbosa compra as fitas dele."},{"n":"Cordelia Harrow","p":"Filantropa, 87 Anos, Investigadora em 1934","r":"White Hills","d":"A última consciência de White Hills. Bengala de prata, chapéu de feltro, voz de quem já mandou fechar uma fábrica. Passou sessenta anos devolvendo, em obras de caridade, o dinheiro que o pai ganhou com o massacre de 1932.","v":"Paga o advogado de cada família do Waterford que se recusa a sair.","pe":"Sabe desde 1935 que o diamante está no cofre Ashcroft e nunca contou.","q":"Salvar o Waterford antes de morrer.","t":"Morrer antes de terminar; que Preston fique com tudo.","a":"Eddie Lum, Mikey Riordan, a juíza Molly Reilly. Inimiga de Preston, embora o ame."},{"n":"Bunny Lyman","p":"Mulher de Preston, 39 Anos","r":"White Hills","d":"Rainha das festas beneficentes, cabelo armado, ombreiras douradas e um caso com Sonny Moretti. Casou por dinheiro e descobriu que o marido é mais perigoso do que rico.","v":"Protegeu a governanta quando Preston quis demiti-la.","pe":"Conta ao Tio Sam tudo o que o marido diz em casa.","q":"Sair do casamento com metade de tudo, viva.","t":"Que Preston descubra o caso; que Sonny conte a alguém.","a":"Tio Sam (informante), Sonny Moretti (amante)."},{"n":"Gerald Thorne","p":"Advogado da Família, 70 Anos","r":"White Hills","d":"Neto do Escritório Thorne & Vance de 1934. Redige os testamentos, as desapropriações e os acordos de silêncio de White Hills, numa sala forrada de livros que ninguém lê.","v":"Avisou, anonimamente, a juíza Reilly de uma fraude em 1976.","pe":"Assinou a apólice de seguro do carro-forte sabendo para que servia.","q":"Aposentar-se antes que alguém leia os papéis que ele assinou.","t":"O testamento de Cornelius, de 1979, que ele mesmo alterou.","a":"Preston Harrow-Lyman. Teme Cordelia."},{"n":"Samuele \"Tio Sam\" Moretti","p":"Chefe do Crime de Saint Village, 84 Anos","r":"Hipódromo de San Ysidro","d":"Filho caçula de Sal Moretti, cadeirante desde 1946, terno de linho mesmo no inverno, voz baixa e paciência de pedra. Gosta de assistir quando alguém paga uma dívida. Tem braços em todas as facções da cidade.","v":"Paga a escola de todos os sobrinhos-netos, inclusive dos que o odeiam.","pe":"Mandou matar vinte e três pessoas desde 1979; assistiu a nove.","q":"Os russos fora do porto e o nome de quem pagou o barbeiro em 1946.","t":"Morrer sem saber; que Sonny o tire da cadeira.","a":"Braços em toda a cidade (ver a tabela). Inimigo de Yuri Volkov. Desconfia de Preston."},{"n":"Sonny Moretti","p":"Sobrinho-neto do Tio Sam, 37 Anos","r":"Hipódromo de San Ysidro","d":"Neto de Vincent, jaqueta de couro branco, Camaro vermelho, cheira o que vende. Quer a cadeira do tio- avô e está negociando com os russos para consegui-la.","v":"Ama a filha de seis anos mais do que qualquer coisa.","pe":"Vende cocaína batizada da Bratva na Strip, sabendo que mata.","q":"Ser o chefe antes dos quarenta.","t":"O Tio Sam, que sabe de tudo e não diz nada.","a":"Bunny Lyman (amante), Yuri Volkov (em segredo)."},{"n":"Dolly Pemberton","p":"Jóquei, 24 Anos","r":"Hipódromo de San Ysidro","d":"Bisneta do antigo dono do hipódromo, um metro e meio de músculos e teimosia. Corre os páreos que o Tio Sam manda perder.","v":"Nunca dopou um cavalo, nem quando mandaram.","pe":"Perde de propósito três vezes por mês.","q":"Ganhar um páreo limpo, uma vez só.","t":"O páreo de Natal: mandaram que ela perca com o favorito.","a":"Nunzio Calà, o veterinário, que a protege."},{"n":"Vinnie Ascoli","p":"Gerente da Savoy, 40 Anos","r":"Saint Edwiges","d":"Terno branco, corrente de ouro, bronzeado de lâmpada. Cobra o aluguel da Strip para o Tio Sam e repassa a cocaína de La Patrona e, desde setembro, a da Bratva.","v":"Fecha a Savoy às sextas de Natal para uma festa beneficente para órfãos.","pe":"Sabia que o pó de setembro estava batizado e vendeu assim mesmo.","q":"Pagar o Tio Sam e o cartel ao mesmo tempo, sem que um saiba do outro.","t":"Que Spider descubra o que ele sabia.","a":"Tio Sam (braço), La Patrona (fornecedora), Sonny Moretti (sócio secreto)."},{"n":"Spider","p":"Baixista Punk, 19 Anos","r":"Saint Edwiges","d":"Cabelo espetado com sabão, coturno, jaqueta com o nome da banda pintado à mão nas costas. Vive no Porão 77 desde que a irmã morreu.","v":"Leva comida para os mendigos da Clay toda madrugada.","pe":"Já roubou dois carros para pagar o aluguel do porão.","q":"Vingar a irmã, morta por overdose de pó batizado.","t":"Virar o que ele odeia.","a":"Dee Dee Morrow, Mama Flor."},{"n":"Mama Flor","p":"Dona da Comuna da Rua Clay, 62 Anos","r":"Saint Edwiges","d":"Hippie de 1967, cabelo branco até a cintura, saia indiana e mente afiada. A comuna dela abriga fugitivos, doentes e testemunhas.","v":"Escondeu duzentas pessoas da polícia em dezessete anos.","pe":"Esconde, agora, uma testemunha do roubo da Montgomery, e cobra por isso.","q":"Que os tratores não cheguem à Rua Clay.","t":"A Petrolífera, que quer a quadra para um centro comercial.","a":"Spider, padre Tom Quinn, Cordelia Harrow (doadora)."},{"n":"Lin Jade","p":"Mestra de Academia e Chefe do Lótus Vermelho, 44 Anos","r":"Chinatown","d":"Neta de Lin Mei-Hua, vendia ingresso no Teatro Mandarim em 1973 e o transformou em academia. Fala pouco, varre o tablado sozinha toda noite e nunca perdeu uma luta, salvo uma, em 1979, para uma mulher chamada Ruby Halloran.","v":"Paga o hospital de toda moça das casas que adoece.","pe":"Cobra das casas o que a polícia cobraria, e um pouco mais.","q":"Expulsar os 14 Dragões sem deixar a polícia entrar.","t":"Que os de uma porta vejam os da outra.","a":"Madame Su, Kenji Hale. Respeita Ruby Halloran. Inimiga de Tony Kwan."},{"n":"Tony Kwan, \"Dragão Branco\"","p":"Chefe dos 14 Dragões, 29 Anos","r":"Chinatown","d":"Chegou de Hong Kong em 1992, fugindo da devolução da colônia à China em 1997, terno italiano, mocassim sem meia, um sorriso de propaganda de cigarro. Compra armas dos russos e recebe outras dos Moretti, de graça.","v":"Mantém um templo pequeno para a mãe, que ficou em Hong Kong.","pe":"Comprou a luta de Kenji Hale em agosto e guarda o recibo.","q":"As casas, o porto e a cabeça de Lin Jade.","t":"Que o Tio Sam pare de mandar armas.","a":"Tio Sam (braço), Bratva (fornecedora)."},{"n":"Madame Su","p":"Dona da Casa das Mil Lanternas, 55 Anos","r":"Chinatown","d":"Trabalhou na Rua Grant desde os dezesseis anos e hoje é dona da maior casa do bairro. Guarda um caderno com o nome de cada cliente desde 1964.","v":"Nunca aceitou menores em casa, nem quando pagavam o triplo.","pe":"Vende nomes do caderno para a Imprensa quando precisa.","q":"Que as moças saiam vivas da guerra; achar a moça que sumiu.","t":"Que alguém leia o caderno inteiro.","a":"Lin Jade. Talvez a Viúva, que já passou por aqui, segundo os boatos."},{"n":"Yuri Volkov","p":"Chefe da Bratva de Odessa, 52 Anos","r":"Embarcadouro","d":"Ex-oficial da marinha soviética, ombros de estivador, óculos de leitura pendurados no pescoço. Joga xadrez com os capangas antes de mandar matá-los. Vende informação à KGB e à CIA, e a nenhuma das duas o suficiente.","v":"Paga o aluguel de quarenta famílias de refugiados.","pe":"Vende heroína e armas; mandou batizar o pó da Strip para queimar o cartel.","q":"O porto inteiro e a Strip, antes dos Moretti.","t":"A filha; ser mandado de volta.","a":"Metade da Narcóticos, Sonny Moretti (em segredo), os 14 Dragões (clientes). Inimigo do Tio Sam."},{"n":"Irina Volkova","p":"Filha de Yuri, Contadora, 28 Anos","r":"Embarcadouro","d":"Formada em Leningrado, cabelo loiro de farmácia, dente de ouro do lado esquerdo. Faz os livros da Bratva e decidiu, em outubro, que não quer mais.","v":"Desviou dinheiro do pai para as famílias da igreja.","pe":"Copiou os livros contábeis para vender a quem a tirar da cidade.","q":"Sair de Saint Village viva, com os livros.","t":"Que o pai a encontre antes do Natal.","a":"Frankie Vega (sem saber que é protagonista). Padre Aleksei."},{"n":"Bogdan, \"o Urso\"","p":"Matador da Bratva, 40 Anos","r":"Embarcadouro","d":"Dois metros, mãos de pá, uma tatuagem de igreja ortodoxa nas costas, uma cúpula para cada morte. Tem catorze cúpulas.","v":"Nunca matou mulher, nem quando mandaram.","pe":"Catorze mortes.","q":"Cumprir ordens e voltar para casa um dia.","t":"Que o mandem matar Irina.","a":"Yuri Volkov, até a ordem errada."},{"n":"Mikey Riordan","p":"Dono do O'rourke's, 58 Anos","r":"Distrito de Waterford","d":"Filho de Tommy Riordan e Angela Moretti, neto de Biddy Riordan, sobrinho-neto do Tio Sam. Ombros largos, nariz quebrado três vezes, voz de quem já foi presidente do Local 9. Um dos irlandeses que ficaram.","v":"Dá cerveja fiado a quem perdeu o emprego.","pe":"Mantém o bairro calmo para o tio, em troca de uma dívida perdoada.","q":"Impedir as demolições, de qualquer jeito.","t":"Ter de escolher entre o bairro e a família.","a":"Padre Tom Quinn, La Patrona (acordo), Cordelia Harrow. Braço relutante do Tio Sam."},{"n":"Marisol Rosales, \"La Patrona\"","p":"Chefe dos Hijos Del Horno, 44 Anos","r":"Distrito de Waterford","d":"Cresceu na Calle del Horno, ficou viúva três vezes, todas por escolha. Comanda as oficinas, a cocaína da Estrada do Estreito e as esquinas do Distrito. Usa óculos escuros à noite.","v":"Paga o enterro de cada morto do bairro, de qualquer lado.","pe":"A cocaína que passa pela estrada mata gente na Strip.","q":"A Calle intacta e a estrada só dela, longe dos russos.","t":"Que a Bratva descubra a rota.","a":"Mikey Riordan, Ana Ortiz (amiga de escola). Inimiga da Bratva."},{"n":"Padre Tom Quinn","p":"Pároco de São Brendan, 50 Anos","r":"Distrito de Waterford","d":"Neto de Patrick Quinn, o operário cujo laudo foi falsificado em 1934. Esconde famílias despejadas na sacristia e guarda uma pasta com cada documento de desapropriação.","v":"Nunca negou abrigo a ninguém.","pe":"Sabe quem incendiou o escritório da Petrolífera em outubro e não conta.","q":"Que a refinaria pague pelos mortos.","t":"Que a pasta seja roubada.","a":"Mikey Riordan, Mama Flor, Cordelia Harrow."},{"n":"Lou Cassidy","p":"Gerente do Cassino, 50 Anos","r":"Monumental Island","d":"Sorriso de crupiê, smoking de veludo, unhas feitas. Lava o dinheiro do Tio Sam e guarda as fotografias dos quartos num cofre dentro do cofre.","v":"Nunca deixou ninguém sair da ilha bêbado ao volante de uma lancha.","pe":"Chantageia meio legislativo estadual.","q":"Agradar ao Tio Sam e sobreviver ao réveillon.","t":"Que as fotos saiam do cofre; que a Petrolífera vire sócia e o demita.","a":"Tio Sam (braço). Victoria Holt (compra fotos dele)."},{"n":"Gloria Vane","p":"Cantora do Cabaré, 48 Anos","r":"Monumental Island","d":"Foi famosa em 1966 e cantou no Ed Sullivan. Hoje canta seis noites por semana para políticos que pedem a mesma música. Escreve canções que ninguém ouviu.","v":"Dá metade do cachê para as moças da ilha que querem ir embora.","pe":"Esconde uma arma no estojo de maquiagem desde 1981.","q":"Recuperar as fotos e cantar a sua música nova à meia-noite do réveillon.","t":"Que o senador a reconheça na primeira fila.","a":"As moças da ilha. Odeia Lou Cassidy."},{"n":"Gunnar Lindqvist","p":"Chefe da Segurança, 74 Anos","r":"Monumental Island","d":"Ex-guarda da prisão em 1963, neto do legista de 1934. Conhece cada cela, cada túnel e cada fechadura da ilha. Ficou para trás na noite da transferência e nunca mais saiu.","v":"Salvou um preso de um incêndio em 1961.","pe":"Guarda o que a transferência de 1963 deixou no túnel, e vende pedaços.","q":"Que ninguém abra o túnel.","t":"Que descubram o que tem no túnel.","a":"Lou Cassidy, por obrigação."},{"n":"Darlene","p":"Garçonete da Moonlite, 46 Anos","r":"Estrada do Estreito","d":"Avental cor-de-rosa, cabelo armado com laquê, um lápis atrás da orelha. Trabalha no turno da noite há vinte anos e sabe o pedido de cada matador da Costa Oeste.","v":"Nunca deixou ninguém morrer no turno dela; já escondeu três pessoas na câmara fria.","pe":"Vende o que sabe para quem deixar a melhor gorjeta.","q":"Que ninguém morra no turno dela.","t":"Que a Távola volte a se reunir no Golden Gate.","a":"Kid Ruiz, Eddie Lum (cliente de quarenta anos)."},{"n":"\"Kid\" Ruiz","p":"Piloto de Racha, 22 Anos","r":"Estrada do Estreito","d":"Jaqueta de cetim, cabelo com gel, um Dodge Charger preto de 1969 envenenado na Calle del Horno. Invicto na Reta.","v":"Divide os prêmios com a mãe e as três irmãs.","pe":"Leva cocaína de La Patrona no porta-malas, uma vez por mês.","q":"Correr fora daqui, numa pista de verdade.","t":"Perder o carro.","a":"La Patrona, Darlene. Rival de Sonny Moretti."},{"n":"Otis Mendoza","p":"Dono do Ferro-velho, 60 Anos","r":"Estrada do Estreito","d":"Sobrinho-neto do Dr. Elias Mendoza, o legista de 1934. Compra tudo o que chega sem pergunta e desmancha em uma noite.","v":"Guarda o arquivo do tio-avô, com os laudos verdadeiros de 1934.","pe":"Desmontou o carro-forte da Montgomery na mesma tarde do roubo.","q":"Aposentar-se rico e em silêncio.","t":"Que alguém ache a placa do carro-forte que ele ainda não derreteu.","a":"Quem pagar."}],"textos":{"Downtown":"DOWNTOWN\n\"Saint Village sempre olhou para o mar. A Monarch olha para o futuro. Empregos,\nestradas, energia para a sua família.\" Pronto. Foi?\nGerald, a família da casa 114, a da varanda azul. Eles assinaram? Não? Ofereça mais\ndois mil e diga que a casa tem cupim. Tem cupim, Gerald. Todas as casas do\nWaterford têm cupim. Foram construídas em 1910 por irlandeses que bebiam no\nalmoço.\nA minha bisavó Vivian dizia que esta cidade foi feita por gente que sabia esperar.\nEla esperou o pai morrer, esperou o irmão sumir, esperou a fortuna cair do céu.\nEu não espero. Eu cheguei em casa num domingo de 1979, abri o cofre do banco\nque acabei de comprar e encontrei, numa caixa de charutos, a coisa mais bonita\nque já vi na vida. Azul. Do tamanho de um ovo de codorna. Senti que alguém tinha\nesquecido o futuro dentro de uma gaveta.\nO problema desta cidade é que todo mundo acha que é dono de uma rua. O\nitaliano acha que é dono do porto, o russo acha que é dono do porto, os irlandeses\nachavam que eram donos do porto e agora estão em Bakersfield. Tudo tem um\npreço por metro quadrado, e quem paga o metro quadrado escreve a história da\nrua.\nGerald, e o seguro do carro-forte? Está tudo assinado? Ótimo. Não precisa me\ndizer mais nada. Quanto menos eu souber, melhor eu durmo.\nOito. Sorrindo. \"Saint Village sempre olhou para o mar.\"\n— P r e s t o n H a r r o w - Ly m a n , g r a v a n d o u m c o m e r c i a l n o C a n a l 7\n“\n“Do 31º andar a cúpula da Prefeitura parece uma maquete. É assim que eu gosto dela.”\n— P r e s t o n H a r r o w - Ly m a n , T o r r e M o n a r c h\nDowntown virou uma vitrine de vidro espelhado onde a Petrolífera compra licenças no café da manhã e a\nPrefeitura assina desapropriações no almoço. Ao meio-dia a Montgomery está cheia de ternos de\nombreira, sapatos de bico fino e walkmans pendurados na cintura; à meia-noite, de gente vendendo o que\nos ternos compram. Entre as torres sobrevivem o Fórum de granito, a Delegacia de tijolo vermelho com o\nar-condicionado quebrado desde 1979, a Prefeitura de cúpula de cobre e o Cine Montgomery, um palácio\nart déco de 1931 que hoje passa kung fu, faroeste spaghetti e terror em sessão dupla.\nDe dia, Downtown é a cidade que aparece no telejornal: inaugurações, coletivas, executivos atravessando a\nrua com pressa. De noite, é a cidade que o telejornal não mostra: carros parados em fila dupla na frente\ndo Hotel St. Clair, gente entrando pela porta dos fundos da Delegacia, a fila da sessão das duas no Cine\nMontgomery. Em 1994 se atira de dia na Montgomery. O carro-forte do Banco Ashcroft foi atacado ao\nmeio-dia, e a polícia levou onze minutos para chegar.\nL E I A E M V O Z A L T A\nA Montgomery ao meio-dia cheira a cachorro-quente, fumaça de ônibus e perfume caro. Os prédios de vidro\ndevolvem o sol em todas as direções, e é difícil saber de onde vem a luz. Na calçada, um homem de terno grita num\ntelefone público enquanto outro, encostado na banca de jornal, folheia o Flagrante e não lê nada. Do outro lado da\nrua, o letreiro do Cine Montgomery anuncia em letras vermelhas faltando duas: \"SESSÃO DUP A · O PUNHO DE\nFERRO · VINGANÇA EM HONG KO G\".\nQuem manda. A Monarch Petróleo, pelo escritório do 31º andar, e a Prefeitura que ela financia. A\nDelegacia Central cobra pedágio de todos. O Tio Sam tem um vereador na folha.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nTorre Monarch Trinta e um andares de vidro fumê; o escritório de\nPreston no último, com vista para o Waterford\nMapas das desapropriações, quem na Prefeitura\nrecebeu, a apólice de seguro do carro-forte\nPrefeitura · A cúpula de cobre de 1934, agora com detector de\nmetais e fila de jornalistas na escadaria\nVotos comprados, o calendário das demolições,\na agenda do prefeito\nDelegacia\nCentral\nTijolo vermelho, café de garrafa térmica, uma\ngaveta cheia de moedas tchecas na mesa de\nBrannigan\nQuem foi solto, provas que sumiram, o preço de\ncada tira\nFórum · Granito, escadaria, corredores onde advogados\nnegociam penas no bebedouro\nProcessos arquivados, o gabinete da juíza Molly\nReilly\nCine\nMontgomery\nPalácio de 1931 com 1.800 lugares, metade\nquebrados; o lustre ainda funciona\nEncontros na última fila; a cabine de projeção\nouve a sala inteira\nCanal 7 · No prédio da antiga Gazeta, na Praça do Fórum · Fitas que não foram ao ar, quem pagou para não\naparecer\nZachary Video Videolocadora na esquina da Praça do Fórum; o\nporão é outra loja\nArmas, documentos, fitas gravadas e Tito\nBarbosa\nPalermo 24h · O antigo Café Palermo, lanchonete aberta a noite\ntoda\nConversas de tiras, taxistas e jornalistas depois\ndo turno\nHotel St. Clair Decadente; a suíte do sétimo andar virou sala de\nnegócios do cartel\nQuem se encontra com quem, e quem não sai do\nelevador\nPlanta do Cine Montgomery\nPreston Harrow-Lyman\nVICE-PRESIDENTE REGIONAL DA MONARCH PETRÓLEO, 45 ANOS\nBisneto de Cornelius Ashcroft pelo lado de Vivian, sorriso de comercial de TV, cabelo que não se mexe\ncom o vento. Herdou o banco falido da família, vendeu-o à Monarch e ficou com o cargo e com o cofre. É\no Rei da Távola, e ninguém sabe.\nVIRTUDE\nPaga escola para os filhos de três funcionários mortos\nna refinaria. Em silêncio.\nPECADO\nMandou roubar o próprio diamante para receber o seguro e\nculpar os irlandeses do Waterford.\nQUER\nO Waterford vazio até março e uma cadeira no\nconselho da Monarch em Houston.\nTEME\nQue o Tio Sam descubra que foi enganado; que a mulher fale.\nAlianças: A Prefeitura (comprada), Victoria Holt (por contrato), a Távola (sem que ela saiba quem paga).\nInimigo de Mikey Riordan e de Cordelia Harrow.\nPrefeito Edmund Whitcombe III\nPREFEITO DE SAINT VILLAGE, 52 ANOS\nBisneto do prefeito de 1934, ex-ator de comerciais de carro, voz grave e dentes perfeitos. Governa pela\ntelevisão e assina o que a Petrolífera manda, porque a campanha é paga por ela.\nVIRTUDE\nFechou dois prostíbulos de menores em Saint Edwiges no primeiro\nmandato, contra a vontade dos Moretti.\nPECADO\nVendeu as licenças de desapropriação por um\nfundo de campanha.\nQUER\nA reeleição e um cargo em Washington.\nTEME\nO quarto 214 da Monumental Island: há fotos\ndele lá.\nAlianças: Preston Harrow-Lyman, Victoria Holt. Paga o Tio Sam para não ser incomodado.\nOzzie Pak\nPROJECIONISTA DO CINE MONTGOMERY, 61 ANOS\nTrabalha na cabine desde 1952. Conhece cada filme pela textura do som. Desde 1979 grava, num gravador\nde rolo escondido, as conversas da última fila, onde se fecham negócios no escuro.\nVIRTUDE\nAvisou a polícia de um sequestro em 1981, por telefone anônimo;\na menina voltou para casa.\nPECADO\nVende trechos das gravações para quem pagar,\ninclusive para a Imprensa.\nQUER\nAposentar-se com dinheiro suficiente para abrir um cinema\npequeno no interior.\nTEME\nQue alguém descubra o gravador; que a fita da\núltima semana seja ouvida.\nAlianças: Ninguém. Tito Barbosa compra as fitas dele.\n1 d 6 R u m o r · V e r d a d e ?\n1 · A Petrolífera tem um vereador para cada desapropriação · Verdade: sete de nove\n2 · O prefeito vai renunciar antes do réveillon · Falso\n3 · Alguém grava a última fila do Cine Montgomery · Verdade: Ozzie Pak, desde 1979\n4 · O cofre do Banco Ashcroft tinha algo que não estava no inventário Verdade: o Coração do Lago\n5 · Brannigan matou um parceiro em 1977 e chamou de suicídio · Meia verdade: assistiu e não impediu\n6 · Os abrigos sob o Fórum estão cheios de comida enlatada · Falso: estão cheios de armas apreendidas\nGanchos. Ozzie Pak liga para os protagonistas dizendo que gravou algo que não devia, e some antes do\nencontro; a fita está dentro da lata de um filme de kung fu na cabine. Uma família do Waterford pede\najuda para provar que a assinatura na escritura da casa foi falsificada dentro da Prefeitura.","White Hills":"WHITE HILLS\nEu abro o jardim aos domingos para as crianças do Waterford desde 1958. Elas\nsobem a ladeira de bonde, de mãos dadas, e correm na grama que o meu pai\nmandou plantar com o dinheiro que eu descobri de onde vinha numa carta de\n1932. As mães ficam no portão, sem entrar, como se o portão ainda fosse delas a\nnão atravessar.\nTenho setenta e sete anos. Já fui investigadora, uma vez, durante um ano, quando\nera jovem e achava que a verdade servia para alguma coisa. Ela serviu para pouco.\nServiu para eu saber de onde vinha cada colher de prata desta casa, e para eu passar\nsessenta anos devolvendo as colheres uma a uma, em forma de escola, de hospital,\nde bolsa de estudos.\nO meu sobrinho Preston acha que eu sou uma velha sentimental. Ele vem jantar\numa vez por mês, fala de progresso entre a sopa e o peixe e olha o relógio de\npêndulo da sala como quem calcula quanto vale. Ele não sabe que eu sei do cofre.\nNão sabe que o velho Ashcroft me mostrou o diamante em 1935, numa caixa de\ncharutos, e me fez jurar que eu nunca contaria a ninguém de onde ele tinha vindo.\nO Eddie Lum não aparece há três dias. Ele vem toda quinta, de táxi, tomar chá e\nreclamar do médico. Na última vez trouxe uma coroa tcheca e deixou em cima da\nmesa, sem explicar.\nEu ainda tenho a carta do meu pai. E agora tenho uma moeda.\n— C o r d e l i a H a r r o w , M a n s ã o H a r r o w , W h i t e H i l l s\n“\n“Enquanto a vela estiver acesa, a casa é minha. Os guardas do portão são do meu sobrinho.”\n— C o r d e l i a H a r r o w , 8 7 a n o s\nNa colina, o dinheiro velho vende a prataria para o dinheiro novo e finge que é doação. As mansões de\n1934 ainda estão lá; metade foi dividida em apartamentos para médicos e advogados, a outra metade tem\ncerca elétrica, cachorro e um abrigo antiaéreo de concreto no jardim, com adega, piscina e lugar marcado\npara cada membro da família. Os empregados não têm lugar marcado.\nO bonde ainda sobe a Califórnia até a Estação do Topo, agora cheio de turistas de bermuda que\nfotografam a baía. Nas festas de sexta, a cocaína passa em bandejas de prata herdadas, e os filhos das\nfamílias antigas dançam com os filhos dos executivos da Petrolífera. Ninguém fala de onde vem o dinheiro\nde ninguém. É a única regra que sobreviveu a 1934.\nL E I A E M V O Z A L T A\nA ladeira da Califórnia sobe tão íngreme que o bonde geme a cada quarteirão. Lá em cima, as casas recuam atrás\nde portões de ferro e cercas vivas aparadas como cabelo de militar. Um jardineiro mexicano rega rosas às dez da\nnoite. Num gramado, sob a luz de um poste de ferro fundido, uma placa amarela pregada no tronco de um pinheiro\navisa: \"ABRIGO PARTICULAR · ACESSO SOMENTE A MORADORES\".\nQuem manda. Ninguém, de verdade. Cordelia Harrow ainda freia o que pode no conselho do Clube\nPacífico, mas o sobrinho Preston já votou contra ela duas vezes. Bunny Lyman conta ao Tio Sam o que\nouve em casa.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nMansão Harrow · A casa de Cordelia, com o jardim aberto aos\ndomingos\nA carta de 1932; quem ainda visita a velha\nsenhora\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nClube Pacífico · O mesmo clube de 1934, com quadra de squash e\numa sala sem janelas onde se cheira\nQuem jantou com quem; os acordos da\nPetrolífera\nMansão Ashcroft Fechada desde 1979, vigiada por seguranças da\nMonarch\nO escritório de Cornelius, trancado desde\n1934\nAbrigo dos Lyman Bunker de 1962 sob a quadra de tênis, para doze\npessoas\nDocumentos que a família quer que\nsobrevivam ao Grande Terremoto\nSanatório Santa\nÚrsula\nClínica de reabilitação para herdeiros · Filhos internados por saberem demais, de\nnovo\nEstação do Bonde\ndo Topo\nPonto final do bonde, agora atração turística · Empregadas e motoristas que veem tudo\nCordelia Harrow\nFILANTROPA, 87 ANOS, INVESTIGADORA EM 1934\nA última consciência de White Hills. Bengala de prata, chapéu de feltro, voz de quem já mandou fechar\numa fábrica. Passou sessenta anos devolvendo, em obras de caridade, o dinheiro que o pai ganhou com o\nmassacre de 1932.\nVIRTUDE\nPaga o advogado de cada família do Waterford que se\nrecusa a sair.\nPECADO\nSabe desde 1935 que o diamante está no cofre Ashcroft e\nnunca contou.\nQUER\nSalvar o Waterford antes de morrer.\nTEME\nMorrer antes de terminar; que Preston fique com tudo.\nAlianças: Eddie Lum, Mikey Riordan, a juíza Molly Reilly. Inimiga de Preston, embora o ame.\nBunny Lyman\nMULHER DE PRESTON, 39 ANOS\nRainha das festas beneficentes, cabelo armado, ombreiras douradas e um caso com Sonny Moretti. Casou\npor dinheiro e descobriu que o marido é mais perigoso do que rico.\nVIRTUDE\nProtegeu a governanta quando Preston quis demiti-la.\nPECADO\nConta ao Tio Sam tudo o que o marido diz em casa.\nQUER\nSair do casamento com metade de tudo, viva.\nTEME\nQue Preston descubra o caso; que Sonny conte a alguém.\nAlianças: Tio Sam (informante), Sonny Moretti (amante).\nGerald Thorne\nADVOGADO DA FAMÍLIA, 70 ANOS\nNeto do Escritório Thorne & Vance de 1934. Redige os testamentos, as desapropriações e os acordos de\nsilêncio de White Hills, numa sala forrada de livros que ninguém lê.\nVIRTUDE\nAvisou, anonimamente, a juíza Reilly de uma fraude em\n1976.\nPECADO\nAssinou a apólice de seguro do carro-forte sabendo para que\nservia.\nQUER\nAposentar-se antes que alguém leia os papéis que ele\nassinou.\nTEME\nO testamento de Cornelius, de 1979, que ele mesmo alterou.\nAlianças: Preston Harrow-Lyman. Teme Cordelia.\n1 d 6 R u m o r · V e r d a d e ?\n1 · Cordelia Harrow está doente e vai deixar tudo para os\noperários\nMeia verdade: está doente; o testamento ainda não foi\nassinado\n2 · Os Lyman construíram o abrigo com dinheiro da\nPrefeitura\nVerdade\n3 · Bunny Lyman tem um caso com Sonny Moretti · Verdade\n4 · A Mansão Ashcroft tem um quarto que ninguém abre\ndesde 1934\nVerdade: o escritório de Cornelius\n5 · O Clube Pacífico vai aceitar sócios russos · Falso, por enquanto\n6 · Preston não é filho de quem diz ser · Falso, mas ele teme que seja\nGanchos. Bunny Lyman contrata os protagonistas para fotografar o marido com alguém, e as fotos\nmostram Preston com um homem da Távola. Cordelia Harrow pede que encontrem Eddie Lum, que não\naparece há três dias.","Hipódromo de San Ysidro":"HIPÓDROMO DE SAN YSIDRO\nVocê já cortou o cabelo na Fratelli? Não? Devia. O filho do Enzo tem a mão do pai.\nMão firme, navalha de cabo de osso, toalha quente no rosto antes. Eu ainda vou lá\ntoda primeira segunda-feira do mês. As pessoas acham que é coragem. É costume.\nEu sentei naquela cadeira em 1946 com o meu pai na cadeira ao lado, e quando eu\nacordei, três semanas depois, eu não sentia mais nada da cintura para baixo e o\nmeu pai já estava no cemitério de São Brendan com um terno que não era dele.\nSabe o que eu aprendi naquele hospital? Que ficar parado não é tão ruim. Você fica\nparado e as coisas vêm até você. A enfermeira vem. O padre vem. O meu irmão\nVincent vinha toda tarde, com laranja, e sentava onde você está sentado agora, e\nchorava. Trinta e três anos eu esperei descobrir por que o Vincent chorava tanto.\nNão, não se mexe. A corda é de cavalo, não arrebenta.\nO cavalo daqui do lado se chama Cavaleiro Negro. Vai ganhar o páreo de Natal.\nNão porque é o melhor, mas porque eu já decidi. O seu chefe acha que pode\ncomprar o porto com rublo e com paciência. Eu tenho mais paciência que ele. Eu\ntenho trinta e oito anos de paciência sentado nesta cadeira.\nAgora você vai me contar quantos contêineres entram na quinta-feira, e eu vou\nouvir. Eu ouço muito bem. É outra coisa que a cadeira ensina.\nNunzio, traz o balde. E desliga o rádio, que eu quero ouvir o páreo das cinco.\n— S a m u e l e \" T i o S a m \" M o r e t t i , b a i a 1 9 d o h i p ó d r o m o\n“\n“O Cavaleiro Negro ganha o páreo de Natal. Não porque é o melhor. Porque eu já decidi.”\n— S a m u e l e “ T i o S a m ” M o r e t t i\nO hipódromo é a corte do Tio Sam. Nas tardes de corrida, a arquibancada enche de operários apostando\no salário e de juízes apostando a carreira; no camarote de vidro blindado, Samuele Moretti assiste aos\npáreos e às dívidas com o mesmo binóculo. Os cavalos correm dopados, os jóqueis correm com medo, e\no lago do paddock, decorativo, com patos e cinco metros de lama, é fundo o bastante para um carro.\nO hipódromo foi de Pemberton até 1934 e de ninguém até 1966, quando os Moretti o compraram falido.\nHoje é a sede da família: as apostas legais pagam os impostos, as ilegais pagam o resto, e a agiotagem paga\no que sobra. Quem deve ao Tio Sam é convidado para ver um páreo no camarote. Quem não paga é\nconvidado para ver as cocheiras.\nL E I A E M V O Z A L T A\nA arquibancada ruge quando os cavalos fazem a curva, um ruído de vinte mil vozes que treme o concreto. No alto,\natrás de um vidro escuro, um velho numa cadeira de rodas cromada não se mexe. Na pista, um cavalo negro com o\nnúmero 7 ganha por meio corpo, e um homem de boné, na fila do guichê, rasga o bilhete devagar, como quem rasga\numa carta de amor.\nQuem manda. A família Moretti, sem sócios. O Tio Sam decide os páreos, os juros e quem sai do\nestábulo andando.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nCamarote\nMoretti\nVidro blindado, carpete vermelho, uma rampa para a\ncadeira de rodas\nQuem deve, quanto e até quando\nGuichês · Apostas legais na frente, ilegais na cabine dos fundos · O dinheiro que circula antes de um páreo\narranjado\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nCocheiras · Quarenta baias, um veterinário que injeta o que\nmandam; a baia 19 não tem cavalo\nCavalos dopados, um contador russo\namarrado a uma cadeira\nLago do\npaddock\nDecorativo, com patos e cinco metros de lama · Carros, armas e gente que não pagou\nClube dos\nJóqueis\nBar de madeira escura com fotos de 1934 na parede · Fofoca de pista e quem apostou contra a\ncasa\nSala de\npesagem\nOnde o jóquei sobe na balança antes do páreo · Chumbo costurado na sela, contratos de\npáreo\nPlanta do Hipódromo\nSamuele \"Tio Sam\" Moretti\nCHEFE DO CRIME DE SAINT VILLAGE, 84 ANOS\nFilho caçula de Sal Moretti, cadeirante desde 1946, terno de linho mesmo no inverno, voz baixa e\npaciência de pedra. Gosta de assistir quando alguém paga uma dívida. Tem braços em todas as facções da\ncidade.\nVIRTUDE\nPaga a escola de todos os sobrinhos-netos, inclusive dos que o\nodeiam.\nPECADO\nMandou matar vinte e três pessoas desde 1979; assistiu\na nove.\nQUER\nOs russos fora do porto e o nome de quem pagou o barbeiro\nem 1946.\nTEME\nMorrer sem saber; que Sonny o tire da cadeira.\nAlianças: Braços em toda a cidade (ver a tabela). Inimigo de Yuri Volkov. Desconfia de Preston.\nSonny Moretti\nSOBRINHO-NETO DO TIO SAM, 37 ANOS\nNeto de Vincent, jaqueta de couro branco, Camaro vermelho, cheira o que vende. Quer a cadeira do tio-\navô e está negociando com os russos para consegui-la.\nVIRTUDE\nAma a filha de seis anos mais do que qualquer coisa.\nPECADO\nVende cocaína batizada da Bratva na Strip, sabendo que mata.\nQUER\nSer o chefe antes dos quarenta.\nTEME\nO Tio Sam, que sabe de tudo e não diz nada.\nAlianças: Bunny Lyman (amante), Yuri Volkov (em segredo).\nDolly Pemberton\nJÓQUEI, 24 ANOS\nBisneta do antigo dono do hipódromo, um metro e meio de músculos e teimosia. Corre os páreos que o\nTio Sam manda perder.\nVIRTUDE\nNunca dopou um cavalo, nem quando mandaram.\nPECADO\nPerde de propósito três vezes por mês.\nQUER\nGanhar um páreo limpo, uma vez só.\nTEME\nO páreo de Natal: mandaram que ela perca com o favorito.\nAlianças: Nunzio Calà, o veterinário, que a protege.\n1 d 6 R u m o r · V e r d a d e ?\n1 · O Tio Sam consegue andar e finge a cadeira · Falso\n2 · Há um homem preso numa baia há três semanas · Verdade: um contador da Bratva\n3 · O páreo de Natal já tem vencedor · Verdade: Cavaleiro Negro, número 7\n4 · Sonny está negociando com os russos · Verdade, e o Tio Sam sabe\n5 · Quem atirou em 1946 foi gente da própria família · Verdade: Vincent pagou o barbeiro\n6 · O lago do paddock vai ser drenado pela Prefeitura · Falso, mas o Tio Sam está preocupado\nGanchos. Dolly Pemberton pede proteção para correr o páreo de Natal sem perder de propósito. O Tio\nSam manda buscar os protagonistas no meio da noite e oferece um trabalho que não se recusa: descobrir\nquem pagou o barbeiro em 1946.","Saint Edwiges":"SAINT EDWIGES\nA minha irmã se chamava Debbie. Ela tinha vinte e quatro anos, trabalhava de\ncaixa no supermercado da Pacific e ia à Savoy todo sábado porque gostava de\ndançar debaixo daquele globo de espelhos, que ela dizia que parecia uma estrela\nque alguém tinha trazido para dentro. Eu odiava a Savoy. Eu odiava a música, as\ncalças brancas, o gerente de terno branco. A gente brigava por isso. Era a nossa\nbriga favorita.\nNo sábado dezoito de setembro ela entrou no banheiro da Savoy às duas e dez e\nnão saiu. Acharam ela às três e meia, sentada na tampa da privada, com a cabeça\nencostada na parede de azulejo cor-de-rosa, como quem cochila no ônibus.\nO pó estava batizado. Isso a polícia nem precisou investigar, porque morreram\nmais quatro naquela semana na Strip, todos com o mesmo pó. O capitão gordo da\nNarcóticos foi ao Canal 7 e disse que era uma tragédia da juventude. A juventude.\nComo se a juventude tivesse vendido o pó.\nEu toquei naquela noite no Porão 77. Toquei a música mais rápida que a gente\ntinha, três vezes seguidas, e no fim quebrei o baixo no amplificador, e todo mundo\nachou que era parte do show.\nJuntei moeda numa caixa de sapato durante dois meses. Tem duzentos e catorze\ndólares e uns centavos. Dizem que tem gente que faz o trabalho que a polícia não\nfaz. Eu quero contratar alguém. Ou quero aprender.\n— S p i d e r , b a i x i s t a d o P o r ã o 7 7\n“\n“Três acordes, trinta pessoas e uma goteira em cima do baixo. Melhor palco da Califórnia.”\n— S p i d e r , b a i x i s ta d o P o r ã o 7 7\nA Strip começa na Rua Pacific e só termina quando o dinheiro acaba. Numa mesma quadra cabem uma\ndiscoteca de piso iluminado, um bar de heavy metal com o som rachando a parede, um peep show de\nvinte e cinco centavos e um porão onde uma banda punk toca três acordes para trinta pessoas. Os hippies\nde 1967 ainda vendem incenso na esquina da Clay, mais velhos e mais desconfiados. Os motoqueiros\nestacionam as Harleys em fila na frente do Iron Coffin. Ninguém dorme antes das seis.\nSaint Edwiges sempre foi o bairro do prazer: em 1934 eram o jazz, as apostas e o rum; em 1994 são a rave,\no crack e o barulho. A diferença é a velocidade. Em 1934 um homem perdia a fortuna em um ano; em\n1994 perde em uma noite, e chega em casa sem lembrar de nada.\nL E I A E M V O Z A L T A\nA Pacific à uma da manhã é um corredor de néon rosa, verde e azul, tão forte que tinge a pele de quem passa. De\numa porta sai uma batida de discoteca; da porta ao lado, uma guitarra distorcida; da esquina, o grito de uma\ngarota de cabelo moicano que discute com um motoqueiro de barba. Um homem de terno branco, na porta da\nSavoy, conta notas de cem com o polegar molhado. No chão da calçada, alguém escreveu com tinta spray: \"A\nCIDADE É DE QUEM NÃO DORME\".\nPlanta da Discoteca Savoy\nQuem manda. Os Moretti são donos dos imóveis e cobram aluguel de todos. A cocaína vem de La\nPatrona. A Bratva quer as duas coisas e já vende o pó batizado por intermédio de Sonny Moretti.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nDiscoteca Savoy O antigo Clube Savoy, com globo espelhado e\npista iluminada\nQuem cheira no camarote VIP e com quem\nThe Iron Coffin · Bar de heavy metal, motoqueiros e briga às sextas Armas, motoqueiros de aluguel, quem quer\nsumir\nPorão 77 · Clube punk sem placa, na antiga adega do Farol\nAzul\nFanzines, boatos de rua, garotos que viram\ntudo\nPeep Palace · Cabines de vinte e cinco centavos e um escritório\nnos fundos\nFotografias de gente importante\nBarbearia Fratelli A mesma de 1946, agora com néon na fachada · A cadeira onde Sal Moretti morreu e o filho\ndo barbeiro\nComuna da Rua\nClay\nCasarão ocupado por hippies desde 1967 · Abrigo, remédios, gente que não pergunta\nnada\nVinnie Ascoli\nGERENTE DA SAVOY, 40 ANOS\nTerno branco, corrente de ouro, bronzeado de lâmpada. Cobra o aluguel da Strip para o Tio Sam e\nrepassa a cocaína de La Patrona e, desde setembro, a da Bratva.\nVIRTUDE\nFecha a Savoy às sextas de Natal para uma festa beneficente\npara órfãos.\nPECADO\nSabia que o pó de setembro estava batizado e vendeu\nassim mesmo.\nQUER\nPagar o Tio Sam e o cartel ao mesmo tempo, sem que um\nsaiba do outro.\nTEME\nQue Spider descubra o que ele sabia.\nAlianças: Tio Sam (braço), La Patrona (fornecedora), Sonny Moretti (sócio secreto).\nSpider\nBAIXISTA PUNK, 19 ANOS\nCabelo espetado com sabão, coturno, jaqueta com o nome da banda pintado à mão nas costas. Vive no\nPorão 77 desde que a irmã morreu.\nVIRTUDE\nLeva comida para os mendigos da Clay toda madrugada.\nPECADO\nJá roubou dois carros para pagar o aluguel do porão.\nQUER\nVingar a irmã, morta por overdose de pó batizado.\nTEME\nVirar o que ele odeia.\nAlianças: Dee Dee Morrow, Mama Flor.\nMama Flor\nDONA DA COMUNA DA RUA CLAY, 62 ANOS\nHippie de 1967, cabelo branco até a cintura, saia indiana e mente afiada. A comuna dela abriga fugitivos,\ndoentes e testemunhas.\nVIRTUDE\nEscondeu duzentas pessoas da polícia em\ndezessete anos.\nPECADO\nEsconde, agora, uma testemunha do roubo da Montgomery, e cobra\npor isso.\nQUER\nQue os tratores não cheguem à Rua Clay.\nTEME\nA Petrolífera, que quer a quadra para um centro comercial.\nAlianças: Spider, padre Tom Quinn, Cordelia Harrow (doadora).\n1 d 6 R u m o r · V e r d a d e ?\n1 · O pó da Savoy estava batizado com veneno de rato · Verdade: um lote da Bratva, para queimar o\ncartel\n2 · Uma banda do Porão 77 vai assinar com uma gravadora · Falso\n3 · O Peep Palace tem um vereador fotografado em cada cabine Meia verdade: são três\n4 · Enzo Fratelli Jr. sabe quem matou Sal Moretti · Verdade\n5 · A comuna esconde uma testemunha do roubo da\nMontgomery\nVerdade\n6 · A Strip vai virar centro comercial da Petrolífera · Verdade: o projeto já está na Prefeitura\nGanchos. Spider contrata os protagonistas com uma caixa de sapato cheia de moedas para achar quem\nbatizou o pó que matou a irmã. Vinnie Ascoli aparece pendurado na pista da Savoy na hora da abertura,\ncom o globo espelhado girando.","Chinatown":"CHINATOWN\nEm 1973 a fila deste cinema dobrava a esquina da Washington. Eu tinha 23 anos e\nvendia ingresso. Passava o mesmo filme quatro vezes por dia, um homem sem\ncamisa que derrubava trinta de uma vez, e os garotos brancos de White Hills saíam\nda sessão das seis chutando o ar e pedindo para aprender. Minha avó olhou para\naquela fila e disse: tira as poltronas.\nTiramos as poltronas. Pusemos o tablado. Cobramos em dólar de quem queria ser\no homem do filme, e com o dinheiro pagamos o que a polícia cobrava para não\nfechar a casa dos fundos. A avó dizia que Chinatown sempre teve duas portas, e\nque o segredo é nunca deixar que os de uma porta vejam os da outra.\nAgora os 14 Dragões querem só a porta dos fundos. Chegaram de Hong Kong com\nsapato italiano e acham que o kung fu é coisa de cinema. O Tony Kwan nunca\nvarreu um tablado. Ele não sabe que as tábuas daqui foram serradas das poltronas,\ne que embaixo de cada uma tem um número de assento. Eu sei qual é a fileira H.\nSei que a H dá para o túnel.\nA Madame Su me pediu ajuda ontem. Uma moça dela saiu com um homem de\nterno da Petrolífera e não voltou. Eu disse que ia ver. Disse isso como a avó dizia,\ndevagar, olhando a pessoa nos olhos, para ela entender que eu vou ver de verdade.\nTem alguém na porta. Não é aluno, aluno não bate três vezes.\nEntra. Tira o sapato, que o tablado é limpo.\n— L i n J a d e , A c a d e m i a G a r r a d e J a d e\n“\n“As tábuas deste tablado foram poltronas de cinema. Embaixo da fileira H ainda tem um túnel.”\n— L i n J a d e , A c a d e m i a G a r r a d e J a d e\nChinatown cresceu mais que qualquer bairro em dez anos, e cresceu por duas portas. A da frente é a\nacademia de kung fu, com alunos de todas as cores pagando para aprender o que viram no cinema. A dos\nfundos é a casa de massagem, o bordel e a mesa de mahjong, que pagam o aluguel da academia. As duas\nportas dão para o mesmo corredor e para os mesmos túneis de 1906, ampliados em 1934 e de novo em\n1962.\nNas ruas Grant e Stockton, as lanternas de papel vermelho ainda balançam sobre as bancas de pato\nlaqueado, ervas e fogos de artifício. O Cine Golden Harvest passa filmes de Hong Kong sem legenda às\nduas da manhã. E desde 1992 há uma guerra silenciosa: o Lótus Vermelho, herdeiro da velha tong de Lin\nMei-Hua, contra os 14 Dragões, uma gangue recém-chegada de Hong Kong que compra armas dos russos\ne dos Moretti ao mesmo tempo.\nL E I A E M V O Z A L T A\nA Rua Grant, às onze da noite, é um túnel de lanternas vermelhas e letreiros em caracteres que piscam em verde.\nCheira a gengibre, fritura e incenso. De uma porta aberta vem o ruído seco de corpos batendo num tablado e uma\nvoz de mulher contando em cantonês. Na porta ao lado, de cortina de contas, uma moça de vestido de seda fuma\nencostada no batente e conta os homens que entram. Um garoto de bicicleta passa gritando os títulos do Cine\nGolden Harvest: \"O Dragão Branco! O Templo de Shaolin! Sessão dupla!\"\nQuem manda. O Lótus Vermelho de Lin Jade, que protege as academias e cobra das casas. Os 14 Dragões\nquerem as casas sem as academias. O Tio Sam arma os Dragões para enfraquecer o Lótus.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nAcademia Garra de\nJade\nA academia de Lin Jade, no antigo Teatro\nMandarim\nLutadores de aluguel, desafios, a fileira H que\ndá para o túnel\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nCasa de Chá do\nDragão Jade\nReaberta em 1979, com vidros à prova de bala Acordos entre gangues; as portas para os túneis\nCasa das Mil\nLanternas\nO maior bordel da Rua Grant, com fachada de\ncasa de banhos\nClientes de White Hills e da Prefeitura, e o que\ndizem na cama\nCine Golden Harvest Cinema de Hong Kong, sessão das duas da\nmanhã\nEncontros no escuro; filmes como senha\nPátio do Poço Velho · O mesmo pátio de 1934, agora cheio de\nbancas\nNotícias de rua, o mercado de armas aos\nsábados\nTúneis de Chinatown A rede de 1906, ampliada · Saídas para o porto e para o píer da barca;\nesconderijos\nPlanta da Academia Garra de Jade\nLin Jade\nMESTRA DE ACADEMIA E CHEFE DO LÓTUS VERMELHO, 44 ANOS\nNeta de Lin Mei-Hua, vendia ingresso no Teatro Mandarim em 1973 e o transformou em academia. Fala\npouco, varre o tablado sozinha toda noite e nunca perdeu uma luta, salvo uma, em 1979, para uma mulher\nchamada Ruby Halloran.\nVIRTUDE\nPaga o hospital de toda moça das casas que adoece.\nPECADO\nCobra das casas o que a polícia cobraria, e um pouco mais.\nQUER\nExpulsar os 14 Dragões sem deixar a polícia entrar.\nTEME\nQue os de uma porta vejam os da outra.\nAlianças: Madame Su, Kenji Hale. Respeita Ruby Halloran. Inimiga de Tony Kwan.\nTony Kwan, \"Dragão Branco\"\nCHEFE DOS 14 DRAGÕES, 29 ANOS\nChegou de Hong Kong em 1992, fugindo da devolução da colônia à China em 1997, terno italiano,\nmocassim sem meia, um sorriso de propaganda de cigarro. Compra armas dos russos e recebe outras dos\nMoretti, de graça.\nVIRTUDE\nMantém um templo pequeno para a mãe, que ficou em Hong\nKong.\nPECADO\nComprou a luta de Kenji Hale em agosto e guarda o\nrecibo.\nQUER\nAs casas, o porto e a cabeça de Lin Jade.\nTEME\nQue o Tio Sam pare de mandar armas.\nAlianças: Tio Sam (braço), Bratva (fornecedora).\nMadame Su\nDONA DA CASA DAS MIL LANTERNAS, 55 ANOS\nTrabalhou na Rua Grant desde os dezesseis anos e hoje é dona da maior casa do bairro. Guarda um\ncaderno com o nome de cada cliente desde 1964.\nVIRTUDE\nNunca aceitou menores em casa, nem quando pagavam o\ntriplo.\nPECADO\nVende nomes do caderno para a Imprensa quando\nprecisa.\nQUER\nQue as moças saiam vivas da guerra; achar a moça que\nsumiu.\nTEME\nQue alguém leia o caderno inteiro.\nAlianças: Lin Jade. Talvez a Viúva, que já passou por aqui, segundo os boatos.\n1 d 6 R u m o r · V e r d a d e ?\n1 · Lancelot, da Távola, frequenta a Casa das Mil Lanternas Verdade\n2 · Lin Jade nunca perdeu uma luta · Falso: perdeu uma, para Ruby Halloran, em 1989\n3 · Os 14 Dragões trabalham para os russos · Meia verdade: compram armas deles e dos Moretti\n4 · Há um túnel que chega à Monumental Island · Falso: chega ao píer da barca\n5 · A Petrolífera quer derrubar a Rua Grant inteira · Verdade\n6 · A Viúva trabalhou numa casa da Rua Grant · O Diretor decide\nGanchos. Lin Jade desafia um dos protagonistas para uma luta na academia: se ele perder, trabalha para o\nLótus por uma semana. Madame Su pede que achem uma de suas moças, que sumiu depois de atender\num homem de terno da Petrolífera.","Embarcadouro":"EMBARCADOURO\nTua vez, Pasha. Não, o cavalo não. Pensa.\nSabe a primeira coisa que eu fiz quando cheguei aqui, em 1980? Fui ao\nsupermercado. Fiquei uma hora no corredor dos cereais. Quarenta caixas\ndiferentes, todas com um desenho de bicho sorrindo. Em Odessa eu fiquei seis\nhoras numa fila por um pão, em 1963, e ninguém sorria, nem o pão. Aqui o pão é\ntão macio que dá para dobrar no meio. Eu achei aquilo obsceno. Depois achei\nbonito. Depois entendi que é a mesma coisa.\nEm dezembro de 1991 a minha bandeira acabou numa quarta-feira à noite, na\ntelevisão, entre um comercial de refrigerante e o jogo de basquete. Eu fiquei\nsentado olhando. Dezoito anos servi, antes de vir para cá, um país que deixou de\nexistir no intervalo. No mês seguinte começaram a chegar os rapazes da segunda\nleva: ex-paraquedistas, ex-KGB, um coronel que vendeu um helicóptero inteiro\nem Vladivostok e não sabe dizer para quem. Trazem malas que eu não abro.\nDormem nos contêineres do Píer 30 e me chamam de tio.\nO velho italiano acha que eu quero o porto. Eu já tenho o porto. Os irlandeses\nforam embora, os guindastes trabalham sozinhos, e quem fala com o guindaste sou\neu. O que eu quero é o que vem depois do porto: a Strip, o cassino, o vereador\nque assina.\nViu? Você moveu o cavalo. Eu disse para não mover o cavalo. Agora a tua rainha\nestá sozinha, e você não percebeu porque estava ouvindo a minha história.\nXeque. Vai buscar o Bogdan, e diz para ele trazer o carro grande.\n—Yu r i V o l k o v , G a l p ã o 1 4\n“\n“No Píer 30 se joga xadrez com contêineres. O tabuleiro de madeira é só para treinar.”\n— Y u r i V o l k o v, G a l p ã o 1 4\nQuando os guindastes automáticos chegaram, em 1971, os estivadores foram embora e os galpões ficaram\nvazios. Os russos chegaram em 1980 e ocuparam cada um deles. Hoje o Embarcadouro fala russo depois\nda meia-noite: contêineres que chegam sem nota, saunas onde se fecham negócios sem roupa e sem\nescuta, um restaurante georgiano de toalhas brancas que nunca está cheio e sempre lucra. Os poucos\nirlandeses que ficaram atravessam a rua quando passam.\nO Píer 9, onde em 1934 se fazia o shape-up das seis da manhã, está abandonado; o portão enferruja e as\ngaivotas são as únicas que fazem fila. O terminal do Píer 30 trabalha dia e noite, iluminado como um\nestádio. Entre um e outro, galpões de tijolo com janelas pintadas de preto, carros pretos parados com o\nmotor ligado e homens de casaco de couro que fumam cigarros sem filtro.\nL E I A E M V O Z A L T A\nO vento do porto traz cheiro de óleo diesel, peixe e água parada. Os guindastes do Píer 30 se movem sozinhos no\nalto, lentos como animais pré-históricos, empilhando contêineres coloridos debaixo de holofotes brancos. Mais\nperto, na frente de um galpão de janelas pintadas, dois homens de casaco de couro discutem em russo ao lado de um\nMercedes preto. Um deles para de falar e olha diretamente para vocês. Depois volta a falar, mais baixo.\nQuem manda. A Bratva de Odessa, de Yuri Volkov. O terminal é da Autoridade Portuária no papel e dos\nrussos na prática. Metade da Narcóticos de Brannigan está na folha de Volkov.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nTerminal do Píer 30 · Guindastes automáticos, mil contêineres\nempilhados\nO que chegou sem nota e para quem\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nGalpão 14 · O mesmo galpão de 1934, agora quartel da\nBratva\nArmas, heroína, o escritório e o tabuleiro\nde Volkov\nSauna Odessa · Banhos russos onde se negocia sem roupa\ne sem escuta\nAcordos, ameaças, quem está devendo\nRestaurante Tbilisi · Georgiano, toalhas brancas, ninguém\ncome\nA lavanderia de dinheiro da Bratva\nPíer 9 · Abandonado desde 1971 · Encontros discretos, corpos na água, um\nvelho escondido\nIgreja Ortodoxa da Pequena\nVarsóvia\nA mesma do porão do dominó em 1934 · Refugiados, documentos falsos, o padre\nAleksei\nPlanta do Galpão 14\nYuri Volkov\nCHEFE DA BRATVA DE ODESSA, 52 ANOS\nEx-oficial da marinha soviética, ombros de estivador, óculos de leitura pendurados no pescoço. Joga\nxadrez com os capangas antes de mandar matá-los. Vende informação à KGB e à CIA, e a nenhuma das\nduas o suficiente.\nVIRTUDE\nPaga o aluguel de quarenta famílias de\nrefugiados.\nPECADO\nVende heroína e armas; mandou batizar o pó da Strip para queimar o\ncartel.\nQUER\nO porto inteiro e a Strip, antes dos Moretti.\nTEME\nA filha; ser mandado de volta.\nAlianças: Metade da Narcóticos, Sonny Moretti (em segredo), os 14 Dragões (clientes). Inimigo do Tio Sam.\nIrina Volkova\nFILHA DE YURI, CONTADORA, 28 ANOS\nFormada em Leningrado, cabelo loiro de farmácia, dente de ouro do lado esquerdo. Faz os livros da\nBratva e decidiu, em outubro, que não quer mais.\nVIRTUDE\nDesviou dinheiro do pai para as famílias da igreja.\nPECADO\nCopiou os livros contábeis para vender a quem a tirar da cidade.\nQUER\nSair de Saint Village viva, com os livros.\nTEME\nQue o pai a encontre antes do Natal.\nAlianças: Frankie Vega (sem saber que é protagonista). Padre Aleksei.\nBogdan, \"o Urso\"\nMATADOR DA BRATVA, 40 ANOS\nDois metros, mãos de pá, uma tatuagem de igreja ortodoxa nas costas, uma cúpula para cada morte. Tem\ncatorze cúpulas.\nVIRTUDE\nNunca matou mulher, nem quando mandaram.\nPECADO\nCatorze mortes.\nQUER\nCumprir ordens e voltar para casa um dia.\nTEME\nQue o mandem matar Irina.\nAlianças: Yuri Volkov, até a ordem errada.\n1 d 6 R u m o r · V e r d a d e ?\n1 · Volkov ainda trabalha para a KGB · Meia verdade: vende informação aos dois lados\n2 · Há uma ogiva nuclear num contêiner do Píer 30 · Falso: é um gerador velho com símbolo de radiação\n3 · A Bratva comprou a Narcóticos de Brannigan · Verdade: metade dela\n4 · Irina Volkova quer fugir · Verdade\n5 · Os russos querem a maleta do roubo da Montgomery · Verdade: acham que tem algo além do diamante\n6 · Um estivador irlandês ainda mora escondido no Píer 9 · Verdade: o velho Fintan Molloy, 70 anos\nGanchos. Irina Volkova procura os protagonistas para tirá-la da cidade com os livros contábeis do pai e\noferece metade do que eles provam. Um contêiner aberto no Píer 30 tem doze pessoas dentro, e só uma\nainda respira.","Distrito de Waterford":"DISTRITO DE WATERFORD\nDuas, Danny? Duas. E uma para o teu irmão, que ele vai chegar reclamando do\ncapataz.\nO velho Byrne fundou o sindicato neste balcão, e quem servia a cerveja era a\nminha avó, Biddy Riordan. A minha mãe era uma Moretti que fugiu de casa para\ncasar com um irlandês de punho fechado, e o meu pai era esse irlandês. Eu cresci\ncom um pé em cada lado da Montgomery, e aprendi cedo que os dois lados te\nbatem igual.\nEm 1971, quando os guindastes começaram a trabalhar sozinhos, metade da rua foi\nembora numa semana. Bakersfield, Sacramento, Oregon. Os que tinham algum\ndinheiro compraram casa em White Hills e mudaram o sobrenome de pronúncia.\nOs que não tinham foram atrás de colheita. Ficaram os velhos, os teimosos e eu,\nque herdei um pub e uma dívida com o meu tio.\nAgora a rua é de operário da refinaria. Mexicano, irlandês, polaco, vietnamita, todo\nmundo com o mesmo macacão e a mesma tosse. Bebem aqui depois do turno, vão\nao drive-in no sábado, apostam no boliche no domingo. É uma vida, e a\nPetrolífera quer passar um trator por cima dela para pôr um tanque.\nO Tio Sam me ligou ontem. Disse que se eu mantiver o bairro calmo ele segura o\npreço do terreno. Ele chama isso de família. Eu chamo de leilão.\nOlha a casa 114, ali da janela. A da varanda azul. Pintaram de laranja hoje de manhã.\nO dono está sentado no canto, de boné, sem tocar no copo.\nDanny, chama o padre Quinn. E fecha a porta, que hoje o O'Rourke's vira reunião.\n— M i k e y R i o r d a n , O ' R o u r k e ' s\n“\n“Sábado é dia de drive-in. A refinaria fica acesa no fundo do filme, e ninguém cobra por ela.”\n— M i k e y R i o r d a n , O ’ R o u r k e ’ s\nO antigo gueto irlandês virou uma cidade operária à sombra da refinaria da Monarch. Três turnos por dia,\na sirene da troca às seis, às duas e às dez; pubs que abrem quando o turno da noite sai; um drive-in que\npassa dois filmes por noite para casais em carros envenenados; um boliche de doze pistas, uma igreja, um\nsindicato fraco. As casas de 1910 ainda estão de pé, de madeira pintada e varanda, e agora estão marcadas\ncom tinta laranja: a Petrolífera quer o terreno para os tanques.\nNa Calle del Horno, a rua dos latinos, as oficinas envenenam muscle cars e desmancham carros roubados;\nos Hijos del Horno vigiam as esquinas. Nos pubs da Rua Dolores, os irlandeses que ficaram cantam as\nmesmas músicas que os avós cantavam em 1934, só que mais baixo. E sobre tudo paira o cheiro de\nenxofre da refinaria, que entra pelas frestas e gruda nas cortinas.\nL E I A E M V O Z A L T A\nA sirene da refinaria uiva às dez em ponto, e a rua se enche de macacões cinzentos que saem pelo portão como uma\nmaré. As chaminés da Monarch soltam chamas laranja contra o céu nublado. Do outro lado da rua, a tela gigante\ndo drive-in mostra um homem de chapéu correndo de uma pedra enorme, sem som. Na varanda de uma casa de\nmadeira, alguém pintou um grande X laranja. Embaixo do X, com tinta branca, outra mão escreveu: \"AQUI\nMORA GENTE\".\nPlanta do O'Rourke's e do drive-in\nQuem manda. Ninguém. A Petrolífera paga os salários e decide quem fica. Mikey Riordan tenta organizar\nos moradores do balcão do O'Rourke's. Los Hijos del Horno controlam a Calle del Horno e as oficinas.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nRefinaria Monarch · Chaminés e tanques na margem do estreito, onde era\na Waterford S.A.\nQuem morreu em acidente e não foi\nregistrado\nO'Rourke's · O pub de 1934, agora de Mikey Riordan · O bairro inteiro, depois das dez\nDrive-in Estrela do\nEstreito\nTela gigante, duzentas vagas, lanchonete com milk-\nshake\nEncontros nos carros do fundo, rachas\nna saída\nBoliche Shamrock · Doze pistas, música alta, máquinas de pinball · Apostas, brigas, recrutas para\nqualquer serviço\nIgreja de São Brendan Ainda de pé; o padre esconde famílias despejadas · Abrigo, a ficha de cada\ndesapropriação\nCalle del Horno · Oficinas que envenenam muscle cars e desmancham\nroubados\nCarros, peças, os soldados de La\nPatrona\nMikey Riordan\nDONO DO O'ROURKE'S, 58 ANOS\nFilho de Tommy Riordan e Angela Moretti, neto de Biddy Riordan, sobrinho-neto do Tio Sam. Ombros\nlargos, nariz quebrado três vezes, voz de quem já foi presidente do Local 9. Um dos irlandeses que\nficaram.\nVIRTUDE\nDá cerveja fiado a quem perdeu o emprego.\nPECADO\nMantém o bairro calmo para o tio, em troca de uma dívida perdoada.\nQUER\nImpedir as demolições, de qualquer jeito.\nTEME\nTer de escolher entre o bairro e a família.\nAlianças: Padre Tom Quinn, La Patrona (acordo), Cordelia Harrow. Braço relutante do Tio Sam.\nMarisol Rosales, \"La Patrona\"\nCHEFE DOS HIJOS DEL HORNO, 44 ANOS\nCresceu na Calle del Horno, ficou viúva três vezes, todas por escolha. Comanda as oficinas, a cocaína da\nEstrada do Estreito e as esquinas do Distrito. Usa óculos escuros à noite.\nVIRTUDE\nPaga o enterro de cada morto do bairro, de qualquer lado.\nPECADO\nA cocaína que passa pela estrada mata gente na Strip.\nQUER\nA Calle intacta e a estrada só dela, longe dos russos.\nTEME\nQue a Bratva descubra a rota.\nAlianças: Mikey Riordan, Ana Ortiz (amiga de escola). Inimiga da Bratva.\nPadre Tom Quinn\nPÁROCO DE SÃO BRENDAN, 50 ANOS\nNeto de Patrick Quinn, o operário cujo laudo foi falsificado em 1934. Esconde famílias despejadas na\nsacristia e guarda uma pasta com cada documento de desapropriação.\nVIRTUDE\nNunca negou abrigo a ninguém.\nPECADO\nSabe quem incendiou o escritório da Petrolífera em outubro e não conta.\nQUER\nQue a refinaria pague pelos mortos.\nTEME\nQue a pasta seja roubada.\nAlianças: Mikey Riordan, Mama Flor, Cordelia Harrow.\n1 d 6 R u m o r · V e r d a d e ?\n1 · Os irlandeses do O'Rourke's assaltaram o carro-forte · Falso: é o que a Petrolífera quer que se pense\n2 · A refinaria despeja resíduo no estreito à noite · Verdade\n3 · Mikey Riordan é sobrinho-neto do Tio Sam · Verdade\n4 · O drive-in vai fechar no Natal · Meia verdade: a gerente já assinou, mas pode desistir\n5 · La Patrona e Mikey Riordan têm um acordo · Verdade: ela protege o bairro, ele não fala dela\n6 · A casa marcada número 1 é a de Cordelia Harrow · Falso: é a do padre Quinn\nGanchos. Na noite de uma desapropriação, os moradores bloqueiam a rua com carros e chamam os\nprotagonistas para segurar a linha até o amanhecer. Um operário morre na refinaria, e a viúva tem certeza\nde que não foi acidente.","Monumental Island":"MONUMENTAL ISLAND\nEu cantei no Ed Sullivan em 1966. Um vestido prateado, uma orquestra de\nquarenta músicos, a minha mãe chorando na plateia. Cantei uma música sobre um\nhomem que não voltou da guerra, e no dia seguinte vendeu duzentas mil cópias.\nDurou três anos. Depois a música mudou, os meninos de cabelo comprido\nchegaram, e eu descobri que uma cantora de trinta anos de vestido prateado é uma\ncoisa que as gravadoras guardam no porão, como móvel velho.\nAgora eu canto aqui. Seis noites por semana, no pátio onde os presos tomavam sol.\nOs políticos sentam nas mesas da frente e me pedem a mesma música de 1966,\nporque acham que é romântico. Não é. A música é sobre um homem morto.\nO quarto onde eu durmo era uma cela do Pavilhão Leste. Pintaram de rosa,\npuseram cortina e televisão. Às vezes eu acordo de madrugada e vejo, na parede,\num risco embaixo da tinta: alguém contava os dias ali. Eu também conto. Faltam\nquarenta e três para o réveillon.\nO Lou Cassidy tem umas fotos minhas de 1981, de uma noite que eu prefiro\nesquecer, com um homem que hoje é senador. Ele usa as fotos para eu cantar por\nmetade do cachê. Eu canto. Canto bem. Mas no Baile do Fim do Mundo, à meia-\nnoite, quando todas as câmeras do Canal 7 estiverem viradas para o palco, eu vou\ncantar uma música nova.\nNinguém aqui sabe que eu também escrevo.\n— G l o r i a V a n e , c a b a r é d a M o n u m e n t a l I s l a n d\n“\n“As grades são de 1934. O dourado é de 1982. O cadeado continua o mesmo.”\n— G u n n a r L i n d q v i s t, c h e f e d a s e g u r a n ç a d a i l h a\nA ilha que foi prisão virou uma pequena Las Vegas. O letreiro de néon gira sobre a velha torre do farol, a\nbarca sai do píer de Chinatown a cada vinte minutos, e o cassino ocupa o Bloco A, com as grades das celas\npintadas de dourado. Políticos de todo o estado vêm perder dinheiro que não é deles; prostitutas vêm de\nReno e de Los Angeles; o cabaré apresenta uma cantora que já foi famosa. Ninguém fala dos túneis.\nNa noite de 31 de dezembro de 1994, a Monumental Island dá o Baile do Fim do Mundo: fantasias de fim\nde milênio, coquetéis com nomes de terremoto, contagem regressiva com sirene de verdade. O Coração\ndo Lago, o diamante roubado do SS Excalibur em 1934, será exibido numa vitrine no centro do salão. Pelo\nmenos esse era o plano antes do roubo da Montgomery.\nL E I A E M V O Z A L T A\nA barca atraca no píer da ilha com um baque surdo. Diante de vocês, a velha prisão brilha como uma árvore de\nNatal: lâmpadas douradas contornam cada janela gradeada, holofotes cor-de-rosa sobem pelas paredes de\nconcreto, e no alto do farol um letreiro gigante gira devagar, MONUMENTAL ISLAND, em letras que mudam de\ncor. Do pátio vem uma orquestra tocando uma música de 1966. Um porteiro de luvas brancas estende a mão para o\nconvite. Atrás dele, presa na parede ao lado da porta, ainda está a placa de bronze de 1934: \"COMPLEXO\nPENAL DE BLACK ROCK\".\nQuem manda. No papel, um consórcio de investidores limpos. Na prática, os Moretti, que lavam ali o\ndinheiro do hipódromo. A Petrolífera quer entrar como sócia.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nCassino do Bloco A · Mesas de dados e roleta nas antigas celas · Quem perdeu o quê, e para quem deve agora\nCabaré do Pátio · O pátio de recreio virou palco com orquestra Quem senta com quem nas mesas da frente\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nHotel do Pavilhão\nLeste\nQuartos por hora no antigo pavilhão\npsiquiátrico\nCâmeras escondidas em cada quarto\nCofre da\nAdministração\nO cofre do antigo diretor da prisão · Fichas, dinheiro vivo e, no réveillon, o\ndiamante\nFarol · Restaurante giratório no topo · A melhor vista da baía e das lanchas\nchegando\nTúnel de 1853 · Abrigo antiaéreo desde 1962, depósito desde\n1982\nUma saída que ninguém vigia\nPlanta da Monumental Island\nLou Cassidy\nGERENTE DO CASSINO, 50 ANOS\nSorriso de crupiê, smoking de veludo, unhas feitas. Lava o dinheiro do Tio Sam e guarda as fotografias dos\nquartos num cofre dentro do cofre.\nVIRTUDE\nNunca deixou ninguém sair da ilha bêbado ao volante de\numa lancha.\nPECADO\nChantageia meio legislativo estadual.\nQUER\nAgradar ao Tio Sam e sobreviver ao réveillon.\nTEME\nQue as fotos saiam do cofre; que a Petrolífera vire sócia e\no demita.\nAlianças: Tio Sam (braço). Victoria Holt (compra fotos dele).\nGloria Vane\nCANTORA DO CABARÉ, 48 ANOS\nFoi famosa em 1966 e cantou no Ed Sullivan. Hoje canta seis noites por semana para políticos que pedem\na mesma música. Escreve canções que ninguém ouviu.\nVIRTUDE\nDá metade do cachê para as moças da ilha que querem ir embora.\nPECADO\nEsconde uma arma no estojo de maquiagem desde\n1981.\nQUER\nRecuperar as fotos e cantar a sua música nova à meia-noite do\nréveillon.\nTEME\nQue o senador a reconheça na primeira fila.\nAlianças: As moças da ilha. Odeia Lou Cassidy.\nGunnar Lindqvist\nCHEFE DA SEGURANÇA, 74 ANOS\nEx-guarda da prisão em 1963, neto do legista de 1934. Conhece cada cela, cada túnel e cada fechadura da\nilha. Ficou para trás na noite da transferência e nunca mais saiu.\nVIRTUDE\nSalvou um preso de um incêndio em 1961.\nPECADO\nGuarda o que a transferência de 1963 deixou no túnel, e vende pedaços.\nQUER\nQue ninguém abra o túnel.\nTEME\nQue descubram o que tem no túnel.\nAlianças: Lou Cassidy, por obrigação.\n1 d 6 R u m o r · V e r d a d e ?\n1 · Os dados da mesa 4 são viciados · Verdade\n2 · Há um preso de 1963 que nunca saiu da ilha · Meia verdade: é o chefe da segurança, que era\nguarda\n3 · O diamante será exibido no Baile do Fim do Mundo · Verdade\n4 · O Senador Pratt vai votar a lei da Petrolífera · Verdade, por causa do quarto 214\n5 · A ilha tem um abrigo para cem pessoas, só para\nconvidados\nVerdade: o túnel de 1853\n6 · A Monumental Island está falida · Falso: lava dinheiro demais para falir\nGanchos. Gloria Vane contrata os protagonistas para recuperar as fotos que o cassino usa para chantageá-\nla. O Senador Hollis Pratt é encontrado morto no quarto 214, e a câmera escondida foi arrancada da\nparede.","Estrada do Estreito":"ESTRADA DO ESTREITO\n11 de novembro. Turno das dez às seis. Catorze corridas, sessenta e um dólares,\ntrês gorjetas, uma delas em moeda canadense.\nO médico diz que eu devia dormir. Eu digo que durmo desde 1934, só que de\nolho aberto. Ele não ri. Médico novo não ri de nada.\nCorrida das onze: dois rapazes de cabelo espetado, da Montgomery até o Porão 77.\nDiscutiram o caminho inteiro se a música deles era política ou só barulho.\nDesceram sem pagar a última quadra. Deixei. Quem não paga a última quadra\nsempre volta para pagar a primeira.\nCorrida da uma: um homem de terno da Petrolífera, do Clube Pacífico até o\nGolden Gate Motel. Perguntou se eu conhecia a cidade. Disse que sim. Perguntou\ndesde quando. Disse que desde antes da ponte. Ele riu e me deu vinte. Não pediu\nrecibo. Quem vai ao Golden Gate de madrugada nunca pede recibo.\nCorrida das três: uma moça de chapéu, na chuva, da Rua Clay até a frente da\nDelegacia. Não disse uma palavra. Desceu, ficou parada olhando a porta, e quando\neu dei a partida vi que tinha deixado uma moeda no banco de trás. Coroa tcheca.\nGuardei com as outras.\nEm 1934 eu devia oitocentos dólares a Mae Calloway e achava que a cidade ia me\nengolir. A cidade não engoliu. Mastiga devagar, de boca aberta, para todo mundo\nver.\nLuz acesa no ponto. Um passageiro com uma maleta de alumínio, sangue no\npunho da camisa.\nLivre.\n— D i á r i o d e b o r d o d e E d d i e L u m , t á x i 2 1 4\n“\nA Lanchonete Moonlite de madrugada, Darlene servindo café a um homem que não come a torta\nA estrada que sai da cidade pela margem do estreito virou uma faixa de néon de oito quilômetros: motéis\ncom piscina vazia, um posto que nunca fecha, uma lanchonete de beira de estrada onde a garçonete sabe\no pedido de cada matador da Costa Oeste. Aos sábados, a reta entre o posto e a cabeceira da ponte vira\npista de racha, e os muscle cars do Waterford correm contra os esportivos de White Hills por dinheiro e\npor orgulho.\nÉ também a rota da cocaína de La Patrona, que vem do sul pela estrada para não cruzar o porto russo, e o\nlugar onde a Távola se encontra, no Golden Gate Motel, o mesmo de 1934, onde em 1990 os cavaleiros\ntraíram Guinevere.\nL E I A E M V O Z A L T A\nOs faróis cortam a neblina rasteira e, de repente, os letreiros aparecem um atrás do outro, como cartas de baralho\nsendo viradas: STARLITE MOTEL · VAGAS · TV COLORIDA. MOONLITE · TORTA DE CEREJA. TEXACO\n· ABERTO 24 HORAS. Por último, mais apagado que os outros, com o G piscando: GOLDEN GATE MOTEL. Na\nfrente da lanchonete, três carros envenenados roncam parados, faróis acesos, e um garoto de jaqueta de cetim\nconta notas em cima do capô de um Charger preto.\nA 2 6\nPlanta do Golden Gate Motel\nQuem manda. Ninguém, e por isso todo mundo usa. La Patrona passa a cocaína por ali. A Távola usa o\nGolden Gate Motel. Os tiras da Narcóticos passam uma vez por semana, para cobrar.\nL u g a r · O q u e é · O q u e s e d e s c o b r e a l i\nGolden Gate\nMotel\nO motel de 1934, com néon que pisca; o quarto\n11 nunca é alugado\nOnde Ruby Halloran foi traída em 1990; um cofre\nno piso do quarto 11\nLanchonete\nMoonlite\nCromo, vinil vermelho, jukebox, torta de cereja Quem passou, para onde ia, o que pediu\nPosto Texaco 24h Combustível, mapas, cigarros e um telefone\npúblico\nLigações que ninguém pode rastrear\nA Reta · Dois quilômetros de asfalto entre o posto e a\ncabeceira da ponte\nApostas, carros, quem tem coragem\nMotel Starlite · Quartos por hora com garagem fechada · Trocas de carga, de carro e de identidade\nFerro-velho\nMendoza\nCarros batidos empilhados em cinco andares · Peças, carros sem número, o carro-forte\ndesmontado\nDarlene\nGARÇONETE DA MOONLITE, 46 ANOS\nAvental cor-de-rosa, cabelo armado com laquê, um lápis atrás da orelha. Trabalha no turno da noite há\nvinte anos e sabe o pedido de cada matador da Costa Oeste.\nVIRTUDE\nNunca deixou ninguém morrer no turno dela; já escondeu três pessoas na\ncâmara fria.\nPECADO\nVende o que sabe para quem deixar a melhor\ngorjeta.\nQUER\nQue ninguém morra no turno dela.\nTEME\nQue a Távola volte a se reunir no Golden\nGate.\nAlianças: Kid Ruiz, Eddie Lum (cliente de quarenta anos).\n\"Kid\" Ruiz\nPILOTO DE RACHA, 22 ANOS\nJaqueta de cetim, cabelo com gel, um Dodge Charger preto de 1969 envenenado na Calle del Horno.\nInvicto na Reta.\nVIRTUDE\nDivide os prêmios com a mãe e as três irmãs.\nPECADO\nLeva cocaína de La Patrona no porta-malas, uma vez por mês.\nQUER\nCorrer fora daqui, numa pista de verdade.\nTEME\nPerder o carro.\nAlianças: La Patrona, Darlene. Rival de Sonny Moretti.\nOtis Mendoza\nDONO DO FERRO-VELHO, 60 ANOS\nSobrinho-neto do Dr. Elias Mendoza, o legista de 1934. Compra tudo o que chega sem pergunta e\ndesmancha em uma noite.\nVIRTUDE\nGuarda o arquivo do tio-avô, com os laudos verdadeiros\nde 1934.\nPECADO\nDesmontou o carro-forte da Montgomery na mesma tarde\ndo roubo.\nQUER\nAposentar-se rico e em silêncio.\nTEME\nQue alguém ache a placa do carro-forte que ele ainda não\nderreteu.\nAlianças: Quem pagar.\n1 d 6 R u m o r · V e r d a d e ?\n1 · O quarto 11 do Golden Gate é assombrado · Falso: tem um cofre no piso\n2 · Kid Ruiz vai correr contra Sonny Moretti por um carro · Verdade\n3 · Darlene viu Ruby Halloran pedir café na semana passada · Verdade\n4 · A Petrolífera vai construir um oleoduto ao longo da estrada Verdade\n5 · O ferro-velho tem um carro-forte desmontado · Verdade: o da Montgomery\n6 · A polícia nunca vem até aqui · Meia verdade: vem cobrar, uma vez por semana\nGanchos. Kid Ruiz pede aos protagonistas que corram com ele contra Sonny Moretti, com um carro\ncomo prêmio e a família Moretti apostando contra. Darlene telefona de madrugada dizendo que três\nhomens de terno estão perguntando por um dos protagonistas.\nA CIDADE QUE CRESCEU DEPRESSA\nDEMAIS\nC A P Í T U L O S E T E\nSaint Village tinha cento e oitenta mil habitantes em 1934. Tem novecentos e quarenta mil em 1994,\nsegundo o censo, e mais uns cem mil que o censo não conta: os que dormem debaixo da Trincheira, os\nque vieram de Odessa num contêiner, os que trabalham no turno da noite da refinaria com o documento\nde outra pessoa. A cidade quintuplicou em sessenta anos, e ninguém planejou nada disso. Ela cresceu\ncomo cresce um dente torto, empurrando os outros para o lado.\nO Diretor que conhece o livro de 1934 vai reconhecer as ruas. A Montgomery ainda corta Downtown em\ndiagonal, a Pacific ainda desce até o porto, a Praça do Fórum ainda tem a estátua do fundador com a mão\nestendida para o mar. Mas tudo está mais alto, mais sujo, mais barulhento e mais rápido. Este capítulo\nconta o que aconteceu entre um livro e outro, e por que, em 1994, a cidade é a personagem principal de\nqualquer caso. Os protagonistas passam. Os chefes envelhecem e morrem. Saint Village continua, e cobra\nde todo mundo.\nEu dirigi o bonde da linha 4 de 1931 até o dia em que arrancaram os trilhos, em\n1956. Saía da Praça do Fórum, descia a Montgomery, virava na Pacific e ia até o fim\ndo Embarcadouro, onde o motorneiro da noite descia para tomar um café com\nrum no quiosque do português. Eu conhecia cada passageiro pelo sapato.\nEstivador de bota, secretária de salto baixo, os rapazes do Moretti com sapato\nbicolor que ninguém mais usava em Nova York e aqui ainda era chique.\nQuando tiraram os trilhos, disseram que era o progresso. A General Motors pagou\nmetade da obra e a cidade pagou a outra metade com um empréstimo que ainda\nnão acabou de pagar. No lugar do bonde vieram os ônibus, e depois dos ônibus\nvieram os carros, e depois dos carros veio o viaduto, que passava por cima do\nEmbarcadouro como um teto de concreto e tirou o sol da rua do português por\ntrinta anos. Em 1989 o viaduto caiu, e a rua do português viu o sol de novo, só que\no português já tinha morrido e o quiosque era um ponto de crack.\nEu tenho oitenta e três anos e moro no sétimo andar da Torre C de Monarch\nHeights, que tem elevador desde 1987, quando ele quebrou pela última vez. Desço\nas escadas toda manhã para comprar o jornal. Sete andares. Conto os degraus,\ncento e doze. No bonde também tinha cento e doze rebites na plataforma do\nmotorneiro. Eu contava quando a linha parava no sinal da Clay. Não sei por que\nlembro disso. Lembro de coisas que não servem para nada e esqueço o nome do\nmeu médico.\nDa minha janela eu vejo a chama da refinaria. Ela não apaga nunca, nem de dia. A\nminha neta diz que parece uma vela de aniversário. Eu digo que parece o fósforo\nque alguém acendeu em 1942 e esqueceu de soprar.\n— A u g u s t o Fe r r e i r a , m o t o r n e i r o a p o s e n t a d o d a l i n h a 4\n“\nO Q U E O B O N D E V I U\nEm 1934 a cidade cabia num passeio de bonde. Começava nas mansões de White Hills, descia pelo\ncomércio de Downtown, atravessava a Strip de Saint Edwiges e terminava no cheiro de peixe e piche do\nEmbarcadouro. A ilha de Black Rock era uma prisão, o Waterford era um bairro de estivadores irlandeses\ne Chinatown fechava as portas às nove da noite por ordem da polícia. A neblina chegava do Pacífico às\nquatro da tarde e cobria tudo até a manhã seguinte. Os mais velhos chamavam a neblina de \"o lençol\",\nporque ela escondia o que a cidade fazia de noite.\nA guerra mudou tudo em quatro anos. Em 1942 a Marinha transformou o Embarcadouro num estaleiro, e\no estaleiro precisava de trinta mil braços. Vieram trens inteiros de gente do Texas, de Oklahoma, do\nArkansas e da Louisiana, brancos pobres e negros que fugiam do Sul, e a cidade não tinha onde pôr\nninguém. Construíram barracas de madeira no terreno baldio ao sul do Waterford, prometeram que eram\nprovisórias e derrubaram a última em 1971, para levantar no lugar as torres de Monarch Heights. Quem\nnasceu nas barracas se casou nas barracas e criou os filhos lá. Os filhos foram os primeiros moradores das\ntorres, e os netos são os garotos que vendem pedra no pátio da Torre F.\nDepois da guerra vieram as fábricas. A Pacific Pride abriu a maior fábrica de enlatados da costa em 1948, a\nQuímica Halvorsen começou a fazer pesticida em 1952, a usina termoelétrica foi inaugurada em 1955 com\num discurso do governador, e a Monarch Petróleo, que comprou a velha Harrow Oil em 1979, ergueu a\nrefinaria em 1981 sobre o aterro do Waterford. Cada fábrica trouxe uma onda de gente, e cada onda de\ngente trouxe um bairro novo, construído às pressas, com rua de terra que só foi asfaltada dez anos depois.\nA neblina ainda vem do Pacífico às quatro da tarde. Só que agora ela encontra a fumaça das chaminés no\nmeio do caminho, e as duas se misturam num ar amarelado que fica parado sobre a cidade nos dias sem\nvento. Ao pôr do sol o céu de Saint Village fica laranja e púrpura, cor de ferida, e os turistas da\nMonumental Island tiram fotografias achando lindo. Os moradores sabem que é o enxofre.\nA P R E S S A\nSaint Village tem uma doença que os urbanistas da Universidade chamam de crescimento sem cidade. As\nfábricas chegaram antes das escolas, as torres antes dos hospitais, o viaduto antes do metrô que nunca\nveio. Em 1994 a cidade tem a maior refinaria do Norte da Califórnia e um único hospital público, o\nMunicipal, construído em 1931 para cento e oitenta mil pessoas. Tem três estações de televisão, sete\nemissoras de rádio e quatro bibliotecas. Tem doze mil policiais na folha de pagamento e dois mil de\nverdade nas ruas; o resto é burocracia, licença médica e gente que nunca existiu, cujos salários alguém\nrecebe.\nA pressa está em tudo. Nas casas do Waterford, construídas em 1910 para estivadores e divididas em\nquatro apartamentos em 1945, em oito em 1960, e que agora têm famílias inteiras dormindo em quartos\nsem janela. Nas obras abandonadas da Prefeitura, um esqueleto de concreto aqui, uma passarela que não\nleva a lugar nenhum ali. Nos viadutos de acesso à refinaria, que cortam bairros ao meio sem passarela\npara pedestre, e onde três crianças morreram atropeladas em 1993. Na própria Monumental Island, onde\na prisão de 1934 virou cassino em oito meses de obra, com as celas pintadas de dourado e os mesmos\ncadeados nas portas dos quartos.\nE a pressa está nas pessoas. Ninguém em Saint Village tem tempo. O operário da refinaria faz dois turnos\npara","Owenfield":"OWENFIELD\nA minha mãe dizia que a chama da refinaria era o olho de Deus. Eu tinha seis anos\ne acreditava. Olhava pela janela da cozinha e ela estava lá, laranja, piscando no alto\nda torre, e eu achava que Deus estava acordado vigiando a gente.\nAgora eu trabalho embaixo dela. Turno das duas às dez, unidade de craqueamento,\ncom uma máscara que não serve para nada e um detector de gás que apita o tempo\ntodo, então a gente desliga. A chama é o que eles queimam quando a pressão sobe\ndemais. Quando ela fica grande e amarela, alguma coisa deu errado. Quando fica\npequena e azul, alguma coisa deu errado de outro jeito.\nEm março a Halvorsen vazou cloro no arroio. Os peixes boiaram durante três dias,\nde barriga para cima, prateados, até o Rio Morto ficar parecendo uma rua coberta\nde moedas. A Prefeitura disse que não era nada. A Halvorsen deu uma cesta básica\npara cada família da Rua Doze. A minha filha tem tosse desde março. O médico do\nMunicipal diz que é alergia.\nEu ainda olho a chama da janela da cozinha. Agora sei que Deus não está lá. Está o\ncapataz Wilkins, olhando o mostrador da pressão e fumando um Winston.\n— R o s a D e l g a d o M e n d e s , o p e r a d o r a d a R e f i n a r i a M o n a r c h\n“\n“A minha mãe dizia que a chama era o olho de Deus. Hoje eu sei que é o capataz Wilkins.”\n— R o s a D e l g a d o M e n d e s , R e f i n a r i a M o n a r c h\nOwenfield ocupa a faixa de aterro entre o sul do Embarcadouro e o Distrito de Waterford, onde em 1934\nhavia charco, gaivotas e os depósitos de carvão do porto. Hoje é uma paisagem de cilindros de aço, torres\nde destilação, tubulações que correm por cima das ruas como trilhos de montanha-russa e chaminés de\ntijolo das fábricas antigas, quase todas apagadas. No centro, visível de qualquer lugar da cidade, fica a\ntorre de queima da Refinaria Monarch, com a chama que não apaga desde 1981. Os moradores marcam\ndistâncias por ela. \"Fica a três chamas daqui\" quer dizer longe.\nA rua principal é a Avenida Industrial, quatro pistas de asfalto rachado onde passam caminhões-tanque dia\ne noite e onde não há calçada. As ruas transversais têm números em vez de nomes, da Rua Um à Rua\nVinte e Dois, porque foram abertas pela Câmara de Comércio em 1949 com pressa de lotear. Nelas\nmoram as famílias que chegaram para trabalhar nas fábricas e nunca conseguiram sair: casas de madeira\nde um andar, pintadas de cores vivas que o ar ácido desbota em dois anos, com quintais de terra onde não\ncresce nada além de mato.\nA Pacific Pride Enlatados, fechada desde 1979, ainda ocupa três quarteirões com seu galpão de tijolo e as\nletras de ferro no telhado, onde falta o segundo P. Lá dentro, as esteiras de sardinha enferrujam no escuro,\ne nos fins de semana os galpões viram pista de rave para mil garotos que vêm de toda a cidade de carro.\nNinguém da polícia entra, porque o dono atual é uma empresa de fachada da Bratva que paga a\nNarcóticos para olhar para o outro lado.\nA Química Halvorsen ainda funciona, com metade dos funcionários de 1975, e fabrica pesticidas que são\nproibidos na Califórnia e vendidos para o México e as Filipinas. Ela despeja no Arroio San Ysidro, que em\n1934 era um riacho onde os meninos do Waterford pescavam e em 1994 é um canal de concreto chamado\npelos moradores de Rio Morto. O vazamento de cloro de março matou toneladas de peixes, e uma\nquímica da empresa, Eleanor Voss, guarda numa pasta os laudos que provam que não foi o primeiro.\nA Usina Termoelétrica Municipal, de 1955, queima óleo pesado e produz o zumbido que a cidade inteira\nouve quando falta luz. As três chaminés vermelhas e brancas são a primeira coisa que o viajante vê\nchegando pela Estrada do Estreito.\nE há os ferros-velhos, dezenas deles, encostados nos muros das fábricas, onde os garotos da Rua\nDezessete vendem cobre arrancado dos fios da iluminação pública. Um deles, o Ferro-Velho Kowalczyk, é\no único lugar da cidade onde se pode desaparecer com um carro inteiro em vinte minutos, prensado num\ncubo de metal do tamanho de uma geladeira.\nL e i a e m v o z a l t a\nO ar muda de gosto na Avenida Industrial. Primeiro vem o ovo podre do enxofre, depois um gosto de moeda na\nlíngua que não sai mesmo com a janela fechada. A chama da refinaria fica à esquerda, enorme, maior do que vocês\nlembravam, e ilumina por baixo as nuvens baixas, que ficam cor de laranja e de vinho. Um caminhão-tanque\npassa a meio metro do retrovisor e buzina sem motivo. Nas ruas numeradas, à direita, as casas de madeira têm as\nluzes acesas e as cortinas fechadas. Um menino de bicicleta, com um rolo de fio de cobre no guidão, para na esquina\nda Rua Dezessete e fica olhando o carro de vocês até ele virar.\nO que o Diretor faz com Owenfield. É o bairro dos segredos industriais e dos acidentes. Um caso que\npassa por aqui envolve o que a Petrolífera e a Halvorsen escondem: vazamentos, laudos falsificados,\noperários mortos e registrados como acidente de trânsito. É também onde a cidade se livra de coisas:\ncorpos no Rio Morto, carros no ferro-velho, provas na fornalha da usina. O perigo não é só bala. Uma\nexplosão numa tubulação, uma nuvem de gás que obriga a evacuar dez quarteirões, um caminhão-tanque\ndescontrolado na Avenida Industrial. Os protagonistas que passam muito tempo aqui começam a tossir.","Monarch Heights":"MONARCH HEIGHTS\nEu moro no décimo primeiro andar da Torre F desde 1972. Quando a gente se\nmudou, a Prefeitura deu uma festa no pátio com banda de música e um homem de\nterno cortou uma fita vermelha. O apartamento tinha cheiro de tinta nova,\nbanheiro dentro de casa e uma janela de onde eu via o mar inteiro. Eu tinha vindo\ndas barracas da guerra. Chorei no corredor.\nO elevador quebrou pela primeira vez em 1979 e pela última em 1986. Desde\nentão eu subo onze andares de escada com a sacola das compras. Tenho setenta e\num anos. Paro no quinto e no oitavo. No quinto mora a Dona Lupe, que vende\ntamales da porta do apartamento, e no oitavo os rapazes que vendem outra coisa.\nEles carregam a minha sacola. Me chamam de vovó. Um deles, o Junior, é neto da\nminha comadre e eu dei banho nele quando era bebê. Hoje ele tem uma pistola na\ncintura e um bipe que toca de cinco em cinco minutos.\nDepois do terremoto de 1989, a Torre F rachou do segundo ao nono andar. Dá\npara enfiar a mão na rachadura da escada. A Prefeitura mandou um engenheiro, ele\nolhou, escreveu \"interditada\" num papel e colou na porta. Ninguém saiu. Para\nonde a gente ia? O papel caiu com a chuva de dezembro.\nDa minha janela eu ainda vejo o mar. Mas agora entre mim e o mar tem a refinaria.\n— H a t t i e M a e J o h n s o n , To r r e F, a p a r t a m e n t o 1 1 0 7\n“\n“Onze andares de escada. Paro no quinto e no oitavo. O Junior carrega a sacola.”\n— H at t i e M a e J o h n s o n , T o r r e F, 1 1 0 7\nMonarch Heights são oito torres de concreto de catorze andares, batizadas com letras de A a H,\nconstruídas em 1971 pela Prefeitura com dinheiro federal no terreno das barracas da guerra, ao sul do\nWaterford. O projeto se chamava originalmente Conjunto Habitacional Harrow-Lyman, em homenagem\nao bisavô de Preston, que doou o terreno; a placa de bronze com o nome foi roubada em 1980 e vendida\ncomo sucata, e desde então o bairro é chamado pelo nome da empresa que mais emprega seus\nmoradores. Vivem aqui, oficialmente, nove mil pessoas. Os assistentes sociais acham que são quinze mil.\nAs torres foram desenhadas por um arquiteto de Chicago que nunca visitou Saint Village, a partir de um\nmodelo de Le Corbusier que já tinha fracassado em três outras cidades. Corredores compridos, abertos\npara o vento, sem portaria; elevadores que quebram sempre; pátios de cimento entre os prédios, com\nbancos que ninguém usa e uma quadra de basquete com as tabelas sem rede. À noite, as janelas acesas\nformam um tabuleiro irregular, porque metade das lâmpadas dos corredores está queimada e a outra\nmetade foi roubada.\nOs moradores fizeram das torres uma cidade. Cada andar tem sua economia: no quinto da Torre B, uma\nmulher corta cabelo na cozinha; no nono da Torre D, um rapaz conserta televisão e videocassete; no\ntérreo da Torre A, a igreja pentecostal Fogo de Pentecostes ocupa dois apartamentos derrubados em um,\ncom os cultos de sábado à noite que se ouvem até a refinaria. Os murais pintados nas paredes dos pátios\ncontam a história do bairro: as barracas, o estaleiro, os mortos do terremoto, o rosto de um garoto\nchamado Deshawn que a Narcóticos matou em 1992 e cuja morte começou os três dias de tumulto.\nA Torre F, rachada no terremoto, é o coração do tráfico. Os Hijos del Horno controlam o comércio de\ncrack do térreo ao sexto andar; acima do sexto vivem os moradores que não têm para onde ir. Na quadra\nde basquete, entre as onze da noite e as quatro da manhã, os olheiros dos Hijos assobiam quando uma\nviatura entra no pátio, e o assobio sobe de andar em andar como um sino.\nL e i a e m v o z a l t a\nA Torre F aparece no fim da rua como um paredão cinza com janelas, alta demais para o bairro, com uma\nrachadura que desce em zigue-zague do nono andar até o segundo. No pátio, uma mulher de roupão estende roupa\nnum varal amarrado entre dois postes; um grupo de garotos de moletom joga basquete numa tabela sem rede, e\nquando o carro de vocês para, um deles assobia. O assobio é respondido por outro, no terceiro andar, e por outro, no\nquinto. A bola para de quicar. Pela janela aberta do térreo, um rádio toca uma música gospel, e o cheiro de tamale\nse mistura ao de urina na escada.\nO que o Diretor faz com Monarch Heights. É o lugar onde a cidade empilhou quem não queria ver. Um\ncaso que chega aqui é um caso sobre gente comum: uma testemunha que mora no décimo andar e não\npode descer porque os Hijos estão no sexto, uma criança que viu alguma coisa da janela, uma avó que\nguarda uma arma do neto na caixa de costura. A polícia só entra em grupo de seis. A Imprensa só entra\nquando há morto. A Petrolífera quer demolir as torres e construir no terreno um terminal de combustível;\njá comprou os vereadores, falta esvaziar os prédios.","A Trincheira":"A TRINCHEIRA\nEu durmo debaixo do Pilar 47 desde 1990. É o melhor pilar da Trincheira, porque\nnão pinga quando chove e porque o concreto do teto caiu inclinado, fazendo uma\nespécie de quarto. Antes de mim dormia aqui um sujeito chamado Dutch, que\nmorreu de frio no inverno de 1989, uma semana depois do terremoto. Eu herdei o\ncolchão dele e a coleção de tampinhas de garrafa.\nEu estava no Golfo? Não. No Vietnã, de 1968 a 1970, primeiro de infantaria, depois\nna cozinha, porque não conseguia mais segurar a arma sem tremer. Voltei, casei,\ntrabalhei na Pacific Pride até ela fechar, me separei, bebi. Nesta ordem. Não é uma\nhistória original. Debaixo do viaduto tem uns quarenta como eu, e se você der um\ncafé para cada um, vai ouvir quarenta vezes a mesma história com nomes\ndiferentes.\nNo dia 17 de outubro de 1989, às cinco e quatro da tarde, eu estava em cima do\nviaduto, num ônibus, voltando do hospital dos veteranos. O ônibus balançou\ncomo um barco. Eu vi a pista da frente se dobrar no meio e descer. Vi um Buick\nvermelho escorregar pela laje como um brinquedo. Quarenta e dois mortos. O\nnosso ônibus parou a quatro metros do buraco. Desci a pé, pela escada de\nemergência, e nunca mais subi.\nA Prefeitura diz que vai derrubar o resto e construir um parque. Diz isso há cinco\nanos. Enquanto isso eu fico aqui embaixo, e o Buick vermelho fica lá em cima, de\nrodas para o céu, esperando o parque.\n— L e s t e r \" S a r g e n t o \" B o o n e , d e b a i x o d o P i l a r 4 7\n“\n“O Buick vermelho continua lá em cima, de rodas para o céu, esperando o parque da Prefeitura.”\n— L e s t e r “ S a r g e n t o ” B o o n e , P i l a r 4 7\nA Trincheira é o que ficou do Viaduto do Embarcadouro, a Freeway 480, construída entre 1959 e 1963 por\ncima da rua do porto e derrubada em parte pelo terremoto de 1989. Três quilômetros de laje elevada\nsobre pilares de concreto, dos quais oitocentos metros desabaram e o resto ficou de pé, rachado,\ninterditado e escorado com vigas de aço provisórias que estão lá há cinco anos. O trecho que caiu foi\nremovido; o trecho que ficou é uma ruína gigantesca no meio da cidade, uma montanha de concreto cinza\ncom vergalhões para fora como ossos, e por baixo dela floresceu um bairro que nenhum mapa da Câmara\nde Turismo mostra.\nDebaixo dos pilares, protegidos da chuva pela laje, vivem centenas de pessoas em barracas de lona, caixas\nde papelão e carros sem rodas. Há um mercado noturno que funciona das dez da noite às cinco da\nmanhã sob os pilares 20 a 35, onde se vende de tudo: peças de carro, rádios roubados, fitas piratas,\ncomida vietnamita em panelas de alumínio, armas embrulhadas em jornal, remédio de farmácia sem\nreceita. Há uma igreja debaixo do pilar 12, onde um pregador chamado Irmão Ezekiel anuncia todas as\nnoites a chegada do Grande Terremoto e a destruição de Saint Village, \"a Babilônia do Pacífico\". E há o\ndesmanche da Bratva, sob os pilares 50 a 58, onde carros roubados entram inteiros e saem em pedaços\nantes do amanhecer.\nA Trincheira é também a fronteira. De um lado fica o Embarcadouro, russo; do outro, Downtown e as\ntorres da Monarch. Por cima, interditada, a laje ainda carrega os carros esmagados de 1989 que ninguém\nremoveu, com a ferrugem escorrendo pelas bordas como lágrimas. Os garotos da Strip sobem por uma\nescada de emergência para pichar a beirada, e do alto da Trincheira se vê a cidade inteira: a chama da\nrefinaria, as luzes da Monumental Island, as torres de Monarch Heights, os prédios espelhados de\nDowntown. Muitos casais da cidade deram o primeiro beijo lá em cima. Alguns caíram.\nL e i a e m v o z a l t a\nDebaixo da laje é sempre noite. A luz entra pelas bordas em faixas cinzentas, e entre os pilares, numerados com\ntinta amarela, brilham fogueiras em tonéis de óleo. O cheiro é de fumaça, urina e carne assando num espeto\nimprovisado. No pilar 23, uma mulher vietnamita vende sopa em copos de isopor; no 24, um homem de casaco do\nexército expõe numa lona azul seis rádios, três pistolas e uma pilha de fitas VHS sem capa. Lá em cima, onde a laje\nacaba, um carro de 1989 continua pendurado pela metade, com as rodas viradas para o céu, exatamente como\nficou no dia em que a cidade tremeu. Ninguém olha para ele. Do pilar 12, uma voz rouca grita que o fim está\nchegando.\nO que o Diretor faz com a Trincheira. É o mercado negro de Saint Village, o lugar onde se compra o que\nnão se pode comprar em outro lugar e onde se esconde quem não pode ser encontrado. Testemunhas\nfugitivas vêm para cá. Os veteranos que moram sob os pilares sabem de tudo que acontece no porto e no\ncentro e vendem a informação por um maço de cigarros ou uma garrafa. A polícia faz batidas uma vez\npor mês, para a televisão, e prende sempre as mesmas pessoas. E há o perigo da própria ruína: uma\nréplica de terremoto pode derrubar mais um pedaço da laje em cima de quem estiver embaixo.","Greenspring Streets e a Galleria":"GREENSPRING STREETS E A\nGALLERIA\nA gente se mudou para Greenspring Streets em 1984, quando o Gary foi\npromovido na Monarch. A casa tinha três quartos, duas garagens, piscina e um\ngramado na frente que o Gary corta todo sábado às nove da manhã, igual aos\nvizinhos, igual a todo mundo da Rua Magnólia. Greenspring Streets tem quarenta\ne duas ruas com nome de flor, e todas fazem curva, e todas terminam num círculo.\nO folheto dizia que as ruas sem saída eram para a segurança das crianças. Hoje eu\nacho que eram para a gente não conseguir sair.\nEu não vou à cidade desde 1992, desde o tumulto. Vi tudo pela televisão. As\nchamas em Downtown, os rapazes quebrando as vitrines da Montgomery, a viatura\nvirada de cabeça para baixo. O Gary comprou uma pistola na semana seguinte e\nguarda na gaveta da mesinha de cabeceira, do lado da Bíblia. As crianças vão de\nônibus escolar para a escola, de carro para a Galleria e de avião para a Disney. Não\nconhecem a cidade. A minha filha mais velha tem dezesseis anos e nunca andou na\nMontgomery.\nÀs vezes, de noite, quando todo mundo dorme, eu saio no quintal e olho para o\nnorte. Daqui dá para ver a chama da refinaria, pequenininha, por cima dos\ntelhados. O Gary trabalha lá. O salário dele paga a piscina. E quando a chama fica\ngrande, eu volto para dentro e fecho a janela.\n— L i n d a P r e s c o t t , R u a M a g n ó l i a , G r e e n s p r i n g S t r e e t s\n“"},"geral":"baía funda. Em 1934 tinha seiscentos mil habitantes, uma ponte em construção e uma ilha-prisão. Em\n1994 tem oitocentos e quarenta mil, uma ponte que virou cartão-postal e uma ilha-cassino. Os bondes\nainda sobem as ladeiras de White Hills, a neblina ainda entra pela baía às seis da tarde, e a Montgomery\nainda é a rua onde o dinheiro muda de mão. O resto mudou de dono.\nEntre 1934 e 1994 a cidade trocou o rum pela cocaína, o jornal pela televisão e o cais de estivadores por\ngalpões cheios de russos. Os irlandeses que não enriqueceram foram embora. Os italianos ficaram com o\nhipódromo e, depois, com o resto. Uma petrolífera chegou prometendo progresso enquanto a televisão\nconta os dias para o Grande Terremoto.\nS E S S E N TA A N O S\nA n o O q u e a c o n t e c e u  · O q u e f i c o u pa r a 1 9 9 4\n1935 A greve geral para o porto por nove semanas. Byrne negocia o fim\ncom o prefeito\nA Irmandade vira o Sindicato dos\nEstivadores, Local 9\n1935 A Irmandade vende o Coração do Lago em segredo ao velho\nAshcroft para pagar o fundo de greve\nO diamante passa 49 anos no cofre do\nBanco Ashcroft\n1937 A Black Rock Bridge é inaugurada, com o Pilar 3 reforçado às\npressas depois que Hattie Brooks publica o diário de Pedro\nAlvarado\nO corpo nunca foi retirado do concreto\n1942 Os moradores nipo-americanos são levados para campos de\ninternamento; seus comércios são vendidos a preço de banana\nFortunas de White Hills começaram ali\n1946 Don Sal Moretti morre na cadeira da Barbearia Fratelli. O filho\ncaçula, Sam, leva três tiros na espinha. Vincent assume\nSam passou 33 anos esperando a vez dele\n1952 A Waterford reabre para fazer munição para a Coreia e fecha em\n1961\nO esqueleto da fábrica vira terreno da\nrefinaria\n1958 A Gazeta da Manhã abre o Canal 7  · O telejornal das onze decide quem é\nculpado\n1962 Crise dos mísseis. O túnel de 1853, sob Black Rock, e os porões do\nFórum viram abrigos antiaéreos\nAs placas amarelas de abrigo ainda estão\nnas paredes\n1963 A prisão de Black Rock fecha. Os presos saem em uma noite, de\nlancha\nA ilha fica vazia por 18 anos\n1966 Os Moretti compram o Hipódromo de San Ysidro  · O hipódromo vira o coração do poder\nitaliano\n1967 O verão do amor chega a Saint Edwiges  · A comuna da Rua Clay continua lá\n1969 Ativistas indígenas ocupam Black Rock por 19 meses  · Murais da ocupação ainda cobrem o Bloco\nA\n1971 O terminal de contêineres abre. Acaba o shape-up; os irlandeses\npobres vão embora\nSobram os pubs, os velhos e os poucos que\nenriqueceram\n1973 A febre do kung fu chega com os filmes de Hong Kong; academias e\nbordéis se multiplicam em Chinatown\nChinatown é o bairro que mais cresceu em\ndez anos\nA n o O q u e a c o n t e c e u  · O q u e f i c o u pa r a 1 9 9 4\n1977 Tiroteio entre gangues no Dragão Jade, durante o jantar: cinco\nmortos\nA casa de chá reabre em 1979 com vidros à\nprova de bala\n1979 Vincent Moretti morre. Sam, o Tio Sam, assume. A Harrow-Lyman\ncompra o Banco Ashcroft\nComeça o reinado mais cruel dos Moretti\n1980 Chegam os emigrados soviéticos, e com eles a Bratva de Odessa.  · O porto fala russo depois da meia-noite\n1981 A Monarch Petróleo ergue a refinaria na margem do estreito. A\nViúva deixa a primeira moeda\nO antigo gueto vira cidade operária\n1982 Black Rock reabre como Monumental Island  · Políticos e apostadores chegam de barco\ntoda noite\n1983 O Canal 7 exibe um filme sobre o dia seguinte à bomba. As sirenes\npassam a ser testadas toda primeira quarta-feira do mês\nAs placas de abrigo antiaéreo ainda estão\nnas paredes; os abrigos de quintal viraram\nadega\n1986 O crack chega ao Distrito de Waterford e à Calle del Horno, mais\nbarato que um maço de cigarros\nOs Hijos del Horno crescem dez vezes em\ntrês anos\n1989 O terremoto de 17 de outubro: quinze segundos derrubam o\nviaduto do Embarcadouro e racham o Pilar 3 da ponte\nA cidade espera o próximo, o Grande\nTerremoto, todos os dias\n1990 A Távola trai Guinevere no Golden Gate Motel e a deixa por morta\nno quarto 11\nRuby Halloran passa quatro anos em coma\n1991 A União Soviética acaba. Chega a segunda leva da Bratva: ex-\nmilitares, ex-KGB, armas sem dono\nO porto passa a vender fuzil como se\nvende banana\n1992 Quatro tiras da Narcóticos são filmados espancando um motorista\ne absolvidos. Três dias de tumulto em maio: Downtown e o\nWaterford pegam fogo\nA Delegacia é odiada; a Viúva vira lenda\n1992 Os 14 Dragões chegam de Hong Kong com o dinheiro das tríades\nque fogem da devolução de 1997\nGuerra silenciosa em Chinatown\n1993 O Canal 7 compra um helicóptero  · Toda perseguição da cidade vai ao ar ao\nvivo\n1994 Ano de eleição. A Petrolífera começa as desapropriações. Ruby\nHalloran acorda do coma\nA campanha começa em novembro\nO MA PA D A C I D A D E\nMapa de Saint Village em 1994\nN º L u g a r  · N º L u g a r  · N º L u g a r\n1 Mansão Harrow  · 11 Galpão 14 e Terminal do Píer\n30\n21 Igreja de São Brendan\n2 Clube Pacífico  · 12 Sauna Odessa  · 22 Hospital Municipal\n3 Hipódromo de San Ysidro  · 13 Refinaria Monarch  · 23 Usina Termoelétrica\nMunicipal\n4 Torre Monarch  · 14 O'Rourke's  · 24 Química Halvorsen\n5 Prefeitura e Delegacia Central  · 15 Drive-in Estrela do Estreito 25 Pacific Pride Enlatados\n6 Cine Montgomery  · 16 Monumental Island  · 26 Torre F de Monarch Heights\n7 Canal 7 e Zachary Video, na Praça do\nFórum\n17 Píer da barca  · 27 Mercado noturno da\nTrincheira\n8 Discoteca Savoy e a Strip  · 18 Golden Gate Motel  · 28 Saint Village Galleria\n9 Academia Garra de Jade  · 19 Lanchonete Moonlite  · 29 Peep Palace\n10 Casa das Mil Lanternas  · 20 Palermo 24h  · 30 Porão 77\nA S FA C Ç Õ E S\nOito facções disputam a cidade, e o Tio Sam tem um braço dentro de quase todas. Cada facção tem um\nrelógio de seis segmentos. Ao fim de cada caso, o Diretor avança um segmento de cada facção que os\nprotagonistas não atrapalharam. Com o relógio cheio, a facção faz o seu movimento final e a cidade\nmuda. A reputação dos protagonistas com cada facção vai de −3 a +3 e muda as Dificuldades sociais no\nterritório dela: −1 por ponto positivo, +1 por ponto negativo.\nF a c ç ã o  · C h e f e  · Q u e r e m 1 9 9 4  · R e l ó g i o c h e i o\nFamília Moretti Samuele \"Tio\nSam\" Moretti, 84\nFechar o cerco: tirar os russos do porto, pôr\na Petrolífera de joelhos e descobrir quem\nmandou atirar nele em 1946\nGuerra aberta com a Bratva:\ntiroteios diários no\nEmbarcadouro e na Strip\nBratva de Odessa Yuri Volkov, 52  · O porto inteiro e a Strip  · Volkov compra a Delegacia, e a\ncidade paga pedágio em rublos\nA Petrolífera\n(Monarch\nPetróleo)\nPreston Harrow-\nLyman, 45\nDesapropriar o Waterford e a orla de\nChinatown para um terminal de petroleiros\nTratores derrubam quarteirões\ncom os moradores dentro\nLótus Vermelho Lin Jade, 44  · Expulsar os 14 Dragões e proteger as\nacademias\nChinatown fecha as portas para a\npolícia e para o resto da cidade\nLos Hijos del\nHorno\nMarisol Rosales,\n\"La Patrona\", 44\nA cocaína da Estrada do Estreito, longe dos\nrussos\nToque de recolher no Distrito,\nimposto pela gangue\nDelegacia\nCentral\nCapitão Ray\nBrannigan, 51\nUma parte de cada apreensão e uma\naposentadoria rica\nPrende os protagonistas com\nprovas plantadas\nA Imprensa  · Victoria Holt, 56 Vender a notícia que cada facção paga e o\nsilêncio que cada uma esconde\nUma notícia fabricada faz dos\nprotagonistas os procurados da\ncidade\nA Távola  · \"O Rei\"  · Recuperar o diamante para um cliente que\npagou adiantado\nOs assassinos começam a apagar\ntestemunhas, uma por noite\nA Távola é um grupo de cinco matadores de aluguel que usam os nomes dos cavaleiros: Lancelot, Gawain,\nTristão, Percival e Mordred. Respondem a um homem que ninguém viu e que assina \"O Rei\". Em 1990\neram seis. A sexta, Guinevere, foi traída por eles no Golden Gate Motel e dada como morta. Chamava-se\nRuby Halloran.\nA Imprensa é a facção que não atira: fotografa. Repórteres que chegam antes da polícia, fotógrafos que\nvendem o mesmo negativo duas vezes, paparazzi nos muros de White Hills, redatores pagos por linha\npara escrever notícias falsas.\nO S B R A Ç O S D O T I O S A M\nO Tio Sam não sai do hipódromo, mas está em toda a cidade. Cada bairro tem alguém que responde a ele.\nO n d e  · O b r a ç o  · C o m o o p e r a\nPrefeitura  · Vereador Carl Benedetti  · Atrasa as licenças da Petrolífera até ela pagar\npedágio\nDelegacia Central  · Sargento Lou Pacino, da Narcóticos  · Avisa das batidas e escolhe quem é preso\nSaint Edwiges  · Vinnie Ascoli, gerente da Savoy  · Cobra o aluguel da Strip e conta quem cheira com\nquem\nChinatown  · Tony Kwan, dos 14 Dragões  · Recebe armas dos Moretti para enfraquecer o\nLótus Vermelho\nEmbarcadouro  · Um contador da Bratva, preso numa baia do\nhipódromo\nFala, aos poucos, em troca de continuar vivo\nDistrito de\nWaterford\nMikey Riordan, sobrinho-neto  · Mantém o bairro calmo enquanto o tio decide o\npreço da terra\nMonumental Island Lou Cassidy, gerente do cassino  · Lava o dinheiro e guarda as fotografias dos\nquartos\nA Imprensa  · Um editor do Flagrante  · Publica o escândalo de quem o Tio Sam escolhe\nWhite Hills  · Bunny Lyman  · Conta ao Tio Sam o que o marido diz em casa\nR E G I Õ E S E M P R O F U N D I D A D E"}};